package com.yvesds.vt5.ai

/**
 * AiConfig - Centrale configuratie voor de AI-motor.
 * Bevat de 21 meteorologische referentiepunten voor Europese migratie.
 */
object AiConfig {

    data class RefPoint(val name: String, val lat: Double, val lon: Double)

    // 21 Strategische locaties voor najaar- en voorjaarstrek
    val REFERENCE_POINTS = listOf(
        // NOORD (Najaar bronnen)
        RefPoint("Falsterbo (SE)", 55.38, 12.83),
        RefPoint("Skagen (DK)", 57.72, 10.58),
        RefPoint("Blåvand (DK)", 55.55, 8.08),
        RefPoint("Helgoland (DE)", 54.18, 7.88),
        RefPoint("Sylt (DE)", 54.91, 8.30),
        RefPoint("Borkum (DE)", 53.58, 6.66),
        RefPoint("Texel (NL)", 53.05, 4.80),
        RefPoint("Lauwersmeer (NL)", 53.38, 6.19),
        RefPoint("IJmuiden (NL)", 52.46, 4.56),
        RefPoint("Gdansk (PL)", 54.35, 18.64),

        // ZUID (Voorjaar bronnen)
        RefPoint("Cap Gris-Nez (FR)", 50.87, 1.58),
        RefPoint("Baie de Somme (FR)", 50.21, 1.62),
        RefPoint("Ouistreham (FR)", 49.28, -0.25),
        RefPoint("Île d'Oléron (FR)", 45.91, -1.30),
        RefPoint("Biarritz (FR)", 43.48, -1.56),
        RefPoint("Tarifa (ES)", 36.01, -5.60),
        RefPoint("Gibraltar (UK)", 36.14, -5.35),
        RefPoint("Sagres (PT)", 37.01, -8.94),
        RefPoint("Camargue (FR)", 43.53, 4.65),
        RefPoint("Mallorca (ES)", 39.69, 3.01),
        RefPoint("Messina (IT)", 38.19, 15.55)
    )

    // BSI 4.0: Anchor Sites met uurs-precisie (Lijst van telpostid's)
    val ANCHOR_SITE_IDS = listOf("site_1", "site_2") // Wordt dynamisch aangevuld of via settings

    // BSI 4.0: Drempels voor Birds-of-Interest
    const val BOI_THRESHOLD_OBSERVATIONS = 50 // Minder dan 50 waarnemingen in 23 jaar = BoI
    const val BOI_FLOATING_WINDOW_DAYS = 9
    const val NORMAL_FLOATING_WINDOW_DAYS = 7
    const val WIND_TOLERANCE_DEGREES = 11.25

    // BSI 4.1: Kust-status & Drempels
    const val IS_COASTAL_SITE = true // TODO: Dynamisch maken op basis van siteId
    const val MIN_BSI_QUALITY_THRESHOLD = 30 // Verlaagd van 35. Soorten onder de 30% worden gefilterd
    const val EFFICIENCY_BOOST_PELAGIC_BFT = 4 // Vanaf 4bft (WNW) al lichte boost voor zeevogels, sterker bij 5+

    // Neural model integration
    const val USE_NEURAL_INFERENCE = true
    const val NEURAL_INTEGRATION_WEIGHT = 0.5 // Hoe sterk de NN voorspelling weegt t.o.v. heuristiek (0.0 - 1.0)

    // Gebruik teldag-verslagen om trainings-voorvallen te wegen (voor prototype/experiment)
    const val USE_DAILY_ANALYSIS_WEIGHTS = true
    const val DAILY_ANALYSIS_LOOKBACK_DAYS = 365 // Kijk terug over deze many days bij berekenen van gewichten
    const val DAILY_ANALYSIS_WEIGHT_MAX = 3.0f // Maximale multiplicatieve boost per soort (>=1.0)
    fun getSampleWeightForSpecies(soortid: String?): Int {
        if (soortid == null) return 1
        return 1
    }

    // Display & selection limits (centralized configuration)
    // Top-N per guild to expose in suggestions and reports
    const val GUILD_TOP_N = 5 // Top-5 per guild

    // Birds-of-Interest (krenten) shown above all and limited to this many
    const val BOI_TOP_N = 3 // Top-3 krenten

    // Maximum species to show per day in the +3 day forecast UI
    const val MAX_SPECIES_PER_DAY = 30
    const val MAX_SPECIES_FOR_3DAY = MAX_SPECIES_PER_DAY * 3

    // Passerine (zangvogels) inclusion guard: if no passerine has a probability
    // >= this value, do not force/include passerines in the forecast lists
    const val PASSERINES_MIN_PERCENT_TO_INCLUDE = 30
}

package com.yvesds.vt5.ai

import android.content.Context
import android.graphics.Color
import android.graphics.Typeface
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.GridLayout
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.card.MaterialCardView
import com.yvesds.vt5.R
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.dao.DayCountRowClean
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.core.ui.ProgressDialogHelper
import com.yvesds.vt5.utils.weather.WeatherManager
import com.yvesds.vt5.utils.weather.Current
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.*
import kotlin.math.*

/**
 * [STABLE_AI_FORECAST_V2 - 24 AUG 2026]
 * Scherm voor het tonen van de 3-daagse AI-prognose.
 * Gebruikt de wetenschappelijke standaard (BSI Kans, Norm, Pieken & Sparklines).
 */
class AiForecastScherm : AppCompatActivity() {

    private lateinit var database: VoiceTallyDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.scherm_ai_forecast)

        database = VoiceTallyDatabase.getDatabase(this)

        findViewById<com.google.android.material.button.MaterialButton>(R.id.btnClose).setOnClickListener {
            finish()
        }

        loadForecast()
    }

    private fun loadForecast() {
        lifecycleScope.launch {
            val progress = ProgressDialogHelper.show(this@AiForecastScherm, "AI berekent 3-daagse prognose...")

            try {
                val loc = WeatherManager.getLastKnownLocation(this@AiForecastScherm)
                if (loc == null) {
                    showError("Geen locatie beschikbaar"); progress.dismiss(); return@launch
                }

                // 1. HAAL WEERSVERWACHTING OP
                val hourlyData = WeatherManager.fetch72HourForecast(loc.latitude, loc.longitude)
                if (hourlyData == null || hourlyData.isEmpty()) {
                    showError("Kon weersverwachting niet ophalen"); progress.dismiss(); return@launch
                }

                // BEPAAL CLUSTER ÉÉN KEER (Analoog aan verslagen)
                val saf = SaFStorageHelper(this@AiForecastScherm)
                val clusterIds = withContext(Dispatchers.IO) {
                    try {
                        val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
                        val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)
                        val primarySite = root.locaties.firstOrNull()
                        if (primarySite != null) {
                            root.locaties.filter { 
                                val r = 6371.0
                                val dLat = Math.toRadians(it.latitude - primarySite.latitude)
                                val dLon = Math.toRadians(it.longitude - primarySite.longitude)
                                val a = sin(dLat/2).pow(2) + cos(Math.toRadians(primarySite.latitude)) * cos(Math.toRadians(it.latitude)) * sin(dLon/2).pow(2)
                                r * 2 * atan2(sqrt(a), sqrt(1 - a)) <= 35.0 
                            }.map { it.telpostid }
                        } else emptyList()
                    } catch(_: Exception) { emptyList() }
                }

                val container = findViewById<ViewGroup>(R.id.forecastContainer)
                container.removeAllViews()

                val sdf = SimpleDateFormat("EEEE d MMMM", Locale("nl", "BE"))
                val dailySnapshots = hourlyData.filter { it.time.endsWith("T10:00") }

                // 2. CORRIDOR VOORSPELLING OPHALEN
                val calNow = Calendar.getInstance()
                val isAutumn = (calNow.get(Calendar.MONTH) + 1) in 7..11
                val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)
                val corridorForecast = withContext(Dispatchers.IO) { WeatherManager.fetchCorridorForecast(points) }

                for (snapshot in dailySnapshots) {
                    val dayView = LayoutInflater.from(this@AiForecastScherm).inflate(R.layout.item_ai_forecast_day, container, false)

                    // TABLET OPTIMALISATIE: Breedte verdelen in het raster
                    if (container is android.widget.GridLayout) {
                        val gridParams = android.widget.GridLayout.LayoutParams()
                        gridParams.width = 0
                        gridParams.columnSpec = android.widget.GridLayout.spec(android.widget.GridLayout.UNDEFINED, 1f)
                        gridParams.setMargins(8, 8, 8, 8)
                        dayView.layoutParams = gridParams
                    }

                    val dateParts = snapshot.time.split("T")[0].split("-")
                    val snapshotCal = Calendar.getInstance().apply {
                        set(dateParts[0].toInt(), dateParts[1].toInt() - 1, dateParts[2].toInt())
                    }

                    dayView.findViewById<TextView>(R.id.tvDayTitle).text = sdf.format(snapshotCal.time).replaceFirstChar { it.uppercase() }
                    val bft = WeatherManager.msToBeaufort(snapshot.windSpeed)
                    val windLabel = WeatherManager.degTo16WindLabel(snapshot.windDeg)
                    val temp = snapshot.temp?.roundToInt() ?: "?"
                    dayView.findViewById<TextView>(R.id.tvWeatherSummary).text = "Verwachting 10:00u | Wind: $windLabel ${bft}bft | Temp: ${temp}°C"

                    // Bepaal corridor boost voor deze specifieke toekomstige dag
                    val regBoost = calculateCorridorBoostAtTime(snapshot.time, corridorForecast, isAutumn)

                    // Voer AI Inference uit voor deze dag (Twee modi: Baseline zonder Neural, En met Neural)
                    val pseudoCurrent = Current(temperature2m = snapshot.temp, windSpeed10m = snapshot.windSpeed, windDirection10m = snapshot.windDeg)
                    val aiBaseline = AiInferenceEngine.getSuggesties(this@AiForecastScherm, pseudoCurrent, 10, providedRegBoost = regBoost, useNeural = false)
                    val aiWithNeural = AiInferenceEngine.getSuggesties(this@AiForecastScherm, pseudoCurrent, 10, providedRegBoost = regBoost, useNeural = true)

                    val baselineMap = aiBaseline.guildResults.associateBy { it.soortid }
                    val withMap = aiWithNeural.guildResults.associateBy { it.soortid }
                    val allIds = (baselineMap.keys + withMap.keys).toList()

                    val speciesGrid = dayView.findViewById<GridLayout>(R.id.speciesGrid)
                    val isTablet = resources.configuration.smallestScreenWidthDp >= 600
                    if (speciesGrid != null) {
                        speciesGrid.columnCount = if (isTablet) 2 else 1

                        // Combineer en sorteer op de hoogste van beide kansen, filter > 5% in minstens één model en neem Top-12
                        val combined = allIds.map { id ->
                            val b = baselineMap[id]
                            val w = withMap[id]
                            val maxProb = max(b?.kans ?: 0, w?.kans ?: 0)
                            Triple(id, maxProb, Pair(b, w))
                        }
                            .filter { it.second > 5 }
                            .sortedByDescending { it.second }
                            .take(12)

                        for ((id, _, pair) in combined) {
                            val b = pair.first
                            val w = pair.second
                            val specView = createComparativeSpeciesCard(b, w, snapshotCal, clusterIds)

                            if (isTablet) {
                                val gridParams = GridLayout.LayoutParams()
                                gridParams.width = 0
                                gridParams.columnSpec = GridLayout.spec(GridLayout.UNDEFINED, 1f)
                                specView.layoutParams = gridParams
                            }

                            speciesGrid.addView(specView)
                        }
                    }

                    container.addView(dayView)
                }

            } catch (e: Exception) {
                showError("Fout bij berekenen prognose: ${e.message}")
            } finally {
                progress.dismiss()
            }
        }
    }

    private suspend fun createSpeciesCard(item: VogelSuggestie, targetDate: Calendar, clusterIds: List<String>): View {
        val view = LayoutInflater.from(this).inflate(R.layout.item_forecast_species, null)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = item.guildName
        tvName.text = item.soortnaam

        // BSI Kans & Norm
        val norm = item.expectedIndex ?: 0f
        view.findViewById<TextView>(R.id.tvProbability).text = "${item.kans}%"
        tvScientific.text = "BSI Kans: ${item.kans}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Foto
        if (!item.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(item.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(item.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(item.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator op de voorspelde week
            val weekOfYear = targetDate.get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        view.findViewById<MaterialCardView>(R.id.cardSpecies).strokeColor = getGuildColor(item.guildName)
        return view
    }

    /**
     * Creëert een vergelijkende kaart die laat zien welke kansen elk model gaf.
     */
    private suspend fun createComparativeSpeciesCard(
        baseline: VogelSuggestie?,
        experimental: VogelSuggestie?,
        targetDate: Calendar,
        clusterIds: List<String>
    ): View {
        val primary = experimental ?: baseline ?: return createSpeciesCard(baseline ?: experimental!!, targetDate, clusterIds)
        val view = LayoutInflater.from(this).inflate(R.layout.item_forecast_species, null)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val tvSources = view.findViewById<TextView>(R.id.tvModelSources)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = primary.guildName
        tvName.text = primary.soortnaam

        val norm = primary.expectedIndex ?: 0f
        // Compose probability display
        val bProb = baseline?.kans ?: 0
        val eProb = experimental?.kans ?: 0
        view.findViewById<TextView>(R.id.tvProbability).text = "H:${bProb}%   P:${eProb}%"
        tvScientific.text = "BSI Kans: ${max(bProb, eProb)}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Sources line (clear labels)
        val sources = mutableListOf<String>()
        if (baseline != null) sources.add("Heuristiek")
        if (experimental != null) sources.add("Prototype")
        tvSources.text = "Bronnen: ${sources.joinToString(" / ")}"

        // Foto
        if (!primary.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(primary.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(primary.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(primary.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator op de voorspelde week
            val weekOfYear = targetDate.get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        view.findViewById<MaterialCardView>(R.id.cardSpecies).strokeColor = getGuildColor(primary.guildName)
        return view
    }

    private fun calculatePeak(dayCounts: List<DayCountRowClean>): String {
        if (dayCounts.isEmpty()) return "onbekend"
        val maxRow = dayCounts.maxByOrNull { it.count } ?: return "onbekend"
        if (maxRow.count <= 0L) return "onbekend"
        val threshold = maxRow.count * 0.5
        val window = dayCounts.filter { it.count >= threshold }
        val sdf = SimpleDateFormat("d MMM", Locale("nl", "BE"))
        val calS = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.first().day) }
        val calE = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.last().day) }
        return if (window.first().day == window.last().day) sdf.format(calS.time) else "${sdf.format(calS.time)} - ${sdf.format(calE.time)}"
    }

    private fun getGuildColor(guildName: String): Int {
        return when {
            guildName.contains("Zang") -> Color.CYAN
            guildName.contains("Roof") -> Color.YELLOW
            guildName.contains("Reiger") -> Color.GREEN
            guildName.contains("Zee") -> Color.MAGENTA
            guildName.contains("Stelt") -> Color.parseColor("#FF9800")
            guildName.contains("Water") -> Color.parseColor("#4FC3F7")
            guildName.contains("Kust") -> Color.parseColor("#009688")
            else -> Color.parseColor("#333333")
        }
    }

    private fun calculateCorridorBoostAtTime(targetTime: String, forecast: Map<String, List<WeatherManager.HourlyForecast>>, isAutumn: Boolean): Double {
        val formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")
        val targetDt = java.time.LocalDateTime.parse(targetTime, formatter)

        var totalMaxScore = 0.0
        forecast.forEach { (_, hourly) ->
            val windowHours = hourly.filter { 
                try {
                    val dt = java.time.LocalDateTime.parse(it.time, formatter)
                    dt.isAfter(targetDt.minusHours(6)) && dt.isBefore(targetDt.plusHours(1))
                } catch (_: Exception) { false }
            }
            val bestInWindow = windowHours.maxOfOrNull { entry ->
                val cur = Current(temperature2m = entry.temp, windSpeed10m = entry.windSpeed, windDirection10m = entry.windDeg)
                AiInferenceEngine.calculateSinglePointScore(cur, isAutumn)
            } ?: 0.0
            totalMaxScore += bestInWindow
        }
        return if (forecast.isEmpty()) 0.0 else totalMaxScore / forecast.size
    }

    private fun showError(msg: String) {
        val container = findViewById<LinearLayout>(R.id.forecastContainer)
        val tv = TextView(this)
        tv.text = msg; tv.setTextColor(getColor(R.color.vt5_red))
        container.addView(tv)
    }
}

package com.yvesds.vt5.ai

import android.content.Context
import android.graphics.Color
import android.graphics.Typeface
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.GridLayout
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.card.MaterialCardView
import com.yvesds.vt5.R
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.dao.DayCountRowClean
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.core.ui.ProgressDialogHelper
import com.yvesds.vt5.utils.weather.WeatherManager
import com.yvesds.vt5.utils.weather.Current
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.*
import kotlin.math.*

/**
 * [STABLE_AI_FORECAST_V2 - 24 AUG 2026]
 * Scherm voor het tonen van de 3-daagse AI-prognose.
 * Gebruikt de wetenschappelijke standaard (BSI Kans, Norm, Pieken & Sparklines).
 */
class AiForecastScherm : AppCompatActivity() {

    private lateinit var database: VoiceTallyDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.scherm_ai_forecast)

        database = VoiceTallyDatabase.getDatabase(this)

        findViewById<com.google.android.material.button.MaterialButton>(R.id.btnClose).setOnClickListener {
            finish()
        }

        loadForecast()
    }

    private fun loadForecast() {
        lifecycleScope.launch {
            val progress = ProgressDialogHelper.show(this@AiForecastScherm, "AI berekent 3-daagse prognose...")

            try {
                val loc = WeatherManager.getLastKnownLocation(this@AiForecastScherm)
                if (loc == null) {
                    showError("Geen locatie beschikbaar"); progress.dismiss(); return@launch
                }

                // 1. HAAL WEERSVERWACHTING OP
                val hourlyData = WeatherManager.fetch72HourForecast(loc.latitude, loc.longitude)
                if (hourlyData == null || hourlyData.isEmpty()) {
                    showError("Kon weersverwachting niet ophalen"); progress.dismiss(); return@launch
                }

                // BEPAAL CLUSTER ÉÉN KEER (Analoog aan verslagen)
                val saf = SaFStorageHelper(this@AiForecastScherm)
                val clusterIds = withContext(Dispatchers.IO) {
                    try {
                        val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
                        val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)
                        val primarySite = root.locaties.firstOrNull()
                        if (primarySite != null) {
                            root.locaties.filter { 
                                val r = 6371.0
                                val dLat = Math.toRadians(it.latitude - primarySite.latitude)
                                val dLon = Math.toRadians(it.longitude - primarySite.longitude)
                                val a = sin(dLat/2).pow(2) + cos(Math.toRadians(primarySite.latitude)) * cos(Math.toRadians(it.latitude)) * sin(dLon/2).pow(2)
                                r * 2 * atan2(sqrt(a), sqrt(1 - a)) <= 35.0 
                            }.map { it.telpostid }
                        } else emptyList()
                    } catch(_: Exception) { emptyList() }
                }

                val container = findViewById<ViewGroup>(R.id.forecastContainer)
                container.removeAllViews()

                val sdf = SimpleDateFormat("EEEE d MMMM", Locale("nl", "BE"))
                val dailySnapshots = hourlyData.filter { it.time.endsWith("T10:00") }

                // 2. CORRIDOR VOORSPELLING OPHALEN
                val calNow = Calendar.getInstance()
                val isAutumn = (calNow.get(Calendar.MONTH) + 1) in 7..11
                val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)
                val corridorForecast = withContext(Dispatchers.IO) { WeatherManager.fetchCorridorForecast(points) }

                for (snapshot in dailySnapshots) {
                    val dayView = LayoutInflater.from(this@AiForecastScherm).inflate(R.layout.item_ai_forecast_day, container, false)

                    // TABLET OPTIMALISATIE: Breedte verdelen in het raster
                    if (container is android.widget.GridLayout) {
                        val gridParams = android.widget.GridLayout.LayoutParams()
                        gridParams.width = 0
                        gridParams.columnSpec = android.widget.GridLayout.spec(android.widget.GridLayout.UNDEFINED, 1f)
                        gridParams.setMargins(8, 8, 8, 8)
                        dayView.layoutParams = gridParams
                    }

                    val dateParts = snapshot.time.split("T")[0].split("-")
                    val snapshotCal = Calendar.getInstance().apply {
                        set(dateParts[0].toInt(), dateParts[1].toInt() - 1, dateParts[2].toInt())
                    }

                    dayView.findViewById<TextView>(R.id.tvDayTitle).text = sdf.format(snapshotCal.time).replaceFirstChar { it.uppercase() }
                    val bft = WeatherManager.msToBeaufort(snapshot.windSpeed)
                    val windLabel = WeatherManager.degTo16WindLabel(snapshot.windDeg)
                    val temp = snapshot.temp?.roundToInt() ?: "?"
                    dayView.findViewById<TextView>(R.id.tvWeatherSummary).text = "Verwachting 10:00u | Wind: $windLabel ${bft}bft | Temp: ${temp}°C"

                    // Bepaal corridor boost voor deze specifieke toekomstige dag
                    val regBoost = calculateCorridorBoostAtTime(snapshot.time, corridorForecast, isAutumn)

                    // Voer AI Inference uit voor deze dag (Twee modi: Baseline zonder Neural, En met Neural)
                    val pseudoCurrent = Current(temperature2m = snapshot.temp, windSpeed10m = snapshot.windSpeed, windDirection10m = snapshot.windDeg)
                    val aiBaseline = AiInferenceEngine.getSuggesties(this@AiForecastScherm, pseudoCurrent, 10, providedRegBoost = regBoost, useNeural = false)
                    val aiWithNeural = AiInferenceEngine.getSuggesties(this@AiForecastScherm, pseudoCurrent, 10, providedRegBoost = regBoost, useNeural = true)

                    val baselineMap = aiBaseline.guildResults.associateBy { it.soortid }
                    val withMap = aiWithNeural.guildResults.associateBy { it.soortid }
                    val allIds = (baselineMap.keys + withMap.keys).toList()

                    val speciesGrid = dayView.findViewById<GridLayout>(R.id.speciesGrid)
                    val isTablet = resources.configuration.smallestScreenWidthDp >= 600
                    if (speciesGrid != null) {
                        speciesGrid.columnCount = if (isTablet) 2 else 1

                        // Combineer en sorteer op de hoogste van beide kansen.
                        // Prioriteiten en limieten zijn centraal configureerbaar via AiConfig:
                        // - Top BOI (krenten) eerst (AiConfig.BOI_TOP_N)
                        // - Maximaal AiConfig.MAX_SPECIES_PER_DAY per dag
                        val maxPerDay = AiConfig.MAX_SPECIES_PER_DAY

                        val candidates = allIds.map { id ->
                            val b = baselineMap[id]
                            val w = withMap[id]
                            val maxProb = max(b?.kans ?: 0, w?.kans ?: 0)
                            Triple(id, maxProb, Pair(b, w))
                        }.filter { it.second > 0 }

                        // BOI (krenten) ids from both models
                        val boiIds = (aiBaseline.rareHighlights.map { it.soortid } + aiWithNeural.rareHighlights.map { it.soortid }).distinct()

                        // Map for quick lookup
                        val candidateById = candidates.associateBy { it.first }

                        // Build BOI triples (fall back to rareHighlights values if absent in candidateById)
                        val boiTriples = boiIds.mapNotNull { id ->
                            candidateById[id] ?: run {
                                // try to recover probability from the rareHighlights lists
                                val r = aiBaseline.rareHighlights.find { it.soortid == id } ?: aiWithNeural.rareHighlights.find { it.soortid == id }
                                if (r != null) Triple(id, r.kans, Pair(null, null)) else null
                            }
                        }.sortedByDescending { it.second }

                        // Determine whether passerines should be included (only if at least one passerine is >= threshold)
                        val passersAllowed = candidates.any { triple ->
                            val guildName = triple.third.first?.guildName ?: triple.third.second?.guildName ?: ""
                            guildName.contains("Zang") && triple.second >= AiConfig.PASSERINES_MIN_PERCENT_TO_INCLUDE
                        }

                        val finalList = mutableListOf<Triple<String, Int, Pair<VogelSuggestie?, VogelSuggestie?>>>()

                        // Add BOIs first (always included)
                        for (t in boiTriples) {
                            if (finalList.size >= maxPerDay) break
                            finalList.add(t)
                        }

                        // Add remaining candidates sorted by probability, skipping duplicates and optionally passerines
                        val remaining = candidates.sortedByDescending { it.second }
                        for (t in remaining) {
                            if (finalList.size >= maxPerDay) break
                            if (boiIds.contains(t.first)) continue // already added

                            val guildName = t.third.first?.guildName ?: t.third.second?.guildName ?: ""
                            val isPasserine = guildName.contains("Zang")
                            if (isPasserine && !passersAllowed) continue

                            finalList.add(t)
                        }

                        // Render final list
                        for ((id, _, pair) in finalList) {
                            val b = pair.first
                            val w = pair.second
                            val specView = createComparativeSpeciesCard(b, w, snapshotCal, clusterIds)

                            if (isTablet) {
                                val gridParams = GridLayout.LayoutParams()
                                gridParams.width = 0
                                gridParams.columnSpec = GridLayout.spec(GridLayout.UNDEFINED, 1f)
                                specView.layoutParams = gridParams
                            }

                            speciesGrid.addView(specView)
                        }
                    }

                    container.addView(dayView)
                }

            } catch (e: Exception) {
                showError("Fout bij berekenen prognose: ${e.message}")
            } finally {
                progress.dismiss()
            }
        }
    }

    private suspend fun createSpeciesCard(item: VogelSuggestie, targetDate: Calendar, clusterIds: List<String>): View {
        val view = LayoutInflater.from(this).inflate(R.layout.item_forecast_species, null)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = item.guildName
        tvName.text = item.soortnaam

        // BSI Kans & Norm
        val norm = item.expectedIndex ?: 0f
        view.findViewById<TextView>(R.id.tvProbability).text = "${item.kans}%"
        tvScientific.text = "BSI Kans: ${item.kans}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Foto
        if (!item.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(item.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(item.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(item.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator op de voorspelde week
            val weekOfYear = targetDate.get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        view.findViewById<MaterialCardView>(R.id.cardSpecies).strokeColor = getGuildColor(item.guildName)
        return view
    }

    /**
     * Creëert een vergelijkende kaart die laat zien welke kansen elk model gaf.
     */
    private suspend fun createComparativeSpeciesCard(
        baseline: VogelSuggestie?,
        experimental: VogelSuggestie?,
        targetDate: Calendar,
        clusterIds: List<String>
    ): View {
        val primary = experimental ?: baseline ?: return createSpeciesCard(baseline ?: experimental!!, targetDate, clusterIds)
        val view = LayoutInflater.from(this).inflate(R.layout.item_forecast_species, null)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val tvSources = view.findViewById<TextView>(R.id.tvModelSources)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = primary.guildName
        tvName.text = primary.soortnaam

        val norm = primary.expectedIndex ?: 0f
        // Compose probability display
        val bProb = baseline?.kans ?: 0
        val eProb = experimental?.kans ?: 0
        view.findViewById<TextView>(R.id.tvProbability).text = "H:${bProb}%   P:${eProb}%"
        tvScientific.text = "BSI Kans: ${max(bProb, eProb)}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Sources line (clear labels)
        val sources = mutableListOf<String>()
        if (baseline != null) sources.add("Heuristiek")
        if (experimental != null) sources.add("Prototype")
        tvSources.text = "Bronnen: ${sources.joinToString(" / ")}"

        // Foto
        if (!primary.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(primary.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(primary.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(primary.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator op de voorspelde week
            val weekOfYear = targetDate.get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        view.findViewById<MaterialCardView>(R.id.cardSpecies).strokeColor = getGuildColor(primary.guildName)
        return view
    }

    private fun calculatePeak(dayCounts: List<DayCountRowClean>): String {
        if (dayCounts.isEmpty()) return "onbekend"
        val maxRow = dayCounts.maxByOrNull { it.count } ?: return "onbekend"
        if (maxRow.count <= 0L) return "onbekend"
        val threshold = maxRow.count * 0.5
        val window = dayCounts.filter { it.count >= threshold }
        val sdf = SimpleDateFormat("d MMM", Locale("nl", "BE"))
        val calS = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.first().day) }
        val calE = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.last().day) }
        return if (window.first().day == window.last().day) sdf.format(calS.time) else "${sdf.format(calS.time)} - ${sdf.format(calE.time)}"
    }

    private fun getGuildColor(guildName: String): Int {
        return when {
            guildName.contains("Zang") -> Color.CYAN
            guildName.contains("Roof") -> Color.YELLOW
            guildName.contains("Reiger") -> Color.GREEN
            guildName.contains("Zee") -> Color.MAGENTA
            guildName.contains("Stelt") -> Color.parseColor("#FF9800")
            guildName.contains("Water") -> Color.parseColor("#4FC3F7")
            guildName.contains("Kust") -> Color.parseColor("#009688")
            else -> Color.parseColor("#333333")
        }
    }

    private fun calculateCorridorBoostAtTime(targetTime: String, forecast: Map<String, List<WeatherManager.HourlyForecast>>, isAutumn: Boolean): Double {
        val formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")
        val targetDt = java.time.LocalDateTime.parse(targetTime, formatter)

        var totalMaxScore = 0.0
        forecast.forEach { (_, hourly) ->
            val windowHours = hourly.filter { 
                try {
                    val dt = java.time.LocalDateTime.parse(it.time, formatter)
                    dt.isAfter(targetDt.minusHours(6)) && dt.isBefore(targetDt.plusHours(1))
                } catch (_: Exception) { false }
            }
            val bestInWindow = windowHours.maxOfOrNull { entry ->
                val cur = Current(temperature2m = entry.temp, windSpeed10m = entry.windSpeed, windDirection10m = entry.windDeg)
                AiInferenceEngine.calculateSinglePointScore(cur, isAutumn)
            } ?: 0.0
            totalMaxScore += bestInWindow
        }
        return if (forecast.isEmpty()) 0.0 else totalMaxScore / forecast.size
    }

    private fun showError(msg: String) {
        val container = findViewById<LinearLayout>(R.id.forecastContainer)
        val tv = TextView(this)
        tv.text = msg; tv.setTextColor(getColor(R.color.vt5_red))
        container.addView(tv)
    }
}

package com.yvesds.vt5.ai

import android.content.Context
import android.util.Log
import com.yvesds.vt5.VT5App
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.entities.AiLog
import com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot
import com.yvesds.vt5.core.database.ui.SpeciesNameResolver
import com.yvesds.vt5.core.opslag.EffortManager
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.features.serverdata.model.ServerDataCache
import com.yvesds.vt5.utils.weather.Current
import com.yvesds.vt5.utils.weather.WeatherManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import java.util.*
import kotlin.math.*
import com.yvesds.vt5.core.opslag.AppDataStore

/**
 * AiInferenceEngine - Expert Deep Diagnostic & Live Corridor Edition.
 * Nu met Zelf-ontdekkende Krenten op basis van de ExpertKnowledgeBase.
 */
object AiInferenceEngine {
    private const val TAG = "AiInference"

    suspend fun getSuggesties(
        context: Context,
        cur: Current,
        hourOverride: Int? = null,
        providedRegBoost: Double? = null,
        useNeural: Boolean? = null
    ): AiSuggestieData = withContext(Dispatchers.IO) {
        Log.i(TAG, "=========================================================")
        Log.i(TAG, "START SCIENTIFIC AI ANALYSIS")

        val db = VoiceTallyDatabase.getDatabase(context)
        val dao = db.tellingDao()
        val saf = SaFStorageHelper(context)

        // Laad alle AI Kennis (JSON of Binair met Auto-Sync)
        val snapshot = try { ServerDataCache.getOrLoad(context) } catch (_: Exception) { null }
        val modelStore = ModelStore(context)
        val expertKB = loadExpertKnowledge(modelStore)

        val cal = Calendar.getInstance()
        val currentHour = hourOverride ?: cal.get(Calendar.HOUR_OF_DAY)
        cal.set(Calendar.HOUR_OF_DAY, currentHour); cal.set(Calendar.MINUTE, 0)
        val dayOfYear = cal.get(Calendar.DAY_OF_YEAR)
        val month = cal.get(Calendar.MONTH) + 1

        val loc = WeatherManager.getLastKnownLocation(context)
        val lat = loc?.latitude ?: 51.0
        val lon = loc?.longitude ?: 3.0

        val currentWindDeg = cur.windDirection10m ?: 0.0
        val currentWindLabel = WeatherManager.degTo16WindLabel(currentWindDeg)
        val currentTemp = (cur.temperature2m ?: 15.0).toFloat()

        // BEPAAL CLUSTER GEANKERD AAN DE HOOFDTELPOST (Eerste in JSON)
        val cluster = withContext(Dispatchers.IO) {
            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
            val root = VT5App.json.decodeFromString<TelpostLocatiesRoot>(jsonStr)
            val primarySite = root.locaties.firstOrNull()
            if (primarySite != null) {
                root.locaties.filter { calculateDistance(primarySite.latitude, primarySite.longitude, it.latitude, it.longitude) <= 35.0 }
                    .map { it.telpostid }
            } else {
                getLocalSiteCluster(saf, lat, lon)
            }
        }

        val phase = SolarTimeEngine.getSolarPhase(lat, lon, cal)

        // 1. LIVE REGIONALE CORRIDOR CHECK (Tenzij boost al gegeven is)
        val regBoost = providedRegBoost ?: getLiveCorridorBoost(month)

        // 2. Data ophalen: BSI 4.0 Dynamic Mining
        val effortHours = EffortManager.getClusterEffortHours(context, cluster ?: emptyList())

        // Bepaal venster grootte (BoI's krijgen 9 dagen, anderen 7)
        // Voor de initiële fetch gebruiken we 9 dagen om zeker te zijn
        val window = AiConfig.BOI_FLOATING_WINDOW_DAYS
        val dayStart = dayOfYear - (window / 2)
        val dayEnd = dayOfYear + (window / 2)

        // Weather Twin Mining: Zoek uren met exact dezelfde wind-signatuur (+/- 5.25 graden)
        // Omdat we in de DAO op Label matchen (N, NO), mappen we de huidige graden naar label
        val weatherTwins = dao.getWeatherTwinObservations(cluster ?: emptyList(), dayStart, dayEnd, currentWindLabel)

        // BSI 4.1: Haal wind-efficiëntie data op (alle windstreken in dit venster)
        val windStats = dao.getWindEfficiencyStats(cluster ?: emptyList(), dayStart, dayEnd)
            .groupBy { it.soortid }

        val profiles = dao.getSpeciesPhenologyProfile(dayStart, dayEnd, cluster ?: emptyList(), if (cluster == null) 0 else 1)

        val clusterIndices = if (cluster != null) {
            dao.getSpeciesGigaBaseline(cluster, effortHours).associateBy { it.soortid }
        } else emptyMap()

        // Neural model: probeer labels en model te laden en maak één predictie voor de huidige context
        val effectiveUseNeural = if (useNeural != null) {
            useNeural
        } else {
            // Read runtime override from DataStore (default true)
            try { AppDataStore.isUseNeuralInference(context) } catch (e: Exception) { AiConfig.USE_NEURAL_INFERENCE }
        }
        Log.i(TAG, "Neural inference enabled (effective): $effectiveUseNeural")

        // Daily-analysis based weighting: read runtime override and compute species weights if enabled
        val effectiveUseDailyWeights = try { AppDataStore.isUseDailyAnalysisWeights(context) } catch (e: Exception) { AiConfig.USE_DAILY_ANALYSIS_WEIGHTS }
        var dailySpeciesWeights: Map<String, Float> = emptyMap()
        if (effectiveUseDailyWeights) {
            try {
                val preparer = TrainingDataPreparer(context)
                dailySpeciesWeights = preparer.computeSpeciesWeightsFromDailyAnalysis()
                Log.i(TAG, "Computed daily-analysis species weights: ${dailySpeciesWeights.size} entries")
            } catch (e: Exception) {
                Log.w(TAG, "Failed to compute daily-analysis weights: ${e.message}")
                dailySpeciesWeights = emptyMap()
            }
        }
        val modelLabels = modelStore.loadModelLabels()
        var neuralPredictions: FloatArray? = null
        if (!modelLabels.isNullOrEmpty() && effectiveUseNeural) {
            try {
                val neural = modelStore.loadNeuralEngine(modelLabels.size)
                // Bouw feature-vector voor de huidige situatie (best effort)
                val siteId = cluster?.firstOrNull()
                val preparer = TrainingDataPreparer(context)
                val epochSec = cal.timeInMillis / 1000L
                val features = preparer.buildFeatureVectorForContext(
                    epoch = epochSec,
                    telpostId = siteId,
                    temperature = cur.temperature2m,
                    windDeg = cur.windDirection10m,
                    windForce = cur.windSpeed10m,
                    cloudCover = null,
                    hpa = cur.pressureMsl,
                    precipitationFlag = null
                )
                neuralPredictions = neural.predict(features)
                Log.i(TAG, "Neural integration: loaded model with ${neuralPredictions.size} outputs.")
            } catch (e: Exception) {
                Log.w(TAG, "Neural integration failed: ${e.message}")
            }
        }

        // 3. Score berekening
        val scoredList = profiles.mapNotNull { p ->
            val speciesData = snapshot?.speciesById?.get(p.soortid)
            val latin = speciesData?.latin
            val name = speciesData?.soortnaam ?: SpeciesNameResolver.getName(context, p.soortid)

            if (name.lowercase().contains("spec.") || 
                name.lowercase().contains("onbekend") || 
                name.contains("/")) return@mapNotNull null

            val guild = SpeciesGuildMapper.getGuildByLatin(latin)
            if (guild == SpeciesGuildMapper.Guild.OTHER) return@mapNotNull null
            val strategy = guild.strategy

            // BSI 4.0: BoI Check & Window
            val totalObs = clusterIndices[p.soortid]?.activePosts ?: 0
            val isBoI = totalObs < AiConfig.BOI_THRESHOLD_OBSERVATIONS

            // F1: Massa (Log) - Geoptimaliseerd voor BSI 4.0
            val fMassaRaw = log10(p.count.toDouble().coerceAtLeast(1.0))
            val fMassa = 1.0 + (fMassaRaw * 0.4)

            // BSI 4.1: Wind-Efficiency Ratio (Dynamisch & Gradueel)
            val speciesWindData = windStats[p.soortid]
            val currentWindCount = speciesWindData?.find { it.windLabel == currentWindLabel }?.count ?: 0L
            val bestWindCount = speciesWindData?.maxOfOrNull { it.count } ?: 1L

            // De ratio: hoe goed is de wind van vandaag t.o.v. de beste wind voor deze soort?
            // We gebruiken een kleine ondergrens (0.01) om totale uitsluiting te voorkomen tenzij veto
            val efficiencyRatio = (currentWindCount.toDouble() / bestWindCount.toDouble()).coerceIn(0.01, 1.0)

            // F2: High-Precision Wind-DNA (BSI 4.0: 5.25 graden tolerantie)
            val histWindDeg = parseWindLabelToDegrees(p.mainWind) ?: currentWindDeg
            val diff = abs(currentWindDeg - histWindDeg)
            val normalizedDiff = if (diff > 180) 360 - diff else diff

            // Scherpe kwadratische afstraffing buiten de 5.25 graden
            val fWind = if (normalizedDiff <= AiConfig.WIND_TOLERANCE_DEGREES) {
                1.8 // Volle bak match
            } else {
                max(0.1, 1.8 * exp(-(normalizedDiff * normalizedDiff) / 400.0))
            }

            // F3: Special / Remarkable / BoI Boost
            var fSpecial = 1.0
            val isKrent = (expertKB?.discoveredKrenten?.contains(p.soortid) == true || 
                          expertKB?.pinnedSpecies?.contains(p.soortid) == true) &&
                          expertKB?.excludedSpecies?.contains(p.soortid) != true

            if (p.isRemarkable == 1) fSpecial = 4.5 // Verhoogd in 4.0
            else if (isKrent || isBoI) fSpecial = 3.0 // BoI krijgt meer gewicht

            // F4: Tijd & Strategie - Nu met "Temporal Blueprinting" voor dag-totalen
            var fTime = 1.0
            val bft = WeatherManager.msToBeaufort(cur.windSpeed10m)

            // BSI 4.0: Temporal Blueprinting (Gouden Mal)
            val hourlyProfile = expertKB?.hourlyProfiles?.get(p.soortid)
            val blueprintFactor = hourlyProfile?.getOrNull(currentHour) ?: -1f

            val targetHour = p.avgHour ?: 10f
            val hourDiff = abs(currentHour - targetHour)

            when (strategy) {
                SpeciesGuildMapper.FlightStrategy.THERMAL -> {
                    if (currentHour < 9 || currentHour > 18 || phase == SolarTimeEngine.SolarPhase.NIGHT || bft >= 6) fTime = 0.0001
                    else fTime = 0.5 + ((currentTemp - 10.0).coerceIn(0.1, 10.0) / 10.0)
                }
                SpeciesGuildMapper.FlightStrategy.ACTIVE -> {
                    if (phase == SolarTimeEngine.SolarPhase.NIGHT && guild != SpeciesGuildMapper.Guild.PELAGICS) fTime = 0.01 
                    else {
                        fTime = if (blueprintFactor >= 0) blueprintFactor.toDouble() * 2.0
                                else exp(-(hourDiff * hourDiff) / 40.0)
                    }
                }
                SpeciesGuildMapper.FlightStrategy.VISMIG -> {
                    if (phase == SolarTimeEngine.SolarPhase.NIGHT) fTime = 0.0001
                    else {
                        fTime = if (blueprintFactor >= 0) blueprintFactor.toDouble() * 2.5
                                else exp(-(hourDiff * hourDiff) / 25.0)
                    }
                }
            }

            // BSI 4.0: 72-uurs Corridor Correlation voor BoI's
            var boiCorridorFactor = 1.0
            if (isBoI) {
                // Hier zouden we de historische corridor condities vergelijken
                // Voor nu implementeren we een placeholder die de corridor-druk van de laatste 72u meeweegt
                boiCorridorFactor = 1.0 + (regBoost * 0.5) 
            }

            // F5: Local Wind Gatekeeper (The Veto)
            var fGatekeeper = 1.0
            val isOffShore = currentWindLabel in listOf("O","OZO","ZO","ZZO","Z")
            val isOnShore = currentWindLabel in listOf("NW","WNW","W","ZW","NNW")

            if (guild == SpeciesGuildMapper.Guild.PELAGICS) {
                if (isOffShore) fGatekeeper = 0.001 
                else if (isOnShore) {
                    // BSI 4.1: Exponentiële boost bij harde aanlandige wind
                    fGatekeeper = if (bft >= AiConfig.EFFICIENCY_BOOST_PELAGIC_BFT) {
                        2.0 * (1.0 + (bft - 4) * 0.5)
                    } else 2.0
                }
            } else if (guild in listOf(SpeciesGuildMapper.Guild.RAPTORS_ACTIVE, SpeciesGuildMapper.Guild.RAPTORS_THERMAL, SpeciesGuildMapper.Guild.PASSERINES, SpeciesGuildMapper.Guild.HERONS)) {
                // BSI 4.1: Coastal Landvogel Veto
                if (AiConfig.IS_COASTAL_SITE && isOnShore) {
                    fGatekeeper = if (bft >= 4) 0.1 else 0.4
                } else if (currentWindLabel in listOf("O", "ONO", "NO")) {
                    fGatekeeper = 1.5
                }
            }

            // BSI 4.0: Weather Twin Bonus
            // Als de soort voorkomt in de weatherTwins lijst, verhogen we de score
            val twinCount = weatherTwins.filter { it.soortid == p.soortid }.sumOf { it.count }
            val fTwin = 1.0 + (log10(twinCount.toDouble().coerceAtLeast(1.0)) * 0.5)

            // BSI 4.1: Finale aggregatie met Efficiency Ratio (basis)
            val total = fMassa * fWind * fSpecial * fTime * fGatekeeper * fTwin * boiCorridorFactor * efficiencyRatio * (1.0 + regBoost)

            // Apply daily-analysis weight (if available) as multiplicative factor so real reconstructed days influence the score
            var combinedScore = total
            try {
                val rawDaily = dailySpeciesWeights[p.soortid] ?: 1.0f
                val dailyW = rawDaily.coerceAtLeast(0.1f).coerceAtMost(AiConfig.DAILY_ANALYSIS_WEIGHT_MAX).toDouble()
                if (dailyW != 1.0) {
                    combinedScore = combinedScore * dailyW
                    Log.d(TAG, "DAILY-WEIGHT: ${p.soortid} weight=${String.format(Locale.US, "%.3f", dailyW)}")
                }
            } catch (e: Exception) {
                Log.w(TAG, "Daily weight application failed: ${e.message}")
            }

            // Neural boost: als we een voorspelling hebben, map species-id naar label-index en pas een multiplicatieve factor toe
            try {
                if (neuralPredictions != null && modelLabels != null) {
                    val idx = modelLabels.indexOf(p.soortid)
                    if (idx >= 0 && idx < neuralPredictions.size) {
                        val prob = neuralPredictions[idx].toDouble()
                        val nnFactor = 1.0 + (AiConfig.NEURAL_INTEGRATION_WEIGHT * prob)
                        combinedScore = combinedScore * nnFactor
                        Log.d(TAG, "NN BOOST: ${p.soortid} prob=${String.format(Locale.US, "%.4f", prob)} factor=${String.format(Locale.US, "%.3f", nnFactor)}")
                    }
                }
            } catch (_: Exception) { /* best-effort */ }

            Log.d(TAG, "RAW BSI 4.1: %-20s | BASE:%5.2f | COMBINED:%5.2f | Ratio:%.2f | W:%.2f | T:%.2f | G:%.2f".format(
                name, total, combinedScore, efficiencyRatio, fWind, fTime, fGatekeeper))

            ScoredSpecies(p.soortid, name, combinedScore, guild, clusterIndices[p.soortid]?.clusterIndex)
        }

        // 4. Gilde selectie & Krenten-Highlights
        val finalResults = mutableListOf<VogelSuggestie>()
        val rareHighlights = mutableListOf<VogelSuggestie>()
        val idealScore = 5.0 

        SpeciesGuildMapper.Guild.entries.filter { it != SpeciesGuildMapper.Guild.OTHER }.forEach { guild ->
            val winners = scoredList.filter { it.guild == guild }.sortedByDescending { it.score }.take(3)
            winners.forEach { w ->
                val probRaw = (min(0.98, w.score / idealScore) * 100).toInt()

                // FEEDBACK CORRECTIE via JSON
                val avgRating = AiFeedbackManager.getCorrectionFactor(context, w.soortid, currentWindLabel)
                val prob = (probRaw * (0.5f + avgRating * 0.5f)).toInt() 

                // BSI 4.1: Dynamic Quality Cutoff (Drempelwaarde)
                if (prob >= AiConfig.MIN_BSI_QUALITY_THRESHOLD) {
                    val latin = snapshot?.speciesById?.get(w.soortid)?.latin
                    val suggestion = VogelSuggestie(
                        guildName = guild.displayName, 
                        soortnaam = w.soortnaam, 
                        kans = prob, 
                        soortid = w.soortid,
                        latinName = latin,
                        expectedIndex = w.expectedIndex
                    )
                    finalResults.add(suggestion)

                    // EXTRA: KRENTEN HIGHLIGHTS ("Uitkijken voor")
                    val isKrentHighlight = (expertKB?.discoveredKrenten?.contains(w.soortid) == true || 
                                          expertKB?.pinnedSpecies?.contains(w.soortid) == true) &&
                                          expertKB?.excludedSpecies?.contains(w.soortid) != true

                    if (guild.isSpecial || isKrentHighlight) {
                        Log.i(TAG, "HIGHLIGHT FOUND: ${w.soortnaam} (${prob}%)")
                        rareHighlights.add(suggestion)
                    }
                }
            }
        }

        Log.i(TAG, "FINISH: ${finalResults.size} suggesties, ${rareHighlights.size} highlights.")
        Log.i(TAG, "=========================================================")

        logForecast(context, db, cur, currentHour, phase, finalResults)

        return@withContext AiSuggestieData(
            guildResults = finalResults.sortedByDescending { it.kans },
            rareHighlights = rareHighlights.sortedByDescending { it.kans }.take(3),
            weerBeschrijving = "$currentWindLabel-wind / ${WeatherManager.msToBeaufort(cur.windSpeed10m)}bft"
        )
    }

    private suspend fun logForecast(
        context: Context, 
        db: VoiceTallyDatabase, 
        cur: Current, 
        hour: Int, 
        phase: SolarTimeEngine.SolarPhase,
        results: List<VogelSuggestie>
    ) {
        try {
            val conditionJson = org.json.JSONObject().apply {
                put("temp", cur.temperature2m)
                put("wind", WeatherManager.degTo16WindLabel(cur.windDirection10m))
                put("h", hour)
                put("phase", phase.name)
            }.toString()

            val suggestionsJson = org.json.JSONObject().apply {
                val list = org.json.JSONArray()
                results.forEach {
                    val item = org.json.JSONObject()
                    item.put("id", it.soortid)
                    item.put("name", it.soortnaam)
                    item.put("prob", it.kans)
                    item.put("guild", it.guildName)
                    list.put(item)
                }
                put("items", list)
            }.toString()

            val prefs = context.getSharedPreferences("vt5_prefs", Context.MODE_PRIVATE)
            val currentTellingId = prefs.getString("pref_telling_id", "manual") ?: "manual"

            db.tellingDao().insertAiLog(com.yvesds.vt5.core.database.entities.AiLog(
                tellingid = currentTellingId,
                type = "scientific_v2",
                requestContext = conditionJson,
                suggestions = suggestionsJson
            ))
        } catch (_: Exception) {}
    }

    private fun loadExpertKnowledge(modelStore: ModelStore): ExpertKnowledgeBase? {
        return modelStore.loadExpertKnowledge()
    }

    suspend fun getLiveCorridorBoost(month: Int): Double {
        val isAutumn = month in 7..11
        val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)

        // We vragen de laatste 24 uur aan voor een venster-analyse
        val corridorData = WeatherManager.fetchCorridorForecast(points)
        if (corridorData.isEmpty()) return 0.0

        val now = java.time.LocalDateTime.now()
        val formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")

        var totalMaxScore = 0.0
        corridorData.forEach { (name, hourly) ->
            // Zoek de meest gunstige condities in de afgelopen 72 uur (3 dagen) voor dit punt
            val recentHours = hourly.filter { 
                try {
                    val dt = java.time.LocalDateTime.parse(it.time, formatter)
                    dt.isAfter(now.minusHours(72)) && dt.isBefore(now.plusHours(1))
                } catch (_: Exception) { false }
            }

            val bestSnapshotScore = recentHours.maxOfOrNull { entry ->
                val cur = Current(temperature2m = entry.temp, windSpeed10m = entry.windSpeed, windDirection10m = entry.windDeg)
                calculateSinglePointScore(cur, isAutumn)
            } ?: 0.0
            totalMaxScore += bestSnapshotScore
        }

        return totalMaxScore / points.size
    }

    /**
     * NIEUW: Haalt de corridor boost op uit de lokale database voor een historisch moment.
     */
    suspend fun getHistoricalCorridorBoost(context: Context, dayEpoch: Long, month: Int): Double = withContext(Dispatchers.IO) {
        val isAutumn = month in 7..11
        val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)
        val db = VoiceTallyDatabase.getDatabase(context)
        val dao = db.tellingDao()

        var totalMaxScore = 0.0
        val windowStart = dayEpoch - (72 * 3600)

        points.forEach { point ->
            var bestPointScore = 0.0
            // Check elk uur in het 72-uurs venster in het archief
            for (hour in 0 until 72) {
                val checkEpoch = windowStart + (hour * 3600)
                val w = dao.getWeather(point.name, checkEpoch)
                if (w != null) {
                    val cur = Current(temperature2m = w.temp, windSpeed10m = w.windSpeed10m, windDirection10m = w.windDir10m, pressureMsl = w.pressureMsl)
                    val score = calculateSinglePointScore(cur, isAutumn)
                    if (score > bestPointScore) bestPointScore = score
                }
            }
            totalMaxScore += bestPointScore
        }

        return@withContext totalMaxScore / points.size
    }

    fun calculateSinglePointScore(cur: Current, isAutumn: Boolean): Double {
        val w = WeatherManager.degTo16WindLabel(cur.windDirection10m)
        val p = cur.pressureMsl ?: 1013.0
        return if (isAutumn) {
            if (w in listOf("N","NNO","NO","ONO","O") && p > 1014.0) 1.0 else 0.0
        } else {
            if (w in listOf("Z","ZZW","ZW","WZW") && p > 1010.0) 1.0 else 0.0
        }
    }

    /**
     * Berekent de corridor-score op basis van een lijst met weer-snapshots.
     */
    fun calculateCorridorScore(statuses: List<Pair<String, Current>>, isAutumn: Boolean): Double {
        if (statuses.isEmpty()) return 0.0
        var matchCount = 0
        statuses.forEach { (_, cur) ->
            if (calculateSinglePointScore(cur, isAutumn) > 0.5) matchCount++
        }
        return (matchCount.toDouble() / statuses.size)
    }

    private fun getLocalSiteCluster(saf: SaFStorageHelper, lat: Double, lon: Double): List<String>? {
        return try {
            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: return null
            val root = VT5App.json.decodeFromString<TelpostLocatiesRoot>(jsonStr)
            val ids = root.locaties.filter { calculateDistance(lat, lon, it.latitude, it.longitude) <= 35.0 }.map { it.telpostid }
            ids.ifEmpty { null }
        } catch (_: Exception) { null }
    }

    private fun parseWindLabelToDegrees(l: String?): Double? {
        val labels = arrayOf("N","NNO","NO","ONO","O","OZO","ZO","ZZO","Z","ZZW","ZW","WZW","W","WNW","NW","NNW")
        val i = labels.indexOf(l?.uppercase()); return if (i >= 0) i * 22.5 else null
    }

    private fun calculateDistance(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
        val r = 6371.0
        val dLat = Math.toRadians(lat2 - lat1); val dLon = Math.toRadians(lon2 - lon1)
        val a = sin(dLat/2).pow(2) + cos(Math.toRadians(lat1)) * cos(Math.toRadians(lat2)) * sin(dLon / 2).pow(2)
        return r * 2 * atan2(sqrt(a), sqrt(1 - a))
    }

    private data class ScoredSpecies(
        val soortid: String, 
        val soortnaam: String, 
        val score: Double, 
        val guild: SpeciesGuildMapper.Guild,
        val expectedIndex: Float? = null
    )
}

package com.yvesds.vt5.ai

import android.content.Context
import android.util.Log
import com.yvesds.vt5.VT5App
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.entities.AiLog
import com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot
import com.yvesds.vt5.core.database.ui.SpeciesNameResolver
import com.yvesds.vt5.core.opslag.EffortManager
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.features.serverdata.model.ServerDataCache
import com.yvesds.vt5.utils.weather.Current
import com.yvesds.vt5.utils.weather.WeatherManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import java.util.*
import kotlin.math.*
import com.yvesds.vt5.core.opslag.AppDataStore

/**
 * AiInferenceEngine - Expert Deep Diagnostic & Live Corridor Edition.
 * Nu met Zelf-ontdekkende Krenten op basis van de ExpertKnowledgeBase.
 */
object AiInferenceEngine {
    private const val TAG = "AiInference"

    suspend fun getSuggesties(
        context: Context,
        cur: Current,
        hourOverride: Int? = null,
        providedRegBoost: Double? = null,
        useNeural: Boolean? = null
    ): AiSuggestieData = withContext(Dispatchers.IO) {
        Log.i(TAG, "=========================================================")
        Log.i(TAG, "START SCIENTIFIC AI ANALYSIS")

        val db = VoiceTallyDatabase.getDatabase(context)
        val dao = db.tellingDao()
        val saf = SaFStorageHelper(context)

        // Laad alle AI Kennis (JSON of Binair met Auto-Sync)
        val snapshot = try { ServerDataCache.getOrLoad(context) } catch (_: Exception) { null }
        val modelStore = ModelStore(context)
        val expertKB = loadExpertKnowledge(modelStore)

        val cal = Calendar.getInstance()
        val currentHour = hourOverride ?: cal.get(Calendar.HOUR_OF_DAY)
        cal.set(Calendar.HOUR_OF_DAY, currentHour); cal.set(Calendar.MINUTE, 0)
        val dayOfYear = cal.get(Calendar.DAY_OF_YEAR)
        val month = cal.get(Calendar.MONTH) + 1

        val loc = WeatherManager.getLastKnownLocation(context)
        val lat = loc?.latitude ?: 51.0
        val lon = loc?.longitude ?: 3.0

        val currentWindDeg = cur.windDirection10m ?: 0.0
        val currentWindLabel = WeatherManager.degTo16WindLabel(currentWindDeg)
        val currentTemp = (cur.temperature2m ?: 15.0).toFloat()

        // BEPAAL CLUSTER GEANKERD AAN DE HOOFDTELPOST (Eerste in JSON)
        val cluster = withContext(Dispatchers.IO) {
            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
            val root = VT5App.json.decodeFromString<TelpostLocatiesRoot>(jsonStr)
            val primarySite = root.locaties.firstOrNull()
            if (primarySite != null) {
                root.locaties.filter { calculateDistance(primarySite.latitude, primarySite.longitude, it.latitude, it.longitude) <= 35.0 }
                    .map { it.telpostid }
            } else {
                getLocalSiteCluster(saf, lat, lon)
            }
        }

        val phase = SolarTimeEngine.getSolarPhase(lat, lon, cal)

        // 1. LIVE REGIONALE CORRIDOR CHECK (Tenzij boost al gegeven is)
        val regBoost = providedRegBoost ?: getLiveCorridorBoost(month)

        // 2. Data ophalen: BSI 4.0 Dynamic Mining
        val effortHours = EffortManager.getClusterEffortHours(context, cluster ?: emptyList())

        // Bepaal venster grootte (BoI's krijgen 9 dagen, anderen 7)
        // Voor de initiële fetch gebruiken we 9 dagen om zeker te zijn
        val window = AiConfig.BOI_FLOATING_WINDOW_DAYS
        val dayStart = dayOfYear - (window / 2)
        val dayEnd = dayOfYear + (window / 2)

        // Weather Twin Mining: Zoek uren met exact dezelfde wind-signatuur (+/- 5.25 graden)
        // Omdat we in de DAO op Label matchen (N, NO), mappen we de huidige graden naar label
        val weatherTwins = dao.getWeatherTwinObservations(cluster ?: emptyList(), dayStart, dayEnd, currentWindLabel)

        // BSI 4.1: Haal wind-efficiëntie data op (alle windstreken in dit venster)
        val windStats = dao.getWindEfficiencyStats(cluster ?: emptyList(), dayStart, dayEnd)
            .groupBy { it.soortid }

        val profiles = dao.getSpeciesPhenologyProfile(dayStart, dayEnd, cluster ?: emptyList(), if (cluster == null) 0 else 1)

        val clusterIndices = if (cluster != null) {
            dao.getSpeciesGigaBaseline(cluster, effortHours).associateBy { it.soortid }
        } else emptyMap()

        // Neural model: probeer labels en model te laden en maak één predictie voor de huidige context
        val effectiveUseNeural = if (useNeural != null) {
            useNeural
        } else {
            // Read runtime override from DataStore (default true)
            try { AppDataStore.isUseNeuralInference(context) } catch (e: Exception) { AiConfig.USE_NEURAL_INFERENCE }
        }
        Log.i(TAG, "Neural inference enabled (effective): $effectiveUseNeural")

        // Daily-analysis based weighting: read runtime override and compute species weights if enabled
        val effectiveUseDailyWeights = try { AppDataStore.isUseDailyAnalysisWeights(context) } catch (e: Exception) { AiConfig.USE_DAILY_ANALYSIS_WEIGHTS }
        var dailySpeciesWeights: Map<String, Float> = emptyMap()
        if (effectiveUseDailyWeights) {
            try {
                val preparer = TrainingDataPreparer(context)
                dailySpeciesWeights = preparer.computeSpeciesWeightsFromDailyAnalysis()
                Log.i(TAG, "Computed daily-analysis species weights: ${dailySpeciesWeights.size} entries")
            } catch (e: Exception) {
                Log.w(TAG, "Failed to compute daily-analysis weights: ${e.message}")
                dailySpeciesWeights = emptyMap()
            }
        }
        val modelLabels = modelStore.loadModelLabels()
        var neuralPredictions: FloatArray? = null
        if (!modelLabels.isNullOrEmpty() && effectiveUseNeural) {
            try {
                val neural = modelStore.loadNeuralEngine(modelLabels.size)
                // Bouw feature-vector voor de huidige situatie (best effort)
                val siteId = cluster?.firstOrNull()
                val preparer = TrainingDataPreparer(context)
                val epochSec = cal.timeInMillis / 1000L
                val features = preparer.buildFeatureVectorForContext(
                    epoch = epochSec,
                    telpostId = siteId,
                    temperature = cur.temperature2m,
                    windDeg = cur.windDirection10m,
                    windForce = cur.windSpeed10m,
                    cloudCover = null,
                    hpa = cur.pressureMsl,
                    precipitationFlag = null
                )
                neuralPredictions = neural.predict(features)
                Log.i(TAG, "Neural integration: loaded model with ${neuralPredictions.size} outputs.")
            } catch (e: Exception) {
                Log.w(TAG, "Neural integration failed: ${e.message}")
            }
        }

        // 3. Score berekening
        val scoredList = profiles.mapNotNull { p ->
            val speciesData = snapshot?.speciesById?.get(p.soortid)
            val latin = speciesData?.latin
            val name = speciesData?.soortnaam ?: SpeciesNameResolver.getName(context, p.soortid)

            if (name.lowercase().contains("spec.") || 
                name.lowercase().contains("onbekend") || 
                name.contains("/")) return@mapNotNull null

            val guild = SpeciesGuildMapper.getGuildByLatin(latin)
            if (guild == SpeciesGuildMapper.Guild.OTHER) return@mapNotNull null
            val strategy = guild.strategy

            // BSI 4.0: BoI Check & Window
            val totalObs = clusterIndices[p.soortid]?.activePosts ?: 0
            val isBoI = totalObs < AiConfig.BOI_THRESHOLD_OBSERVATIONS

            // F1: Massa (Log) - Geoptimaliseerd voor BSI 4.0
            val fMassaRaw = log10(p.count.toDouble().coerceAtLeast(1.0))
            val fMassa = 1.0 + (fMassaRaw * 0.4)

            // BSI 4.1: Wind-Efficiency Ratio (Dynamisch & Gradueel)
            val speciesWindData = windStats[p.soortid]
            val currentWindCount = speciesWindData?.find { it.windLabel == currentWindLabel }?.count ?: 0L
            val bestWindCount = speciesWindData?.maxOfOrNull { it.count } ?: 1L

            // De ratio: hoe goed is de wind van vandaag t.o.v. de beste wind voor deze soort?
            // We gebruiken een kleine ondergrens (0.01) om totale uitsluiting te voorkomen tenzij veto
            val efficiencyRatio = (currentWindCount.toDouble() / bestWindCount.toDouble()).coerceIn(0.01, 1.0)

            // F2: High-Precision Wind-DNA (BSI 4.0: 5.25 graden tolerantie)
            val histWindDeg = parseWindLabelToDegrees(p.mainWind) ?: currentWindDeg
            val diff = abs(currentWindDeg - histWindDeg)
            val normalizedDiff = if (diff > 180) 360 - diff else diff

            // Scherpe kwadratische afstraffing buiten de 5.25 graden
            val fWind = if (normalizedDiff <= AiConfig.WIND_TOLERANCE_DEGREES) {
                1.8 // Volle bak match
            } else {
                max(0.1, 1.8 * exp(-(normalizedDiff * normalizedDiff) / 400.0))
            }

            // F3: Special / Remarkable / BoI Boost
            var fSpecial = 1.0
            val isKrent = (expertKB?.discoveredKrenten?.contains(p.soortid) == true || 
                          expertKB?.pinnedSpecies?.contains(p.soortid) == true) &&
                          expertKB?.excludedSpecies?.contains(p.soortid) != true

            if (p.isRemarkable == 1) fSpecial = 4.5 // Verhoogd in 4.0
            else if (isKrent || isBoI) fSpecial = 3.0 // BoI krijgt meer gewicht

            // F4: Tijd & Strategie - Nu met "Temporal Blueprinting" voor dag-totalen
            var fTime = 1.0
            val bft = WeatherManager.msToBeaufort(cur.windSpeed10m)

            // BSI 4.0: Temporal Blueprinting (Gouden Mal)
            val hourlyProfile = expertKB?.hourlyProfiles?.get(p.soortid)
            val blueprintFactor = hourlyProfile?.getOrNull(currentHour) ?: -1f

            val targetHour = p.avgHour ?: 10f
            val hourDiff = abs(currentHour - targetHour)

            when (strategy) {
                SpeciesGuildMapper.FlightStrategy.THERMAL -> {
                    if (currentHour < 9 || currentHour > 18 || phase == SolarTimeEngine.SolarPhase.NIGHT || bft >= 6) fTime = 0.0001
                    else fTime = 0.5 + ((currentTemp - 10.0).coerceIn(0.1, 10.0) / 10.0)
                }
                SpeciesGuildMapper.FlightStrategy.ACTIVE -> {
                    if (phase == SolarTimeEngine.SolarPhase.NIGHT && guild != SpeciesGuildMapper.Guild.PELAGICS) fTime = 0.01 
                    else {
                        fTime = if (blueprintFactor >= 0) blueprintFactor.toDouble() * 2.0
                                else exp(-(hourDiff * hourDiff) / 40.0)
                    }
                }
                SpeciesGuildMapper.FlightStrategy.VISMIG -> {
                    if (phase == SolarTimeEngine.SolarPhase.NIGHT) fTime = 0.0001
                    else {
                        fTime = if (blueprintFactor >= 0) blueprintFactor.toDouble() * 2.5
                                else exp(-(hourDiff * hourDiff) / 25.0)
                    }
                }
            }

            // BSI 4.0: 72-uurs Corridor Correlation voor BoI's
            var boiCorridorFactor = 1.0
            if (isBoI) {
                // Hier zouden we de historische corridor condities vergelijken
                // Voor nu implementeren we een placeholder die de corridor-druk van de laatste 72u meeweegt
                boiCorridorFactor = 1.0 + (regBoost * 0.5) 
            }

            // F5: Local Wind Gatekeeper (The Veto)
            var fGatekeeper = 1.0
            val isOffShore = currentWindLabel in listOf("O","OZO","ZO","ZZO","Z")
            val isOnShore = currentWindLabel in listOf("NW","WNW","W","ZW","NNW")

            if (guild == SpeciesGuildMapper.Guild.PELAGICS) {
                if (isOffShore) fGatekeeper = 0.001 
                else if (isOnShore) {
                    // BSI 4.1: Exponentiële boost bij harde aanlandige wind
                    fGatekeeper = if (bft >= AiConfig.EFFICIENCY_BOOST_PELAGIC_BFT) {
                        2.0 * (1.0 + (bft - 4) * 0.5)
                    } else 2.0
                }
            } else if (guild in listOf(SpeciesGuildMapper.Guild.RAPTORS_ACTIVE, SpeciesGuildMapper.Guild.RAPTORS_THERMAL, SpeciesGuildMapper.Guild.PASSERINES, SpeciesGuildMapper.Guild.HERONS)) {
                // BSI 4.1: Coastal Landvogel Veto
                if (AiConfig.IS_COASTAL_SITE && isOnShore) {
                    fGatekeeper = if (bft >= 4) 0.1 else 0.4
                } else if (currentWindLabel in listOf("O", "ONO", "NO")) {
                    fGatekeeper = 1.5
                }
            }

            // BSI 4.0: Weather Twin Bonus
            // Als de soort voorkomt in de weatherTwins lijst, verhogen we de score
            val twinCount = weatherTwins.filter { it.soortid == p.soortid }.sumOf { it.count }
            val fTwin = 1.0 + (log10(twinCount.toDouble().coerceAtLeast(1.0)) * 0.5)

            // BSI 4.1: Finale aggregatie met Efficiency Ratio (basis)
            val total = fMassa * fWind * fSpecial * fTime * fGatekeeper * fTwin * boiCorridorFactor * efficiencyRatio * (1.0 + regBoost)

            // Apply daily-analysis weight (if available) as multiplicative factor so real reconstructed days influence the score
            var combinedScore = total
            try {
                val rawDaily = dailySpeciesWeights[p.soortid] ?: 1.0f
                val dailyW = rawDaily.coerceAtLeast(0.1f).coerceAtMost(AiConfig.DAILY_ANALYSIS_WEIGHT_MAX).toDouble()
                if (dailyW != 1.0) {
                    combinedScore = combinedScore * dailyW
                    Log.d(TAG, "DAILY-WEIGHT: ${p.soortid} weight=${String.format(Locale.US, "%.3f", dailyW)}")
                }
            } catch (e: Exception) {
                Log.w(TAG, "Daily weight application failed: ${e.message}")
            }

            // Neural boost: als we een voorspelling hebben, map species-id naar label-index en pas een multiplicatieve factor toe
            try {
                if (neuralPredictions != null && modelLabels != null) {
                    val idx = modelLabels.indexOf(p.soortid)
                    if (idx >= 0 && idx < neuralPredictions.size) {
                        val prob = neuralPredictions[idx].toDouble()
                        val nnFactor = 1.0 + (AiConfig.NEURAL_INTEGRATION_WEIGHT * prob)
                        combinedScore = combinedScore * nnFactor
                        Log.d(TAG, "NN BOOST: ${p.soortid} prob=${String.format(Locale.US, "%.4f", prob)} factor=${String.format(Locale.US, "%.3f", nnFactor)}")
                    }
                }
            } catch (_: Exception) { /* best-effort */ }

            Log.d(TAG, "RAW BSI 4.1: %-20s | BASE:%5.2f | COMBINED:%5.2f | Ratio:%.2f | W:%.2f | T:%.2f | G:%.2f".format(
                name, total, combinedScore, efficiencyRatio, fWind, fTime, fGatekeeper))

            ScoredSpecies(p.soortid, name, combinedScore, guild, clusterIndices[p.soortid]?.clusterIndex)
        }

        // 4. Gilde selectie & Krenten-Highlights
        val finalResults = mutableListOf<VogelSuggestie>()
        val rareHighlights = mutableListOf<VogelSuggestie>()
        val idealScore = 5.0 

        // Take top-N per guild (configurable)
        SpeciesGuildMapper.Guild.entries.filter { it != SpeciesGuildMapper.Guild.OTHER }.forEach { guild ->
            val winners = scoredList.filter { it.guild == guild }.sortedByDescending { it.score }.take(AiConfig.GUILD_TOP_N)
            winners.forEach { w ->
                val probRaw = (min(0.98, w.score / idealScore) * 100).toInt()

                // FEEDBACK CORRECTIE via JSON
                val avgRating = AiFeedbackManager.getCorrectionFactor(context, w.soortid, currentWindLabel)
                val prob = (probRaw * (0.5f + avgRating * 0.5f)).toInt() 

                // BSI 4.1: Dynamic Quality Cutoff (Drempelwaarde)
                if (prob >= AiConfig.MIN_BSI_QUALITY_THRESHOLD) {
                    val latin = snapshot?.speciesById?.get(w.soortid)?.latin
                    val suggestion = VogelSuggestie(
                        guildName = guild.displayName, 
                        soortnaam = w.soortnaam, 
                        kans = prob, 
                        soortid = w.soortid,
                        latinName = latin,
                        expectedIndex = w.expectedIndex
                    )
                                    finalResults.add(suggestion)

                    // EXTRA: KRENTEN HIGHLIGHTS ("Uitkijken voor")
                    val isKrentHighlight = (expertKB?.discoveredKrenten?.contains(w.soortid) == true || 
                                          expertKB?.pinnedSpecies?.contains(w.soortid) == true) &&
                                          expertKB?.excludedSpecies?.contains(w.soortid) != true

                    if (guild.isSpecial || isKrentHighlight) {
                        Log.i(TAG, "HIGHLIGHT FOUND: ${w.soortnaam} (${prob}%)")
                        rareHighlights.add(suggestion)
                    }
                }
            }
        }

        Log.i(TAG, "FINISH: ${finalResults.size} suggesties, ${rareHighlights.size} highlights.")
        Log.i(TAG, "=========================================================")

        logForecast(context, db, cur, currentHour, phase, finalResults)

        return@withContext AiSuggestieData(
            guildResults = finalResults.sortedByDescending { it.kans },
            rareHighlights = rareHighlights.sortedByDescending { it.kans }.take(AiConfig.BOI_TOP_N),
            weerBeschrijving = "$currentWindLabel-wind / ${WeatherManager.msToBeaufort(cur.windSpeed10m)}bft"
        )
    }

    private suspend fun logForecast(
        context: Context, 
        db: VoiceTallyDatabase, 
        cur: Current, 
        hour: Int, 
        phase: SolarTimeEngine.SolarPhase,
        results: List<VogelSuggestie>
    ) {
        try {
            val conditionJson = org.json.JSONObject().apply {
                put("temp", cur.temperature2m)
                put("wind", WeatherManager.degTo16WindLabel(cur.windDirection10m))
                put("h", hour)
                put("phase", phase.name)
            }.toString()

            val suggestionsJson = org.json.JSONObject().apply {
                val list = org.json.JSONArray()
                results.forEach {
                    val item = org.json.JSONObject()
                    item.put("id", it.soortid)
                    item.put("name", it.soortnaam)
                    item.put("prob", it.kans)
                    item.put("guild", it.guildName)
                    list.put(item)
                }
                put("items", list)
            }.toString()

            val prefs = context.getSharedPreferences("vt5_prefs", Context.MODE_PRIVATE)
            val currentTellingId = prefs.getString("pref_telling_id", "manual") ?: "manual"

            db.tellingDao().insertAiLog(com.yvesds.vt5.core.database.entities.AiLog(
                tellingid = currentTellingId,
                type = "scientific_v2",
                requestContext = conditionJson,
                suggestions = suggestionsJson
            ))
        } catch (_: Exception) {}
    }

    private fun loadExpertKnowledge(modelStore: ModelStore): ExpertKnowledgeBase? {
        return modelStore.loadExpertKnowledge()
    }

    suspend fun getLiveCorridorBoost(month: Int): Double {
        val isAutumn = month in 7..11
        val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)

        // We vragen de laatste 24 uur aan voor een venster-analyse
        val corridorData = WeatherManager.fetchCorridorForecast(points)
        if (corridorData.isEmpty()) return 0.0

        val now = java.time.LocalDateTime.now()
        val formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm")

        var totalMaxScore = 0.0
        corridorData.forEach { (name, hourly) ->
            // Zoek de meest gunstige condities in de afgelopen 72 uur (3 dagen) voor dit punt
            val recentHours = hourly.filter { 
                try {
                    val dt = java.time.LocalDateTime.parse(it.time, formatter)
                    dt.isAfter(now.minusHours(72)) && dt.isBefore(now.plusHours(1))
                } catch (_: Exception) { false }
            }

            val bestSnapshotScore = recentHours.maxOfOrNull { entry ->
                val cur = Current(temperature2m = entry.temp, windSpeed10m = entry.windSpeed, windDirection10m = entry.windDeg)
                calculateSinglePointScore(cur, isAutumn)
            } ?: 0.0
            totalMaxScore += bestSnapshotScore
        }

        return totalMaxScore / points.size
    }

    /**
     * NIEUW: Haalt de corridor boost op uit de lokale database voor een historisch moment.
     */
    suspend fun getHistoricalCorridorBoost(context: Context, dayEpoch: Long, month: Int): Double = withContext(Dispatchers.IO) {
        val isAutumn = month in 7..11
        val points = if (isAutumn) AiConfig.REFERENCE_POINTS.take(6) else AiConfig.REFERENCE_POINTS.takeLast(6)
        val db = VoiceTallyDatabase.getDatabase(context)
        val dao = db.tellingDao()

        var totalMaxScore = 0.0
        val windowStart = dayEpoch - (72 * 3600)

        points.forEach { point ->
            var bestPointScore = 0.0
            // Check elk uur in het 72-uurs venster in het archief
            for (hour in 0 until 72) {
                val checkEpoch = windowStart + (hour * 3600)
                val w = dao.getWeather(point.name, checkEpoch)
                if (w != null) {
                    val cur = Current(temperature2m = w.temp, windSpeed10m = w.windSpeed10m, windDirection10m = w.windDir10m, pressureMsl = w.pressureMsl)
                    val score = calculateSinglePointScore(cur, isAutumn)
                    if (score > bestPointScore) bestPointScore = score
                }
            }
            totalMaxScore += bestPointScore
        }

        return@withContext totalMaxScore / points.size
    }

    fun calculateSinglePointScore(cur: Current, isAutumn: Boolean): Double {
        val w = WeatherManager.degTo16WindLabel(cur.windDirection10m)
        val p = cur.pressureMsl ?: 1013.0
        return if (isAutumn) {
            if (w in listOf("N","NNO","NO","ONO","O") && p > 1014.0) 1.0 else 0.0
        } else {
            if (w in listOf("Z","ZZW","ZW","WZW") && p > 1010.0) 1.0 else 0.0
        }
    }

    /**
     * Berekent de corridor-score op basis van een lijst met weer-snapshots.
     */
    fun calculateCorridorScore(statuses: List<Pair<String, Current>>, isAutumn: Boolean): Double {
        if (statuses.isEmpty()) return 0.0
        var matchCount = 0
        statuses.forEach { (_, cur) ->
            if (calculateSinglePointScore(cur, isAutumn) > 0.5) matchCount++
        }
        return (matchCount.toDouble() / statuses.size)
    }

    private fun getLocalSiteCluster(saf: SaFStorageHelper, lat: Double, lon: Double): List<String>? {
        return try {
            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: return null
            val root = VT5App.json.decodeFromString<TelpostLocatiesRoot>(jsonStr)
            val ids = root.locaties.filter { calculateDistance(lat, lon, it.latitude, it.longitude) <= 35.0 }.map { it.telpostid }
            ids.ifEmpty { null }
        } catch (_: Exception) { null }
    }

    private fun parseWindLabelToDegrees(l: String?): Double? {
        val labels = arrayOf("N","NNO","NO","ONO","O","OZO","ZO","ZZO","Z","ZZW","ZW","WZW","W","WNW","NW","NNW")
        val i = labels.indexOf(l?.uppercase()); return if (i >= 0) i * 22.5 else null
    }

    private fun calculateDistance(lat1: Double, lon1: Double, lat2: Double, lon2: Double): Double {
        val r = 6371.0
        val dLat = Math.toRadians(lat2 - lat1); val dLon = Math.toRadians(lon2 - lon1)
        val a = sin(dLat/2).pow(2) + cos(Math.toRadians(lat1)) * cos(Math.toRadians(lat2)) * sin(dLon / 2).pow(2)
        return r * 2 * atan2(sqrt(a), sqrt(1 - a))
    }

    private data class ScoredSpecies(
        val soortid: String, 
        val soortnaam: String, 
        val score: Double, 
        val guild: SpeciesGuildMapper.Guild,
        val expectedIndex: Float? = null
    )
}

package com.yvesds.vt5.ai

import android.graphics.Color
import android.graphics.Typeface
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.yvesds.vt5.R
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.dao.DayCountRowClean
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.*
import android.os.Build
import kotlin.math.*

/**
 * [STABLE_AI_PROGNOSIS_ACTIVITY_V1 - 24 AUG 2026]
 * Nieuwe Activity voor de Live Migratie Prognose.
 * Gebruikt de bewezen seriële render-engine van de dagrapporten.
 */
class AiPrognoseActiviteit : AppCompatActivity() {

    private lateinit var database: VoiceTallyDatabase
    private lateinit var container: LinearLayout

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.scherm_ai_prognose)

        database = VoiceTallyDatabase.getDatabase(this)
        container = findViewById(R.id.prognoseContainer)

        val data = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            intent.getParcelableExtra("prognose_data", AiSuggestieData::class.java)
        } else {
            @Suppress("DEPRECATION")
            intent.getParcelableExtra<AiSuggestieData>("prognose_data")
        }
        if (data == null) {
            finish(); return
        }

        findViewById<TextView>(R.id.tvCondities).text = "Condities: ${data.weerBeschrijving}"
        findViewById<View>(R.id.btnTerug).setOnClickListener { finish() }

        buildDashboard(data)
    }

    private fun buildDashboard(data: AiSuggestieData) {
        lifecycleScope.launch {
            // 1. BEPAAL CLUSTER (Cruciaal anker voor de grafieklijnen)
            val saf = SaFStorageHelper(this@AiPrognoseActiviteit)
            val clusterIds = withContext(Dispatchers.IO) {
                try {
                    val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
                    val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)
                    val primarySite = root.locaties.firstOrNull()
                    if (primarySite != null) {
                        root.locaties.filter { 
                            val r = 6371.0
                            val dLat = Math.toRadians(it.latitude - primarySite.latitude)
                            val dLon = Math.toRadians(it.longitude - primarySite.longitude)
                            val a = sin(dLat/2).pow(2) + cos(Math.toRadians(primarySite.latitude)) * cos(Math.toRadians(it.latitude)) * sin(dLon/2).pow(2)
                            r * 2 * atan2(sqrt(a), sqrt(1 - a)) <= 35.0 
                        }.map { it.telpostid }
                    } else emptyList()
                } catch(_: Exception) { emptyList() }
            }

            // 2. VOEG HIGHLIGHTS TOE (Serieel)
            if (data.rareHighlights.isNotEmpty()) {
                addSectionHeader("UITKIJKEN VOOR (KRENTEN):", getColor(R.color.vt5_orange))
                data.rareHighlights.forEach { item ->
                    val view = createSpeciesCard(item, isHighlight = true, clusterIds = clusterIds)
                    container.addView(view)
                }
                addDivider()
            }

            // 3. VOEG ALGEMENE PROGNOSE TOE (Serieel)
            if (data.guildResults.isNotEmpty()) {
                addSectionHeader("ALGEMENE PROGNOSE:", Color.WHITE)
                data.guildResults.forEach { item ->
                    val view = createSpeciesCard(item, isHighlight = false, clusterIds = clusterIds)
                    container.addView(view)
                }
            }
        }
    }

    private fun addSectionHeader(title: String, color: Int) {
        val tv = TextView(this)
        tv.text = title; tv.setTextColor(color); tv.textSize = 14f; tv.setPadding(24, 32, 24, 16); tv.typeface = Typeface.DEFAULT_BOLD
        container.addView(tv)
    }

    private fun addDivider() {
        val d = View(this)
        d.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 2).apply { setMargins(0, 32, 0, 16) }
        d.setBackgroundColor(Color.parseColor("#444444"))
        container.addView(d)
    }

    private suspend fun createSpeciesCard(item: VogelSuggestie, isHighlight: Boolean, clusterIds: List<String>): View {
        val view = LayoutInflater.from(this).inflate(R.layout.item_ai_suggestion, container, false)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvExpected = view.findViewById<TextView>(R.id.tvExpectedIndex)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = item.guildName
        tvName.text = item.soortnaam
        tvName.setTextColor(if (isHighlight) getColor(R.color.vt5_orange) else getGuildColor(item.guildName))

        val norm = item.expectedIndex ?: 0f
        tvExpected.text = "BpH: ${"%.2f".format(norm)}"
        tvScientific.text = "BSI Kans: ${item.kans}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Foto
        if (!item.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(item.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(item.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(item.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator
            val weekOfYear = Calendar.getInstance().get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        return view
    }

    private fun calculatePeak(dayCounts: List<DayCountRowClean>): String {
        if (dayCounts.isEmpty()) return "onbekend"
        val maxRow = dayCounts.maxByOrNull { it.count } ?: return "onbekend"
        if (maxRow.count <= 0L) return "onbekend"
        val threshold = maxRow.count * 0.5
        val window = dayCounts.filter { it.count >= threshold }
        val sdf = SimpleDateFormat("d MMM", Locale("nl", "BE"))
        val calS = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.first().day) }
        val calE = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.last().day) }
        return if (window.first().day == window.last().day) sdf.format(calS.time) else "${sdf.format(calS.time)} - ${sdf.format(calE.time)}"
    }

    private fun getGuildColor(guildName: String): Int {
        return when {
            guildName.contains("Zang") -> Color.CYAN
            guildName.contains("Roof") -> Color.YELLOW
            guildName.contains("Reiger") -> Color.GREEN
            guildName.contains("Zeevogels") -> Color.MAGENTA
            guildName.contains("Stelt") -> Color.parseColor("#FF9800")
            guildName.contains("Water") -> Color.parseColor("#4FC3F7")
            guildName.contains("Kust") -> Color.parseColor("#009688")
            else -> Color.LTGRAY
        }
    }
}

package com.yvesds.vt5.ai

import android.graphics.Color
import android.graphics.Typeface
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.yvesds.vt5.R
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.dao.DayCountRowClean
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.*
import android.os.Build
import kotlin.math.*

/**
 * [STABLE_AI_PROGNOSIS_ACTIVITY_V1 - 24 AUG 2026]
 * Nieuwe Activity voor de Live Migratie Prognose.
 * Gebruikt de bewezen seriële render-engine van de dagrapporten.
 */
class AiPrognoseActiviteit : AppCompatActivity() {

    private lateinit var database: VoiceTallyDatabase
    private lateinit var container: LinearLayout

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.scherm_ai_prognose)

        database = VoiceTallyDatabase.getDatabase(this)
        container = findViewById(R.id.prognoseContainer)

        val data = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            intent.getParcelableExtra("prognose_data", AiSuggestieData::class.java)
        } else {
            @Suppress("DEPRECATION")
            intent.getParcelableExtra<AiSuggestieData>("prognose_data")
        }
        if (data == null) {
            finish(); return
        }

        findViewById<TextView>(R.id.tvCondities).text = "Condities: ${data.weerBeschrijving}"
        findViewById<View>(R.id.btnTerug).setOnClickListener { finish() }

        buildDashboard(data)
    }

    private fun buildDashboard(data: AiSuggestieData) {
        lifecycleScope.launch {
            // 1. BEPAAL CLUSTER (Cruciaal anker voor de grafieklijnen)
            val saf = SaFStorageHelper(this@AiPrognoseActiviteit)
            val clusterIds = withContext(Dispatchers.IO) {
                try {
                    val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
                    val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)
                    val primarySite = root.locaties.firstOrNull()
                    if (primarySite != null) {
                        root.locaties.filter { 
                            val r = 6371.0
                            val dLat = Math.toRadians(it.latitude - primarySite.latitude)
                            val dLon = Math.toRadians(it.longitude - primarySite.longitude)
                            val a = sin(dLat/2).pow(2) + cos(Math.toRadians(primarySite.latitude)) * cos(Math.toRadians(it.latitude)) * sin(dLon/2).pow(2)
                            r * 2 * atan2(sqrt(a), sqrt(1 - a)) <= 35.0 
                        }.map { it.telpostid }
                    } else emptyList()
                } catch(_: Exception) { emptyList() }
            }

            // 2. VOEG HIGHLIGHTS TOE (Serieel) + bouw gecombineerde lijst voor live weergave
            val boiIds = data.rareHighlights.map { it.soortid }.distinct()

            // Determine whether passerines should be included (only if at least one passerine is >= threshold)
            val passersAllowed = data.guildResults.any { it.guildName.contains("Zang") && it.kans >= AiConfig.PASSERINES_MIN_PERCENT_TO_INCLUDE }

            // Build candidate map from guildResults
            val candidateMap = data.guildResults.associateBy { it.soortid }

            // Start final list with BOIs (always included, limited by AiConfig.BOI_TOP_N)
            val finalList = mutableListOf<VogelSuggestie>()
            for (bh in data.rareHighlights.sortedByDescending { it.kans }.take(AiConfig.BOI_TOP_N)) {
                finalList.add(bh)
            }

            // Then add remaining guildResults sorted by kans, skipping duplicates and optionally passerines
            for (it in data.guildResults.sortedByDescending { it.kans }) {
                if (finalList.size >= AiConfig.MAX_SPECIES_PER_DAY) break
                if (boiIds.contains(it.soortid)) continue
                val isPasserine = it.guildName.contains("Zang")
                if (isPasserine && !passersAllowed) continue
                finalList.add(it)
            }

            // Render BOI section (if any)
            if (data.rareHighlights.isNotEmpty()) {
                addSectionHeader("UITKIJKEN VOOR (KRENTEN):", getColor(R.color.vt5_orange))
                data.rareHighlights.sortedByDescending { it.kans }.take(AiConfig.BOI_TOP_N).forEach { item ->
                    val view = createSpeciesCard(item, isHighlight = true, clusterIds = clusterIds)
                    container.addView(view)
                }
                addDivider()
            }

            // 3. VOEG ALGEMENE PROGNOSE TOE (Serieel) - gereduceerd / gefilterd volgens AiConfig
            if (finalList.isNotEmpty()) {
                addSectionHeader("ALGEMENE PROGNOSE:", Color.WHITE)
                finalList.forEach { item ->
                    val view = createSpeciesCard(item, isHighlight = false, clusterIds = clusterIds)
                    container.addView(view)
                }
            }
        }
    }

    private fun addSectionHeader(title: String, color: Int) {
        val tv = TextView(this)
        tv.text = title; tv.setTextColor(color); tv.textSize = 14f; tv.setPadding(24, 32, 24, 16); tv.typeface = Typeface.DEFAULT_BOLD
        container.addView(tv)
    }

    private fun addDivider() {
        val d = View(this)
        d.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 2).apply { setMargins(0, 32, 0, 16) }
        d.setBackgroundColor(Color.parseColor("#444444"))
        container.addView(d)
    }

    private suspend fun createSpeciesCard(item: VogelSuggestie, isHighlight: Boolean, clusterIds: List<String>): View {
        val view = LayoutInflater.from(this).inflate(R.layout.item_ai_suggestion, container, false)

        val tvName = view.findViewById<TextView>(R.id.tvSpeciesName)
        val tvExpected = view.findViewById<TextView>(R.id.tvExpectedIndex)
        val tvScientific = view.findViewById<TextView>(R.id.tvScientificInfo)
        val tvHistoric = view.findViewById<TextView>(R.id.tvHistoric)
        val ivIcon = view.findViewById<ImageView>(R.id.ivSpecies)
        val chartView = view.findViewById<com.patrykandpatrick.vico.views.cartesian.CartesianChartView>(R.id.sparklinePhenology)
        val viewIndicator = view.findViewById<View>(R.id.viewDateIndicator)
        val clGraph = view.findViewById<View>(R.id.clGraphContainer)

        view.findViewById<TextView>(R.id.tvGuild).text = item.guildName
        tvName.text = item.soortnaam
        tvName.setTextColor(if (isHighlight) getColor(R.color.vt5_orange) else getGuildColor(item.guildName))

        val norm = item.expectedIndex ?: 0f
        tvExpected.text = "BpH: ${"%.2f".format(norm)}"
        tvScientific.text = "BSI Kans: ${item.kans}% | Norm: ${"%.5f".format(norm)} ex/h"

        // Foto
        if (!item.latinName.isNullOrBlank()) {
            val bitmap = withContext(Dispatchers.IO) { SpeciesImageHelper.getThumbnail(item.latinName) }
            if (bitmap != null) ivIcon.setImageBitmap(bitmap)
        }

        // Data & Grafiek (52-weken distributie)
        val distWeeks = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesWeeklyDistribution(item.soortid, clusterIds) }
        val distDays = withContext(Dispatchers.IO) { database.tellingDao().getSpeciesDailyDistribution(item.soortid, clusterIds) }

        if (distWeeks.isNotEmpty()) {
            clGraph.visibility = View.VISIBLE
            PhenologySparklineHelper.setupWeekly(chartView, distWeeks)

            // Indicator
            val weekOfYear = Calendar.getInstance().get(Calendar.WEEK_OF_YEAR)
            chartView.post {
                viewIndicator.x = chartView.left + (chartView.width * (weekOfYear / 53f))
                viewIndicator.visibility = View.VISIBLE; viewIndicator.bringToFront()
            }

            // Pieken
            val spring = calculatePeak(distDays.filter { it.day <= 166 })
            val autumn = calculatePeak(distDays.filter { it.day > 166 })
            tvHistoric.text = "Historische Pieken: [$spring] [$autumn]"
            tvHistoric.visibility = View.VISIBLE
        } else {
            clGraph.visibility = View.GONE; tvHistoric.visibility = View.GONE
        }

        return view
    }

    private fun calculatePeak(dayCounts: List<DayCountRowClean>): String {
        if (dayCounts.isEmpty()) return "onbekend"
        val maxRow = dayCounts.maxByOrNull { it.count } ?: return "onbekend"
        if (maxRow.count <= 0L) return "onbekend"
        val threshold = maxRow.count * 0.5
        val window = dayCounts.filter { it.count >= threshold }
        val sdf = SimpleDateFormat("d MMM", Locale("nl", "BE"))
        val calS = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.first().day) }
        val calE = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, window.last().day) }
        return if (window.first().day == window.last().day) sdf.format(calS.time) else "${sdf.format(calS.time)} - ${sdf.format(calE.time)}"
    }

    private fun getGuildColor(guildName: String): Int {
        return when {
            guildName.contains("Zang") -> Color.CYAN
            guildName.contains("Roof") -> Color.YELLOW
            guildName.contains("Reiger") -> Color.GREEN
            guildName.contains("Zeevogels") -> Color.MAGENTA
            guildName.contains("Stelt") -> Color.parseColor("#FF9800")
            guildName.contains("Water") -> Color.parseColor("#4FC3F7")
            guildName.contains("Kust") -> Color.parseColor("#009688")
            else -> Color.LTGRAY
        }
    }
}

package com.yvesds.vt5.ai

import android.content.Context
import android.util.Log
import com.yvesds.vt5.utils.weather.WeatherManager

data class WeatherContext(
    val lat: Double,
    val lon: Double,
    val temp: Double?,
    val windSpeed: Double?,
    val windDeg: Double?,
    val cloudPercent: Double?,
    val pressure: Double?,
    val visibility: Int?
)

object AiWeatherService {
    private val TAG = "AiWeatherService"

    suspend fun fetchContextualWeather(ctx: Context, lat: Double, lon: Double): WeatherContext? {
        try {
            val current = WeatherManager.fetchCurrent(lat, lon) ?: return null
            return WeatherContext(
                lat = lat,
                lon = lon,
                temp = current.temperature_2m,
                windSpeed = current.wind_speed_10m,
                windDeg = current.wind_direction_10m,
                cloudPercent = current.cloud_cover,
                pressure = current.pressure_msl,
                visibility = WeatherManager.toVisibilityMeters(current.visibility)
            )
        } catch (e: Exception) {
            Log.w(TAG, "fetchContextualWeather failed: ${e.message}")
            return null
        }
    }
}

