package com.yvesds.vt5.features.speech

import android.content.Context
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.utils.LevenshteinUtils
import com.yvesds.vt5.utils.TextUtils
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlin.math.max

/**
 * AliasPriorityMatcher (optimized)
 *
 * - Preserves original priority cascade.
 * - Reduces allocations and avoids building/sorting full scored lists in tryFuzzyMatch.
 * - Computes query phonemes once per fuzzy match call and avoids redundant context switches.
 * - Minor housekeeping to reduce overhead inside hot loops.
 *
 * Change: integrates computePrior() into fuzzy scoring as a small contextual prior boost
 * and filters out number-like alias candidates early using NumberPatterns.isNumberCandidate.
 */
object AliasPriorityMatcher {
    private const val SUGGEST_THRESHOLD = 0.40
    private const val POPUP_MAX_CANDIDATES = 6
    private const val FUZZY_AMBIGUITY_GAP = 0.10

    // Scoring weights (sum <= 1)
    private const val W_TEXT = 0.45
    private const val W_COLOGNE = 0.35
    private const val W_PHONEME = 0.20

    // Contextual priors used by computePrior()
    private const val PRIOR_RECENT = 0.25
    private const val PRIOR_TILES = 0.25
    private const val PRIOR_SITE = 0.15
    private const val PRIOR_MAX = 0.6

    // Weight of prior in final hybrid score (tunable)
    private const val PRIOR_WEIGHT = 0.20

    private fun isNumberToken(token: String): Boolean {
        return token.toIntOrNull() != null || NumberPatterns.parseNumberWord(token) != null
    }

    private fun parseAmountToken(token: String): Int? {
        return NumberPatterns.parseNumberPhrase(token)
    }

    suspend fun match(
        hypothesis: String,
        matchContext: MatchContext,
        context: Context,
        saf: SaFStorageHelper
    ): MatchResult = withContext(Dispatchers.Default) {
        val hyp = hypothesis.trim()
        if (hyp.isBlank()) return@withContext MatchResult.NoMatch(hyp, "empty")

        AliasMatcher.ensureLoaded(context, saf)

        val normalized = TextUtils.normalizeLowerNoDiacritics(hyp)
        val tokens = normalized.split("\\s+".toRegex()).filter { it.isNotBlank() }
        if (tokens.isEmpty()) return@withContext MatchResult.NoMatch(hyp, "empty-after-norm")

        tryResolveWholePhraseMatch(tokens, hyp, matchContext, context, saf)?.let { resolved ->
            return@withContext resolved
        }

        trySegmentedMultiSpeciesMatch(tokens, hyp, matchContext, context, saf)?.let { segmented ->
            return@withContext segmented
        }

        val matches = mutableListOf<MatchResult.MatchWithAmount>()
        val consumed = BooleanArray(tokens.size)
        var i = 0
        while (i < tokens.size) {
            val maxWindow = minOf(6, tokens.size - i)
            var matched = false

            // exact matching first (canonical/alias in tiles/site)
            for (w in maxWindow downTo 1) {
                val window = tokens.subList(i, i + w)
                if (window.all { isNumberToken(it) }) { i++; matched = true; break }
                if (window.any { NumberPatterns.isNumberWord(it) }) continue
                val phrase = window.joinToString(" ")
                val exact = tryExactMatch(phrase, matchContext, context, saf)
                if (exact != null) {
                    val matchStart = i
                    val nextIndex = i + w
                    var consumedEndExclusive = nextIndex
                    var amount = 1
                    var isReturn = false

                    if (nextIndex < tokens.size) {
                        NumberPatterns.parseNumberTokens(tokens, nextIndex)?.let { parsed ->
                            amount = parsed.value
                            consumedEndExclusive = nextIndex + parsed.consumedTokenCount

                            // Check for direction after amount
                            tryMatchDirection(tokens, consumedEndExclusive, context, saf)?.let { dirLen ->
                                isReturn = true
                                consumedEndExclusive += dirLen
                            }
                        } ?: run {
                            // Check for direction directly after species (amount default 1)
                            tryMatchDirection(tokens, nextIndex, context, saf)?.let { dirLen ->
                                isReturn = true
                                consumedEndExclusive += dirLen
                            }
                        }
                    }

                    i = consumedEndExclusive
                    markConsumed(consumed, matchStart, consumedEndExclusive)

                    matches += MatchResult.MatchWithAmount(exact.first, amount, exact.second, isReturn)
                    matched = true; break
                }
            }

            if (!matched) {
                // fuzzy matching
                for (w in maxWindow downTo 1) {
                    val window = tokens.subList(i, i + w)
                    if (window.all { isNumberToken(it) }) { i++; matched = true; break }
                    if (window.any { NumberPatterns.isNumberWord(it) }) continue
                    val phrase = window.joinToString(" ")

                    val fuzzy = tryFuzzyMatch(phrase, matchContext, context, saf)
                    if (fuzzy != null) {
                        val matchStart = i
                        val nextIndex = i + w
                        var consumedEndExclusive = nextIndex
                        var amount = 1
                        var isReturn = false

                        if (nextIndex < tokens.size) {
                            NumberPatterns.parseNumberTokens(tokens, nextIndex)?.let { parsed ->
                                amount = parsed.value
                                consumedEndExclusive = nextIndex + parsed.consumedTokenCount

                                // Check for direction after amount
                                tryMatchDirection(tokens, consumedEndExclusive, context, saf)?.let { dirLen ->
                                    isReturn = true
                                    consumedEndExclusive += dirLen
                                }
                            } ?: run {
                                // Check for direction directly after species (amount default 1)
                                tryMatchDirection(tokens, nextIndex, context, saf)?.let { dirLen ->
                                    isReturn = true
                                    consumedEndExclusive += dirLen
                                }
                            }
                        }

                        i = consumedEndExclusive
                        markConsumed(consumed, matchStart, consumedEndExclusive)

                        matches += MatchResult.MatchWithAmount(fuzzy.first, amount, fuzzy.second, isReturn)
                        matched = true; break
                    }
                }
            }

            if (!matched) i++
        }

        val unmatchedFragments = buildUnmatchedFragments(tokens, consumed)

        if (matches.isEmpty()) return@withContext MatchResult.NoMatch(hyp, "no-candidates")
        if (matches.size > 1 || unmatchedFragments.isNotEmpty()) {
            return@withContext MatchResult.MultiMatch(matches, unmatchedFragments, hyp, "multi-species")
        }

        val match = matches.first()
        return@withContext toDirectMatchResult(match.candidate, hyp, match.amount, match.isReturn)
    }

    /**
     * Safer path for utterances that contain multiple counted species in one sentence.
     *
     * It tries to split the token stream into repeated blocks of:
     *   [species phrase] [amount]
     *
     * This is intentionally conservative:
     * - it only activates when the utterance contains at least two numeric tokens
     * - if a block cannot be matched confidently, the function returns null so the
     *   existing greedy matcher can still handle the utterance as before
     */
    private suspend fun trySegmentedMultiSpeciesMatch(
        tokens: List<String>,
        rawHypothesis: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): MatchResult? {
        if (tokens.count { isNumberToken(it) } < 2) return null

        val matches = mutableListOf<MatchResult.MatchWithAmount>()
        val consumed = BooleanArray(tokens.size)

        var i = 0
        while (i < tokens.size) {
            while (i < tokens.size && isNumberToken(tokens[i])) {
                i++
            }
            if (i >= tokens.size) break

            val nextNumberIndex = findNextNumberTokenIndex(tokens, i) ?: break
            if (nextNumberIndex <= i) {
                i++
                continue
            }

            val phraseTokens = tokens.subList(i, nextNumberIndex)
            if (phraseTokens.isEmpty() || phraseTokens.any { isNumberToken(it) }) {
                i = nextNumberIndex + 1
                continue
            }

            val phrase = phraseTokens.joinToString(" ").trim()
            if (phrase.isBlank()) {
                i = nextNumberIndex + 1
                continue
            }

            val amountParse = NumberPatterns.parseNumberTokens(tokens, nextNumberIndex) ?: run {
                i = nextNumberIndex + 1
                continue
            }

            val resolved = tryExactMatch(phrase, ctx, appContext, saf)
                ?: tryFuzzyMatch(phrase, ctx, appContext, saf)

            if (resolved == null) {
                i = nextNumberIndex + 1
                continue
            }

            var consumedEndExclusive = nextNumberIndex + amountParse.consumedTokenCount
            var isReturn = false
            tryMatchDirection(tokens, consumedEndExclusive, appContext, saf)?.let { dirLen ->
                isReturn = true
                consumedEndExclusive += dirLen
            }

            markConsumed(consumed, i, consumedEndExclusive)
            matches += MatchResult.MatchWithAmount(resolved.first, amountParse.value, resolved.second, isReturn)
            i = consumedEndExclusive
        }

        if (matches.isEmpty()) return null

        val unmatchedFragments = buildUnmatchedFragments(tokens, consumed)
        return if (matches.size > 1 || unmatchedFragments.isNotEmpty()) {
            MatchResult.MultiMatch(matches, unmatchedFragments, rawHypothesis, "segmented-multi-species")
        } else {
            val only = matches.first()
            toDirectMatchResult(only.candidate, rawHypothesis, only.amount, only.isReturn)
        }
    }

    private fun findNextNumberTokenIndex(tokens: List<String>, startIndex: Int): Int? {
        for (idx in startIndex until tokens.size) {
            if (isNumberToken(tokens[idx])) return idx
        }
        return null
    }

    private suspend fun tryExactMatch(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): Pair<Candidate, String>? {
        val candidates = findExactCandidates(phrase, ctx, appContext, saf)
        val best = rankCandidates(candidates, ctx).firstOrNull() ?: return null
        return best to best.source
    }

    private suspend fun tryMatchDirection(
        tokens: List<String>,
        startIndex: Int,
        appContext: Context,
        saf: SaFStorageHelper
    ): Int? {
        if (startIndex < 0 || startIndex >= tokens.size) return null

        val maxWindow = minOf(3, tokens.size - startIndex)
        for (w in maxWindow downTo 1) {
            val window = tokens.subList(startIndex, startIndex + w)
            val phrase = window.joinToString(" ")
            val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)

            // Check for exact match with _DIR_RETURN_ aliases
            val records = AliasMatcher.findExact(normalized, appContext, saf)
            if (records.any { it.speciesid == com.yvesds.vt5.features.alias.SPECIES_ID_DIR_RETURN }) {
                return w
            }

            // Fallback to fuzzy match for direction (high threshold to avoid false positives)
            val fuzzy = AliasMatcher.findFuzzyCandidates(normalized, appContext, saf, topN = 3, threshold = 0.85)
            if (fuzzy.any { it.first.speciesid == com.yvesds.vt5.features.alias.SPECIES_ID_DIR_RETURN }) {
                return w
            }
        }
        return null
    }

    private suspend fun tryResolveWholePhraseMatch(
        tokens: List<String>,
        rawHypothesis: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): MatchResult? {
        var currentTokens = tokens
        var isReturn = false

        // 1. Try match direction at the very end (up to 3 tokens window)
        var dirConsumed: Int? = null
        for (offset in 0..2) {
            val start = currentTokens.size - 1 - offset
            if (start < 0) break
            val consumed = tryMatchDirection(currentTokens, start, appContext, saf)
            if (consumed != null && start + consumed == currentTokens.size) {
                dirConsumed = consumed
                isReturn = true
                currentTokens = currentTokens.dropLast(consumed)
                break
            }
        }

        // 2. Try match number
        val trailingAmount = NumberPatterns.parseTrailingNumberTokens(currentTokens)
            ?.takeIf { it.consumedTokenCount < currentTokens.size }

        val amount = trailingAmount?.value ?: 1
        val phraseTokens = if (trailingAmount != null) {
            currentTokens.dropLast(trailingAmount.consumedTokenCount)
        } else {
            currentTokens
        }
        if (phraseTokens.any { isNumberToken(it) }) return null
        val phrase = phraseTokens.joinToString(" ").trim()
        if (phrase.isBlank()) return null

        val exactCandidates = rankCandidates(findExactCandidates(phrase, ctx, appContext, saf), ctx)
        if (exactCandidates.isNotEmpty()) {
            return when {
                shouldShowExactSuggestions(exactCandidates) -> MatchResult.SuggestionList(
                    exactCandidates.take(POPUP_MAX_CANDIDATES),
                    rawHypothesis,
                    "exact_ambiguous"
                )
                else -> toDirectMatchResult(exactCandidates.first(), rawHypothesis, amount, isReturn)
            }
        }

        val fuzzyCandidates = buildFuzzyCandidates(phrase, ctx, appContext, saf)
        if (fuzzyCandidates.isEmpty()) return null

        val top = fuzzyCandidates.first()
        if (top.score < SUGGEST_THRESHOLD) return null

        return if (shouldShowFuzzySuggestions(fuzzyCandidates)) {
            MatchResult.SuggestionList(
                fuzzyCandidates.take(POPUP_MAX_CANDIDATES),
                rawHypothesis,
                "fuzzy_ambiguous"
            )
        } else {
            toDirectMatchResult(top, rawHypothesis, amount, isReturn)
        }
    }

    private fun toDirectMatchResult(candidate: Candidate, hypothesis: String, amount: Int, isReturn: Boolean = false): MatchResult {
        return if (candidate.isInTiles) {
            MatchResult.AutoAccept(candidate, hypothesis, candidate.source, amount, isReturn)
        } else {
            MatchResult.AutoAcceptAddPopup(candidate, hypothesis, candidate.source, amount, isReturn)
        }
    }

    private suspend fun findExactCandidates(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)
        if (normalized.isBlank()) return emptyList()

        val collected = ArrayList<Candidate>(8)
        collected += findExactCanonicalCandidatesInSet(normalized, ctx.tilesSpeciesIds, "exact_canonical_tiles", ctx)
        collected += findExactCanonicalCandidatesInSet(normalized, ctx.siteAllowedIds, "exact_canonical_site", ctx)
            .filterNot { it.speciesId in ctx.tilesSpeciesIds }
        collected += findExactAliasCandidatesInSet(normalized, ctx.tilesSpeciesIds, "exact_alias_tiles", ctx, appContext, saf)
        collected += findExactAliasCandidatesInSet(normalized, ctx.siteAllowedIds, "exact_alias_site", ctx, appContext, saf)
            .filterNot { it.speciesId in ctx.tilesSpeciesIds }

        return deduplicateCandidates(collected, ctx)
    }

    // Return Candidate? if phrase exactly matches canonical name in the allowed set
    // Non-suspending: simple synchronous scan of ctx.speciesById
    private fun findExactCanonicalCandidatesInSet(
        normalized: String,
        allowed: Set<String>,
        sourceTag: String,
        ctx: MatchContext
    ): List<Candidate> {
        val nameMap = ctx.speciesById
        val results = ArrayList<Candidate>()
        for (sid in allowed) {
            val info = nameMap[sid] ?: continue
            val canon = info.first
            if (TextUtils.normalizeLowerNoDiacritics(canon) == normalized) {
                results += Candidate(
                    speciesId = sid,
                    displayName = canon,
                    score = 1.0,
                    isInTiles = sid in ctx.tilesSpeciesIds,
                    source = sourceTag,
                    autoAddToTiles = sourceTag == "exact_canonical_site" && sid !in ctx.tilesSpeciesIds
                )
            }
        }
        return results
    }

    // Return Candidate? if phrase exactly matches any alias in allowed set (consult AliasMatcher)
    // Suspend because AliasMatcher.findExact is suspend.
    private suspend fun findExactAliasCandidatesInSet(
        normalized: String,
        allowed: Set<String>,
        sourceTag: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val records = AliasMatcher.findExact(normalized, appContext, saf)
        if (records.isEmpty()) return emptyList()
        val results = ArrayList<Candidate>()
        for (r in records) {
            if (r.speciesid in allowed) {
                val display = r.canonical
                results += Candidate(
                    speciesId = r.speciesid,
                    displayName = display,
                    score = 1.0,
                    isInTiles = r.speciesid in ctx.tilesSpeciesIds,
                    source = sourceTag
                )
            }
        }
        return results
    }

    private suspend fun tryFuzzyMatch(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): Pair<Candidate, String>? {
        val candidate = buildFuzzyCandidates(phrase, ctx, appContext, saf).firstOrNull() ?: return null
        return if (candidate.score >= SUGGEST_THRESHOLD) candidate to candidate.source else null
    }

    private suspend fun buildFuzzyCandidates(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)

        val shortlist = AliasMatcher.findFuzzyCandidates(normalized, appContext, saf, topN = 50, threshold = 0.0)
        if (shortlist.isEmpty()) return emptyList()

        val filteredShortlist = shortlist.filter { pair ->
            !NumberPatterns.isNumberCandidate(pair.first)
        }
        if (filteredShortlist.isEmpty()) return emptyList()

        var needPhonemes = false
        for (p in filteredShortlist) {
            if (!p.first.phonemes.isNullOrBlank()) {
                needPhonemes = true
                break
            }
        }

        var qPh: String? = null
        if (needPhonemes) {
            qPh = runCatching { DutchPhonemizer.phonemize(normalized) }.getOrDefault("")
        }

        val bestBySpecies = LinkedHashMap<String, Candidate>()

        for (pair in filteredShortlist) {
            val rec = pair.first
            val recNorm = if (rec.norm.isNotBlank()) rec.norm else rec.alias.ifBlank { rec.canonical }
            if (recNorm.isBlank()) continue

            val textSim = LevenshteinUtils.normalizedRatio(normalized, recNorm)
            val cologneSim = runCatching { ColognePhonetic.similarity(normalized, recNorm) }.getOrDefault(0.0)
            val phonemeSim = if (!rec.phonemes.isNullOrBlank() && qPh != null) {
                runCatching { DutchPhonemizer.phonemeSimilarity(qPh, rec.phonemes) }.getOrDefault(0.0)
            } else 0.0

            val baseScore = (W_TEXT * textSim + W_COLOGNE * cologneSim + W_PHONEME * phonemeSim).coerceIn(0.0, 1.0)
            val prior = computePrior(rec.speciesid, ctx)
            val priorScaled = (prior / PRIOR_MAX).coerceIn(0.0, 1.0)
            val score = ((1.0 - PRIOR_WEIGHT) * baseScore + PRIOR_WEIGHT * priorScaled).coerceIn(0.0, 1.0)

            val candidate = Candidate(
                speciesId = rec.speciesid,
                displayName = ctx.speciesById[rec.speciesid]?.first ?: rec.canonical,
                score = score,
                isInTiles = rec.speciesid in ctx.tilesSpeciesIds,
                source = if (rec.speciesid in ctx.tilesSpeciesIds) "fuzzy_tiles" else "fuzzy_site"
            )

            val existing = bestBySpecies[rec.speciesid]
            if (existing == null || isCandidateBetter(candidate, existing, ctx)) {
                bestBySpecies[rec.speciesid] = candidate
            }
        }

        return rankCandidates(bestBySpecies.values.toList(), ctx)
    }

    private fun deduplicateCandidates(candidates: List<Candidate>, ctx: MatchContext): List<Candidate> {
        val bestBySpecies = LinkedHashMap<String, Candidate>()
        for (candidate in candidates) {
            val existing = bestBySpecies[candidate.speciesId]
            if (existing == null || isCandidateBetter(candidate, existing, ctx)) {
                bestBySpecies[candidate.speciesId] = candidate
            }
        }
        return rankCandidates(bestBySpecies.values.toList(), ctx)
    }

    private fun isCandidateBetter(candidate: Candidate, existing: Candidate, ctx: MatchContext): Boolean {
        val candidateRank = candidatePriority(candidate, ctx)
        val existingRank = candidatePriority(existing, ctx)
        return when {
            candidateRank != existingRank -> candidateRank < existingRank
            candidate.score != existing.score -> candidate.score > existing.score
            else -> candidate.displayName.length < existing.displayName.length
        }
    }

    private fun rankCandidates(candidates: List<Candidate>, ctx: MatchContext): List<Candidate> {
        return candidates.sortedWith(
            compareBy<Candidate> { candidatePriority(it, ctx) }
                .thenByDescending { it.score }
                .thenByDescending { it.speciesId in ctx.recentIds }
                .thenBy { it.displayName.lowercase() }
        )
    }

    private fun candidatePriority(candidate: Candidate, ctx: MatchContext): Int {
        return when {
            candidate.isInTiles -> 0
            candidate.source.startsWith("exact_canonical") -> 1
            candidate.source.startsWith("exact_alias") -> 2
            candidate.speciesId in ctx.siteAllowedIds -> 3
            else -> 4
        }
    }

    private fun shouldShowExactSuggestions(candidates: List<Candidate>): Boolean {
        if (candidates.size <= 1) return false
        val tileMatches = candidates.count { it.isInTiles }
        return tileMatches != 1
    }

    private fun shouldShowFuzzySuggestions(candidates: List<Candidate>): Boolean {
        if (candidates.size <= 1) return false
        val top = candidates[0]
        val second = candidates[1]
        if (top.isInTiles && !second.isInTiles) return false
        return (top.score - second.score) < FUZZY_AMBIGUITY_GAP
    }

    private fun markConsumed(consumed: BooleanArray, startInclusive: Int, endExclusive: Int) {
        val start = startInclusive.coerceAtLeast(0)
        for (idx in start until endExclusive.coerceAtMost(consumed.size)) {
            consumed[idx] = true
        }
    }

    private fun buildUnmatchedFragments(tokens: List<String>, consumed: BooleanArray): List<String> {
        val fragments = mutableListOf<String>()
        var idx = 0
        while (idx < tokens.size) {
            if (consumed[idx]) {
                idx++
                continue
            }

            val buffer = mutableListOf<String>()
            var sawWord = false
            while (idx < tokens.size && !consumed[idx]) {
                val token = tokens[idx]
                buffer += token
                if (!isNumberToken(token)) {
                    sawWord = true
                } else if (sawWord) {
                    idx++
                    break
                }
                idx++
            }

            val fragment = buffer.joinToString(" ").trim()
            if (fragment.isNotBlank()) {
                fragments += fragment
            }
        }
        return fragments
    }

    private fun computePrior(speciesId: String, ctx: MatchContext): Double {
        var prior = 0.0
        if (speciesId in ctx.recentIds) prior += PRIOR_RECENT
        if (speciesId in ctx.tilesSpeciesIds) prior += PRIOR_TILES
        if (speciesId in ctx.siteAllowedIds) prior += PRIOR_SITE
        return prior.coerceAtMost(PRIOR_MAX)
    }
}

package com.yvesds.vt5.features.speech

import android.content.Context
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.features.alias.SPECIES_ID_DIR_RETURN
import com.yvesds.vt5.utils.LevenshteinUtils
import com.yvesds.vt5.utils.TextUtils
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlin.math.max

/**
 * AliasPriorityMatcher (optimized)
 *
 * - Preserves original priority cascade.
 * - Reduces allocations and avoids building/sorting full scored lists in tryFuzzyMatch.
 * - Computes query phonemes once per fuzzy match call and avoids redundant context switches.
 * - Minor housekeeping to reduce overhead inside hot loops.
 *
 * Change: integrates computePrior() into fuzzy scoring as a small contextual prior boost
 * and filters out number-like alias candidates early using NumberPatterns.isNumberCandidate.
 */
object AliasPriorityMatcher {
    private const val SUGGEST_THRESHOLD = 0.40
    private const val POPUP_MAX_CANDIDATES = 6
    private const val FUZZY_AMBIGUITY_GAP = 0.10
    private const val DIRECTION_FUZZY_THRESHOLD = 0.85
    private const val STRICT_SINGLE_TOKEN_FUZZY_MIN_SCORE = 0.92
    private const val TILES_SINGLE_TOKEN_FUZZY_MIN_SCORE = 0.84
    private const val TILES_SINGLE_TOKEN_FUZZY_MIN_GAP = 0.18

    // Scoring weights (sum <= 1)
    private const val W_TEXT = 0.45
    private const val W_COLOGNE = 0.35
    private const val W_PHONEME = 0.20

    // Contextual priors used by computePrior()
    private const val PRIOR_RECENT = 0.25
    private const val PRIOR_TILES = 0.25
    private const val PRIOR_SITE = 0.15
    private const val PRIOR_MAX = 0.6

    // Weight of prior in final hybrid score (tunable)
    private const val PRIOR_WEIGHT = 0.20

    private fun isNumberToken(token: String): Boolean {
        return token.toIntOrNull() != null || NumberPatterns.parseNumberWord(token) != null
    }

    private fun parseAmountToken(token: String): Int? {
        return NumberPatterns.parseNumberPhrase(token)
    }

    suspend fun match(
        hypothesis: String,
        matchContext: MatchContext,
        context: Context,
        saf: SaFStorageHelper
    ): MatchResult = withContext(Dispatchers.Default) {
        val hyp = hypothesis.trim()
        if (hyp.isBlank()) return@withContext MatchResult.NoMatch(hyp, "empty")

        AliasMatcher.ensureLoaded(context, saf)

        val normalized = TextUtils.normalizeLowerNoDiacritics(hyp)
        val tokens = normalized.split("\\s+".toRegex()).filter { it.isNotBlank() }
        if (tokens.isEmpty()) return@withContext MatchResult.NoMatch(hyp, "empty-after-norm")

        tryResolveWholePhraseMatch(tokens, hyp, matchContext, context, saf)?.let { resolved ->
            return@withContext resolved
        }

        trySegmentedMultiSpeciesMatch(tokens, hyp, matchContext, context, saf)?.let { segmented ->
            return@withContext segmented
        }

        val matches = mutableListOf<MatchResult.MatchWithAmount>()
        val consumed = BooleanArray(tokens.size)
        var i = 0
        while (i < tokens.size) {
            // Treat direction/control aliases as non-species control tokens.
            // This prevents words trained as direction from being parsed as birds.
            tryMatchDirection(tokens, i, context, saf)?.let { dirLen ->
                markConsumed(consumed, i, i + dirLen)
                i += dirLen
                return@let
            }
            if (i >= tokens.size) break

            val maxWindow = minOf(6, tokens.size - i)
            var matched = false

            // exact matching first (canonical/alias in tiles/site)
            for (w in maxWindow downTo 1) {
                val window = tokens.subList(i, i + w)
                if (window.all { isNumberToken(it) }) { i++; matched = true; break }
                if (window.any { NumberPatterns.isNumberWord(it) }) continue
                val phrase = window.joinToString(" ")
                val exact = tryExactMatch(phrase, matchContext, context, saf)
                if (exact != null) {
                    val matchStart = i
                    val nextIndex = i + w
                    var consumedEndExclusive = nextIndex
                    var amount = 1
                    var isReturn = false

                    if (nextIndex < tokens.size) {
                        NumberPatterns.parseNumberTokens(tokens, nextIndex)?.let { parsed ->
                            amount = parsed.value
                            consumedEndExclusive = nextIndex + parsed.consumedTokenCount

                            // Check for direction after amount
                            tryMatchDirection(tokens, consumedEndExclusive, context, saf)?.let { dirLen ->
                                isReturn = true
                                consumedEndExclusive += dirLen
                            }
                        } ?: run {
                            // Check for direction directly after species (amount default 1)
                            tryMatchDirection(tokens, nextIndex, context, saf)?.let { dirLen ->
                                isReturn = true
                                consumedEndExclusive += dirLen
                            }
                        }
                    }

                    i = consumedEndExclusive
                    markConsumed(consumed, matchStart, consumedEndExclusive)

                    matches += MatchResult.MatchWithAmount(exact.first, amount, exact.second, isReturn)
                    matched = true; break
                }
            }

            if (!matched) {
                // fuzzy matching
                for (w in maxWindow downTo 1) {
                    val window = tokens.subList(i, i + w)
                    if (window.all { isNumberToken(it) }) { i++; matched = true; break }
                    if (window.any { NumberPatterns.isNumberWord(it) }) continue
                    val phrase = window.joinToString(" ")

                    val fuzzyPick = tryFuzzyMatch(phrase, matchContext, context, saf)
                    val fuzzy = fuzzyPick?.candidate
                    if (fuzzy != null) {
                        val matchStart = i
                        val nextIndex = i + w
                        var consumedEndExclusive = nextIndex
                        var amount = 1
                        var isReturn = false
                        val amountParse = if (nextIndex < tokens.size) {
                            NumberPatterns.parseNumberTokens(tokens, nextIndex)
                        } else {
                            null
                        }

                        if (w == 1 && amountParse == null && fuzzyPick != null && !isSafeSingleTokenFuzzyWithoutAmount(fuzzyPick)) {
                            continue
                        }

                        if (nextIndex < tokens.size) {
                            amountParse?.let { parsed ->
                                amount = parsed.value
                                consumedEndExclusive = nextIndex + parsed.consumedTokenCount

                                // Check for direction after amount
                                tryMatchDirection(tokens, consumedEndExclusive, context, saf)?.let { dirLen ->
                                    isReturn = true
                                    consumedEndExclusive += dirLen
                                }
                            } ?: run {
                                // Check for direction directly after species (amount default 1)
                                tryMatchDirection(tokens, nextIndex, context, saf)?.let { dirLen ->
                                    isReturn = true
                                    consumedEndExclusive += dirLen
                                }
                            }
                        }

                        i = consumedEndExclusive
                        markConsumed(consumed, matchStart, consumedEndExclusive)

                        matches += MatchResult.MatchWithAmount(fuzzy, amount, fuzzy.source, isReturn)
                        matched = true; break
                    }
                }
            }

            if (!matched) i++
        }

        val unmatchedFragments = buildUnmatchedFragments(tokens, consumed)

        if (matches.isEmpty()) return@withContext MatchResult.NoMatch(hyp, "no-candidates")
        if (matches.size > 1 || unmatchedFragments.isNotEmpty()) {
            return@withContext MatchResult.MultiMatch(matches, unmatchedFragments, hyp, "multi-species")
        }

        val match = matches.first()
        return@withContext toDirectMatchResult(match.candidate, hyp, match.amount, match.isReturn)
    }

    /**
     * Safer path for utterances that contain multiple counted species in one sentence.
     *
     * It tries to split the token stream into repeated blocks of:
     *   [species phrase] [amount]
     *
     * This is intentionally conservative:
     * - it only activates when the utterance contains at least two numeric tokens
     * - if a block cannot be matched confidently, the function returns null so the
     *   existing greedy matcher can still handle the utterance as before
     */
    private suspend fun trySegmentedMultiSpeciesMatch(
        tokens: List<String>,
        rawHypothesis: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): MatchResult? {
        if (tokens.count { isNumberToken(it) } < 2) return null

        val matches = mutableListOf<MatchResult.MatchWithAmount>()
        val consumed = BooleanArray(tokens.size)

        var i = 0
        while (i < tokens.size) {
            while (i < tokens.size && isNumberToken(tokens[i])) {
                i++
            }
            if (i >= tokens.size) break

            val nextNumberIndex = findNextNumberTokenIndex(tokens, i) ?: break
            if (nextNumberIndex <= i) {
                i++
                continue
            }

            val phraseTokens = tokens.subList(i, nextNumberIndex)
            if (phraseTokens.isEmpty() || phraseTokens.any { isNumberToken(it) }) {
                i = nextNumberIndex + 1
                continue
            }

            val phrase = phraseTokens.joinToString(" ").trim()
            if (phrase.isBlank()) {
                i = nextNumberIndex + 1
                continue
            }

            val amountParse = NumberPatterns.parseNumberTokens(tokens, nextNumberIndex) ?: run {
                i = nextNumberIndex + 1
                continue
            }

            val resolved = tryExactMatch(phrase, ctx, appContext, saf)
                ?: tryFuzzyMatch(phrase, ctx, appContext, saf)

            if (resolved == null) {
                i = nextNumberIndex + 1
                continue
            }

            var consumedEndExclusive = nextNumberIndex + amountParse.consumedTokenCount
            var isReturn = false
            tryMatchDirection(tokens, consumedEndExclusive, appContext, saf)?.let { dirLen ->
                isReturn = true
                consumedEndExclusive += dirLen
            }

            markConsumed(consumed, i, consumedEndExclusive)
            matches += MatchResult.MatchWithAmount(resolved.first, amountParse.value, resolved.second, isReturn)
            i = consumedEndExclusive
        }

        if (matches.isEmpty()) return null

        val unmatchedFragments = buildUnmatchedFragments(tokens, consumed)
        return if (matches.size > 1 || unmatchedFragments.isNotEmpty()) {
            MatchResult.MultiMatch(matches, unmatchedFragments, rawHypothesis, "segmented-multi-species")
        } else {
            val only = matches.first()
            toDirectMatchResult(only.candidate, rawHypothesis, only.amount, only.isReturn)
        }
    }

    private fun findNextNumberTokenIndex(tokens: List<String>, startIndex: Int): Int? {
        for (idx in startIndex until tokens.size) {
            if (isNumberToken(tokens[idx])) return idx
        }
        return null
    }

    private suspend fun tryExactMatch(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): Pair<Candidate, String>? {
        val candidates = findExactCandidates(phrase, ctx, appContext, saf)
        val best = rankCandidates(candidates, ctx).firstOrNull() ?: return null
        return best to best.source
    }

    private suspend fun tryMatchDirection(
        tokens: List<String>,
        startIndex: Int,
        appContext: Context,
        saf: SaFStorageHelper
    ): Int? {
        if (startIndex < 0 || startIndex >= tokens.size) return null

        val maxWindow = minOf(3, tokens.size - startIndex)
        for (w in maxWindow downTo 1) {
            val window = tokens.subList(startIndex, startIndex + w)
            val phrase = window.joinToString(" ")
            val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)

            // Check for exact match with _DIR_RETURN_ aliases
            val records = AliasMatcher.findExact(normalized, appContext, saf)
            if (records.any { it.speciesid == SPECIES_ID_DIR_RETURN }) {
                return w
            }

            // Fallback to fuzzy match for direction (high threshold to avoid false positives)
            val fuzzy = AliasMatcher.findFuzzyCandidates(normalized, appContext, saf, topN = 3, threshold = DIRECTION_FUZZY_THRESHOLD)
            if (fuzzy.any { it.first.speciesid == SPECIES_ID_DIR_RETURN }) {
                return w
            }
        }
        return null
    }

    private suspend fun tryResolveWholePhraseMatch(
        tokens: List<String>,
        rawHypothesis: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): MatchResult? {
        var currentTokens = tokens
        var isReturn = false

        // 1. Try match direction at the very end (up to 3 tokens window)
        var dirConsumed: Int? = null
        for (offset in 0..2) {
            val start = currentTokens.size - 1 - offset
            if (start < 0) break
            val consumed = tryMatchDirection(currentTokens, start, appContext, saf)
            if (consumed != null && start + consumed == currentTokens.size) {
                dirConsumed = consumed
                isReturn = true
                currentTokens = currentTokens.dropLast(consumed)
                break
            }
        }

        if (isReturn && currentTokens.isEmpty()) {
            return MatchResult.NoMatch(rawHypothesis, "direction-only")
        }

        // 2. Try match number
        val trailingAmount = NumberPatterns.parseTrailingNumberTokens(currentTokens)
            ?.takeIf { it.consumedTokenCount < currentTokens.size }

        val amount = trailingAmount?.value ?: 1
        val phraseTokens = if (trailingAmount != null) {
            currentTokens.dropLast(trailingAmount.consumedTokenCount)
        } else {
            currentTokens
        }
        if (phraseTokens.any { isNumberToken(it) }) return null
        val phrase = phraseTokens.joinToString(" ").trim()
        if (phrase.isBlank()) return null

        val exactCandidates = rankCandidates(findExactCandidates(phrase, ctx, appContext, saf), ctx)
        if (exactCandidates.isNotEmpty()) {
            return when {
                shouldShowExactSuggestions(exactCandidates) -> MatchResult.SuggestionList(
                    exactCandidates.take(POPUP_MAX_CANDIDATES),
                    rawHypothesis,
                    "exact_ambiguous"
                )
                else -> toDirectMatchResult(exactCandidates.first(), rawHypothesis, amount, isReturn)
            }
        }

        val fuzzyCandidates = buildFuzzyCandidates(phrase, ctx, appContext, saf)
        if (fuzzyCandidates.isEmpty()) return null

        val top = fuzzyCandidates.first()
        if (top.score < SUGGEST_THRESHOLD) return null

        return if (shouldShowFuzzySuggestions(fuzzyCandidates)) {
            MatchResult.SuggestionList(
                fuzzyCandidates.take(POPUP_MAX_CANDIDATES),
                rawHypothesis,
                "fuzzy_ambiguous"
            )
        } else {
            toDirectMatchResult(top, rawHypothesis, amount, isReturn)
        }
    }

    private fun toDirectMatchResult(candidate: Candidate, hypothesis: String, amount: Int, isReturn: Boolean = false): MatchResult {
        return if (candidate.isInTiles) {
            MatchResult.AutoAccept(candidate, hypothesis, candidate.source, amount, isReturn)
        } else {
            MatchResult.AutoAcceptAddPopup(candidate, hypothesis, candidate.source, amount, isReturn)
        }
    }

    private suspend fun findExactCandidates(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)
        if (normalized.isBlank()) return emptyList()

        val collected = ArrayList<Candidate>(8)
        collected += findExactCanonicalCandidatesInSet(normalized, ctx.tilesSpeciesIds, "exact_canonical_tiles", ctx)
        collected += findExactCanonicalCandidatesInSet(normalized, ctx.siteAllowedIds, "exact_canonical_site", ctx)
            .filterNot { it.speciesId in ctx.tilesSpeciesIds }
        collected += findExactAliasCandidatesInSet(normalized, ctx.tilesSpeciesIds, "exact_alias_tiles", ctx, appContext, saf)
        collected += findExactAliasCandidatesInSet(normalized, ctx.siteAllowedIds, "exact_alias_site", ctx, appContext, saf)
            .filterNot { it.speciesId in ctx.tilesSpeciesIds }

        return deduplicateCandidates(collected, ctx)
    }

    // Return Candidate? if phrase exactly matches canonical name in the allowed set
    // Non-suspending: simple synchronous scan of ctx.speciesById
    private fun findExactCanonicalCandidatesInSet(
        normalized: String,
        allowed: Set<String>,
        sourceTag: String,
        ctx: MatchContext
    ): List<Candidate> {
        val nameMap = ctx.speciesById
        val results = ArrayList<Candidate>()
        for (sid in allowed) {
            val info = nameMap[sid] ?: continue
            val canon = info.first
            if (TextUtils.normalizeLowerNoDiacritics(canon) == normalized) {
                results += Candidate(
                    speciesId = sid,
                    displayName = canon,
                    score = 1.0,
                    isInTiles = sid in ctx.tilesSpeciesIds,
                    source = sourceTag,
                    autoAddToTiles = sourceTag == "exact_canonical_site" && sid !in ctx.tilesSpeciesIds
                )
            }
        }
        return results
    }

    // Return Candidate? if phrase exactly matches any alias in allowed set (consult AliasMatcher)
    // Suspend because AliasMatcher.findExact is suspend.
    private suspend fun findExactAliasCandidatesInSet(
        normalized: String,
        allowed: Set<String>,
        sourceTag: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val records = AliasMatcher.findExact(normalized, appContext, saf)
        if (records.isEmpty()) return emptyList()
        val results = ArrayList<Candidate>()
        for (r in records) {
            if (r.speciesid in allowed) {
                val display = r.canonical
                results += Candidate(
                    speciesId = r.speciesid,
                    displayName = display,
                    score = 1.0,
                    isInTiles = r.speciesid in ctx.tilesSpeciesIds,
                    source = sourceTag
                )
            }
        }
        return results
    }

    private data class FuzzyPick(
        val candidate: Candidate,
        val candidates: List<Candidate>
    )

    private suspend fun tryFuzzyMatch(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): FuzzyPick? {
        val candidates = buildFuzzyCandidates(phrase, ctx, appContext, saf)
        val candidate = candidates.firstOrNull() ?: return null
        return if (candidate.score >= SUGGEST_THRESHOLD) {
            FuzzyPick(candidate = candidate, candidates = candidates)
        } else {
            null
        }
    }

    private fun isSafeSingleTokenFuzzyWithoutAmount(pick: FuzzyPick): Boolean {
        val top = pick.candidate
        if (top.score >= STRICT_SINGLE_TOKEN_FUZZY_MIN_SCORE) return true
        if (!top.isInTiles || top.score < TILES_SINGLE_TOKEN_FUZZY_MIN_SCORE) return false

        val second = pick.candidates.getOrNull(1) ?: return true
        return (top.score - second.score) >= TILES_SINGLE_TOKEN_FUZZY_MIN_GAP
    }

    private suspend fun buildFuzzyCandidates(
        phrase: String,
        ctx: MatchContext,
        appContext: Context,
        saf: SaFStorageHelper
    ): List<Candidate> {
        val normalized = TextUtils.normalizeLowerNoDiacritics(phrase)

        val shortlist = AliasMatcher.findFuzzyCandidates(normalized, appContext, saf, topN = 50, threshold = 0.0)
        if (shortlist.isEmpty()) return emptyList()

        val filteredShortlist = shortlist.filter { pair ->
            pair.first.speciesid != SPECIES_ID_DIR_RETURN && !NumberPatterns.isNumberCandidate(pair.first)
        }
        if (filteredShortlist.isEmpty()) return emptyList()

        var needPhonemes = false
        for (p in filteredShortlist) {
            if (!p.first.phonemes.isNullOrBlank()) {
                needPhonemes = true
                break
            }
        }

        var qPh: String? = null
        if (needPhonemes) {
            qPh = runCatching { DutchPhonemizer.phonemize(normalized) }.getOrDefault("")
        }

        val bestBySpecies = LinkedHashMap<String, Candidate>()

        for (pair in filteredShortlist) {
            val rec = pair.first
            val recNorm = if (rec.norm.isNotBlank()) rec.norm else rec.alias.ifBlank { rec.canonical }
            if (recNorm.isBlank()) continue

            val textSim = LevenshteinUtils.normalizedRatio(normalized, recNorm)
            val cologneSim = runCatching { ColognePhonetic.similarity(normalized, recNorm) }.getOrDefault(0.0)
            val phonemeSim = if (!rec.phonemes.isNullOrBlank() && qPh != null) {
                runCatching { DutchPhonemizer.phonemeSimilarity(qPh, rec.phonemes) }.getOrDefault(0.0)
            } else 0.0

            val baseScore = (W_TEXT * textSim + W_COLOGNE * cologneSim + W_PHONEME * phonemeSim).coerceIn(0.0, 1.0)
            val prior = computePrior(rec.speciesid, ctx)
            val priorScaled = (prior / PRIOR_MAX).coerceIn(0.0, 1.0)
            val score = ((1.0 - PRIOR_WEIGHT) * baseScore + PRIOR_WEIGHT * priorScaled).coerceIn(0.0, 1.0)

            val candidate = Candidate(
                speciesId = rec.speciesid,
                displayName = ctx.speciesById[rec.speciesid]?.first ?: rec.canonical,
                score = score,
                isInTiles = rec.speciesid in ctx.tilesSpeciesIds,
                source = if (rec.speciesid in ctx.tilesSpeciesIds) "fuzzy_tiles" else "fuzzy_site"
            )

            val existing = bestBySpecies[rec.speciesid]
            if (existing == null || isCandidateBetter(candidate, existing, ctx)) {
                bestBySpecies[rec.speciesid] = candidate
            }
        }

        return rankCandidates(bestBySpecies.values.toList(), ctx)
    }

    private fun deduplicateCandidates(candidates: List<Candidate>, ctx: MatchContext): List<Candidate> {
        val bestBySpecies = LinkedHashMap<String, Candidate>()
        for (candidate in candidates) {
            val existing = bestBySpecies[candidate.speciesId]
            if (existing == null || isCandidateBetter(candidate, existing, ctx)) {
                bestBySpecies[candidate.speciesId] = candidate
            }
        }
        return rankCandidates(bestBySpecies.values.toList(), ctx)
    }

    private fun isCandidateBetter(candidate: Candidate, existing: Candidate, ctx: MatchContext): Boolean {
        val candidateRank = candidatePriority(candidate, ctx)
        val existingRank = candidatePriority(existing, ctx)
        return when {
            candidateRank != existingRank -> candidateRank < existingRank
            candidate.score != existing.score -> candidate.score > existing.score
            else -> candidate.displayName.length < existing.displayName.length
        }
    }

    private fun rankCandidates(candidates: List<Candidate>, ctx: MatchContext): List<Candidate> {
        return candidates.sortedWith(
            compareBy<Candidate> { candidatePriority(it, ctx) }
                .thenByDescending { it.score }
                .thenByDescending { it.speciesId in ctx.recentIds }
                .thenBy { it.displayName.lowercase() }
        )
    }

    private fun candidatePriority(candidate: Candidate, ctx: MatchContext): Int {
        return when {
            candidate.isInTiles -> 0
            candidate.source.startsWith("exact_canonical") -> 1
            candidate.source.startsWith("exact_alias") -> 2
            candidate.speciesId in ctx.siteAllowedIds -> 3
            else -> 4
        }
    }

    private fun shouldShowExactSuggestions(candidates: List<Candidate>): Boolean {
        if (candidates.size <= 1) return false
        val tileMatches = candidates.count { it.isInTiles }
        return tileMatches != 1
    }

    private fun shouldShowFuzzySuggestions(candidates: List<Candidate>): Boolean {
        if (candidates.size <= 1) return false
        val top = candidates[0]
        val second = candidates[1]
        if (top.isInTiles && !second.isInTiles) return false
        return (top.score - second.score) < FUZZY_AMBIGUITY_GAP
    }

    private fun markConsumed(consumed: BooleanArray, startInclusive: Int, endExclusive: Int) {
        val start = startInclusive.coerceAtLeast(0)
        for (idx in start until endExclusive.coerceAtMost(consumed.size)) {
            consumed[idx] = true
        }
    }

    private fun buildUnmatchedFragments(tokens: List<String>, consumed: BooleanArray): List<String> {
        val fragments = mutableListOf<String>()
        var idx = 0
        while (idx < tokens.size) {
            if (consumed[idx]) {
                idx++
                continue
            }

            val buffer = mutableListOf<String>()
            var sawWord = false
            while (idx < tokens.size && !consumed[idx]) {
                val token = tokens[idx]
                buffer += token
                if (!isNumberToken(token)) {
                    sawWord = true
                } else if (sawWord) {
                    idx++
                    break
                }
                idx++
            }

            val fragment = buffer.joinToString(" ").trim()
            if (fragment.isNotBlank()) {
                fragments += fragment
            }
        }
        return fragments
    }

    private fun computePrior(speciesId: String, ctx: MatchContext): Double {
        var prior = 0.0
        if (speciesId in ctx.recentIds) prior += PRIOR_RECENT
        if (speciesId in ctx.tilesSpeciesIds) prior += PRIOR_TILES
        if (speciesId in ctx.siteAllowedIds) prior += PRIOR_SITE
        return prior.coerceAtMost(PRIOR_MAX)
    }
}

package com.yvesds.vt5.core.opslag

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.*
import androidx.datastore.preferences.preferencesDataStore
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map

// Extensie property voor DataStore
private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "vt5_settings")

/**
 * AppDataStore: Moderne vervanging voor SharedPreferences voor persistente instellingen en tellers.
 * Gebruikt Jetpack DataStore Preferences.
 */
object AppDataStore {
    private val KEY_NEXT_TELLING_ID = longPreferencesKey("next_telling_id")
    private val KEY_AI_ENABLED = booleanPreferencesKey("ai_enabled")
    private val KEY_AI_MODEL_DIR_URI = stringPreferencesKey("ai_model_dir_uri")
    private val KEY_KRENTEN_THRESHOLD = intPreferencesKey("ai_krenten_threshold")
    private const val PREFIX_RECORD_ID = "next_record_id_"

    /**
     * Haalt het volgende unieke telling ID op en verhoogt de teller.
     */
    suspend fun nextTellingId(context: Context): String {
        var result = 1L
        context.dataStore.edit { prefs ->
            val current = prefs[KEY_NEXT_TELLING_ID] ?: 1L
            result = current
            prefs[KEY_NEXT_TELLING_ID] = current + 1L
        }
        return result.toString()
    }

    /**
     * Reserveer een blok telling IDs voor bulk imports.
     */
    suspend fun reserveTellingIds(context: Context, amount: Int): LongRange {
        var start = 1L
        context.dataStore.edit { prefs ->
            val current = prefs[KEY_NEXT_TELLING_ID] ?: 1L
            start = current
            prefs[KEY_NEXT_TELLING_ID] = current + amount.toLong()
        }
        return start until (start + amount)
    }

    /**
     * Zet de telling ID teller terug naar 1.
     */
    suspend fun resetTellingId(context: Context) {
        context.dataStore.edit { prefs ->
            prefs[KEY_NEXT_TELLING_ID] = 1L
        }
    }

    /**
     * Haalt het volgende record ID op voor een specifieke telling.
     */
    suspend fun nextRecordId(context: Context, tellingId: String): String {
        val key = longPreferencesKey(PREFIX_RECORD_ID + tellingId)
        var result = 1L
        context.dataStore.edit { prefs ->
            val current = prefs[key] ?: 1L
            result = current
            prefs[key] = current + 1L
        }
        return result.toString()
    }

    /**
     * AI-gerelateerde instellingen.
     */
    suspend fun setAiEnabled(context: Context, enabled: Boolean) {
        context.dataStore.edit { prefs ->
            prefs[KEY_AI_ENABLED] = enabled
        }
    }

    suspend fun isAiEnabled(context: Context): Boolean {
        return context.dataStore.data.map { it[KEY_AI_ENABLED] ?: false }.first()
    }

    suspend fun setAiModelDirUri(context: Context, uri: String?) {
        context.dataStore.edit { prefs ->
            if (uri == null) prefs.remove(KEY_AI_MODEL_DIR_URI)
            else prefs[KEY_AI_MODEL_DIR_URI] = uri
        }
    }

    suspend fun getAiModelDirUri(context: Context): String? {
        return context.dataStore.data.map { it[KEY_AI_MODEL_DIR_URI] }.first()
    }

    suspend fun setKrentenThreshold(context: Context, threshold: Int) {
        context.dataStore.edit { prefs ->
            prefs[KEY_KRENTEN_THRESHOLD] = threshold
        }
    }

    suspend fun getKrentenThreshold(context: Context): Int {
        return context.dataStore.data.map { it[KEY_KRENTEN_THRESHOLD] ?: 100 }.first()
    }
}

