    private fun promptForClientIdentity(onConfirmed: () -> Unit) {
        val input = EditText(this).apply {
            hint = getString(R.string.mc_client_identity_hint)
            setSingleLine(true)
            setText(MasterClientPrefs.getClientAlias(this@HoofdActiviteit))
