        const val PREF_PERM_SAF_ACK = "pref_perm_saf_ack"
        const val PREF_PERM_LOCATION_ACK = "pref_perm_location_ack"
        const val PREF_PERM_CAMERA_ACK = "pref_perm_camera_ack"
