package com.yvesds.vt5.features.soort.ui

import android.os.Bundle
import android.text.Editable
import android.text.TextWatcher
import android.util.Log
import android.view.View
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.isVisible
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.yvesds.vt5.R
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.core.ui.ProgressDialogHelper
import com.yvesds.vt5.databinding.SchermSoortSelectieBinding
import com.yvesds.vt5.features.alias.AliasManager
import com.yvesds.vt5.features.recent.SpeciesUsageScoreStore
import com.yvesds.vt5.features.serverdata.model.DataSnapshot
import com.yvesds.vt5.features.serverdata.model.ServerDataCache
import com.yvesds.vt5.features.telling.TellingSessionManager
import com.yvesds.vt5.hoofd.InstellingenScherm
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.Normalizer
import java.util.Locale
import java.util.concurrent.ConcurrentHashMap

/**
 * Soort-voorselectie met geoptimaliseerde prestaties:
 * - Efficiënte caching en data-filtering
 * - Verbeterde zoekfunctionaliteit met normalisatie
 * - Geoptimaliseerde UI updates met DiffUtil en payloads
 * - Verminderde GC pressure door object pooling
 * - Sectioned adapter met "recente soorten" bovenaan
 * 
 * UPDATE: Gebruikt nu ALLE unieke soorten uit alias_master.json (via AliasManager)
 * in plaats van site-specifieke filtering. Dit zorgt voor een complete soortenlijst
 * die alle soorten uit site_species.json bevat, ongeacht telpost assignment.
 */
class SoortSelectieScherm : AppCompatActivity() {

    private lateinit var binding: SchermSoortSelectieBinding
    private val uiScope = CoroutineScope(Job() + Dispatchers.Main)

    private var telpostId: String? = null
    private var snapshot: DataSnapshot = DataSnapshot()

    // SAF helper for alias manager access
    private lateinit var saf: SaFStorageHelper

    // Datamodels
    data class Row(val soortId: String, val naam: String) {
        // Performance: Lazy cache voor genormaliseerde naam - alleen berekend bij eerste gebruik
        // Vermijdt onnodige string normalisatie voor items die nooit gezocht worden
        val normalizedName: String by lazy { normalizeString(naam) }
    }

    // Alfabetische basislijst (site-filter toegepast indien beschikbaar)
    private var baseAlphaRows: List<Row> = emptyList()
    // Wereldwijde soortenlijst (alle soorten uit species.json, voor uitgebreide zoekfunctie)
    private var worldSpeciesRows: List<Row> = emptyList()
    // Set van site species IDs voor snelle lookup
    private var siteSpeciesIds: Set<String> = emptySet()
    // Cache voor snelle lookup op ID (inclusief wereldwijde soorten)
    private var rowsByIdCache = ConcurrentHashMap<String, Row>()

    // Recents (subset van baseAlphaRows, meest recent eerst)
    private var recentRows: List<Row> = emptyList()
    private val recentIds: Set<String> get() = recentRows.map { it.soortId }.toSet()

    // Geselecteerde ids
    private val selectedIds = mutableSetOf<String>()

    // Adapters
    private lateinit var gridAdapter: SoortSelectieSectionedAdapter
    private lateinit var suggestAdapter: SoortSelectieAdapter

    // Laatste zoekopdracht voor onResume restore
    private var lastSearchQuery = ""

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = SchermSoortSelectieBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Initialize SAF helper for alias manager access
        saf = SaFStorageHelper(this)

        telpostId = intent.getStringExtra(EXTRA_TELPOST_ID)

        // Begin met de (eventuele) preselecties die door MetadataScherm zijn gezet.
        // Zodat de gebruiker de voorgestelde soorten kan zien/wijzigen en bij OK
        // de aangepaste selectie teruggezet wordt in TellingSessionManager.
        selectedIds.clear()
        // Default: geen vakjes aangevinkt tenzij expliciet preselected door MetadataScherm
        selectedIds.addAll(TellingSessionManager.preselectState.value.selectedSoortIds)

        setupAdapters()
        setupListeners()
        loadData()
    }
    private fun setupAdapters() {
        // GRID: sectioned (recents header + items)
        gridAdapter = SoortSelectieSectionedAdapter(
            isSelected = { id -> id in selectedIds },
            onToggleSpecies = { id, checked, position ->
                if (checked) selectedIds += id else selectedIds -= id
                gridAdapter.notifyItemChanged(position, SoortSelectieSectionedAdapter.PAYLOAD_SELECTION)

                // Update suggesties indien zichtbaar
                updateSuggestionsSelection()

                // Header checkbox updaten (alle recents geselecteerd?)
                updateHeaderState()

                updateCounter()
            },
            onToggleAllRecents = { checked ->
                if (checked) {
                    selectedIds.addAll(recentIds)
                } else {
                    selectedIds.removeAll(recentIds)
                }

                // Alleen recents-items refreshen + headerstate bijwerken
                gridAdapter.notifyRecentsSelectionChanged(recentIds)

                // Update suggesties indien zichtbaar
                updateSuggestionsSelection()

                updateCounter()
            }
        )

        // Optimalisatie: SpanSizeLookup voor header over volle breedte
        val spanCount = if (resources.configuration.smallestScreenWidthDp >= 600) 3 else 2
        val glm = GridLayoutManager(this, spanCount, RecyclerView.VERTICAL, false).apply {
            spanSizeLookup = object : GridLayoutManager.SpanSizeLookup() {
                override fun getSpanSize(position: Int): Int {
                    return when {
                        gridAdapter.isHeader(position) -> spanCount // Header over volle breedte
                        gridAdapter.isFooter(position) -> spanCount // Footer over volle breedte
                        else -> 1                           // Items in 2 kolommen
                    }
                }
            }
        }
        // Pool instellen voor view recycling
        binding.rvSoorten.setItemViewCacheSize(30)
        binding.rvSoorten.layoutManager = glm
        binding.rvSoorten.setHasFixedSize(true)
        binding.rvSoorten.adapter = gridAdapter

        // SUGGESTIES: eenvoudige lijst (zelfde rijlayout)
        suggestAdapter = SoortSelectieAdapter(
            isSelected = { id -> id in selectedIds },
            onToggle = { id, checked, position ->
                if (checked) selectedIds += id else selectedIds -= id

                // Update het item in de suggestielijst
                suggestAdapter.notifyItemChanged(position, SoortSelectieAdapter.PAYLOAD_SELECTION)

                // Zoek en update het corresponderende item in de grid
                val idx = gridAdapter.currentList.indexOfFirst {
                    it is SoortSelectieSectionedAdapter.RowUi.Species && it.item.soortId == id
                }
                if (idx >= 0) gridAdapter.notifyItemChanged(idx, SoortSelectieSectionedAdapter.PAYLOAD_SELECTION)

                // Update header status
                updateHeaderState()
                updateCounter()
            }
        )

        binding.rvSuggesties.layoutManager = LinearLayoutManager(this)
        binding.rvSuggesties.setHasFixedSize(true)
        binding.rvSuggesties.adapter = suggestAdapter
        showSuggestions(false)
    }

    private fun setupListeners() {
        binding.btnAnnuleer.setOnClickListener {
            setResult(RESULT_CANCELED)
            finish()
        }

        binding.btnOk.setOnClickListener {
            // Pas bij bevestigen de keuze opslaan in de session manager
            val chosen = ArrayList(selectedIds)
            TellingSessionManager.setPreselectedSoorten(chosen)
            val data = intent.apply { putExtra(EXTRA_SELECTED_SOORT_IDS, chosen) }
            setResult(RESULT_OK, data)
            finish()
        }

        // Debounced zoekfunctie (optimalisatie)
        val searchJob = arrayOfNulls<Job>(1)
        binding.etZoek.addTextChangedListener(object : TextWatcher {
            override fun afterTextChanged(s: Editable?) {
                val query = s?.toString().orEmpty()
                lastSearchQuery = query

                // Cancel lopende zoekopdracht en start een nieuwe na kleine vertraging
                searchJob[0]?.cancel()
                searchJob[0] = uiScope.launch {
                    updateSuggestions(query)
                }
            }
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}
        })
    }

    private fun loadData() {
        uiScope.launch {
            try {
                // Fast-path: check cache first without showing dialog
                val cachedData = ServerDataCache.getCachedOrNull()
                if (cachedData?.hasSpeciesData() == true) {
                    // Cache hit - process immediately without dialog
                    snapshot = cachedData

                    // Process data synchronously (it's fast with cached data)
                    baseAlphaRows = buildAlphaRowsForTelpost()

                    // Build site species ID set for quick lookup
                    siteSpeciesIds = baseAlphaRows.map { it.soortId }.toSet()

                    // Build world species list (alle species.json soorten die NIET in site_species zitten)
                    worldSpeciesRows = buildWorldSpeciesRows()

                    // Build ID cache for O(1) lookups (inclusief wereldwijde soorten)
                    rowsByIdCache.clear()
                    baseAlphaRows.forEach { row -> rowsByIdCache[row.soortId] = row }
                    worldSpeciesRows.forEach { row -> rowsByIdCache[row.soortId] = row }

                    recentRows = computeRecents(baseAlphaRows)
                    submitGrid(recents = recentRows, restAlpha = baseAlphaRows.filterNot { it.soortId in recentIds })
                    updateCounter()

                    return@launch
                }

                // Slow-path: need to load from storage
                val dialog = ProgressDialogHelper.show(this@SoortSelectieScherm, "Soorten laden...")

                try {
                    snapshot = withContext(Dispatchers.IO) {
                        ServerDataCache.getOrLoad(this@SoortSelectieScherm)
                    }

                    // Basislijst opbouwen en sorteren
                    baseAlphaRows = buildAlphaRowsForTelpost()

                    // Build site species ID set for quick lookup
                    siteSpeciesIds = baseAlphaRows.map { it.soortId }.toSet()

                    // Build world species list (alle species.json soorten die NIET in site_species zitten)
                    worldSpeciesRows = buildWorldSpeciesRows()

                    // ID cache opbouwen voor snelle lookup (inclusief wereldwijde soorten)
                    rowsByIdCache.clear()
                    baseAlphaRows.forEach { row -> rowsByIdCache[row.soortId] = row }
                    worldSpeciesRows.forEach { row -> rowsByIdCache[row.soortId] = row }

                    // Recents berekenen
                    recentRows = computeRecents(baseAlphaRows)

                    // Submit naar grid
                    submitGrid(recents = recentRows, restAlpha = baseAlphaRows.filterNot { it.soortId in recentIds })
                    updateCounter()

                    if (baseAlphaRows.isEmpty()) {
                        Toast.makeText(this@SoortSelectieScherm, getString(R.string.soort_no_species_download), Toast.LENGTH_LONG).show()
                    }
                } finally {
                    dialog.dismiss()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error loading data", e)
                Toast.makeText(this@SoortSelectieScherm, getString(R.string.soort_error_loading, e.message ?: ""), Toast.LENGTH_LONG).show()
            }
        }
    }

    /**
     * Build alphabetically sorted species list.
     * 
     * NEW: Uses ALL unique species from alias_master.json (via AliasManager)
     * instead of filtering by telpost. This provides the complete "truth list"
     * of all species from site_species.json regardless of site assignment.
     * 
     * Performance: Runs synchronously but data is already loaded in memory
     * by AliasManager (loaded during MetadataScherm background preload).
     */
    private suspend fun buildAlphaRowsForTelpost(): List<Row> = withContext(Dispatchers.IO) {
        // Try to get all species from alias index first (preferred source)
        val aliasSpecies = try {
            AliasManager.getAllSpeciesFromIndex(this@SoortSelectieScherm, saf)
        } catch (ex: Exception) {
            Log.w(TAG, "Failed to get species from alias index: ${ex.message}")
            emptyMap()
        }

        // If alias index has species, use that as the source of truth
        val base = if (aliasSpecies.isNotEmpty()) {
            ArrayList<Row>(aliasSpecies.size).apply {
                aliasSpecies.forEach { (sid, naam) ->
                    add(Row(sid, naam))
                }
            }
        } else {
            // Fallback to snapshot.speciesById (all species, no filtering)
            ArrayList<Row>(snapshot.speciesById.size).apply {
                snapshot.speciesById.values.forEach { 
                    add(Row(it.soortid, it.soortnaam)) 
                }
            }
        }

        // Sort by pre-computed lowercase to avoid repeated lowercase() calls
        return@withContext base.sortedBy { it.naam.lowercase() }
    }

    /**
     * Build world species list from species.json (snapshot.speciesById).
     * 
     * Contains ONLY species that are NOT in the site species list (siteSpeciesIds).
     * This allows the search function to extend beyond site-specific species
     * when no match is found in the site species list.
     * 
     * Performance: O(n) filter but cached in memory for fast search.
     */
    private fun buildWorldSpeciesRows(): List<Row> {
        // Filter species.json to exclude those already in site_species, map to Row and sort
        return snapshot.speciesById.values
            .filter { it.soortid !in siteSpeciesIds }
            .map { Row(it.soortid, it.soortnaam) }
            .sortedBy { it.naam.lowercase() }
    }

    /**
     * Check if a row matches the normalized search query.
     */
    private fun matchesQuery(row: Row, normalizedQuery: String): Boolean {
        return row.normalizedName.contains(normalizedQuery) || 
               row.soortId.lowercase().contains(normalizedQuery)
    }

    private fun computeRecents(baseAlpha: List<Row>): List<Row> {
        val prefLimit = InstellingenScherm.getMaxFavorieten(this)
        val recentsOrderedIds = SpeciesUsageScoreStore.getTopSpeciesIds(
            this,
            limit = if (prefLimit == InstellingenScherm.MAX_FAVORIETEN_ALL) 0 else prefLimit
        )

        // Pre-allocate result list with expected size
        val result = ArrayList<Row>(recentsOrderedIds.size.coerceAtMost(baseAlpha.size))

        // Use the cached rowsByIdCache for O(1) lookups if available, otherwise build temporary map
        if (rowsByIdCache.isNotEmpty()) {
            recentsOrderedIds.forEach { id ->
                rowsByIdCache[id]?.let { result.add(it) }
            }
        } else {
            // Fallback: build temporary map (should rarely happen)
            val byId = baseAlpha.associateBy { it.soortId }
            recentsOrderedIds.forEach { id ->
                byId[id]?.let { result.add(it) }
            }
        }

        return result
    }

    private fun submitGrid(recents: List<Row>, restAlpha: List<Row>) {
        // Pre-allocate list with known capacity to avoid resizing
        val estimatedSize = if (recents.isNotEmpty()) {
            recents.size + restAlpha.size + 2 // +2 for header and footer
        } else {
            restAlpha.size
        }
        val items = ArrayList<SoortSelectieSectionedAdapter.RowUi>(estimatedSize)

        if (recents.isNotEmpty()) {
            // Check if all recents are selected (optimized with any { } short-circuit)
            val allSel = !recents.any { !selectedIds.contains(it.soortId) }

            // Header voor recente items
            items.add(SoortSelectieSectionedAdapter.RowUi.RecentsHeader(recentsCount = recents.size, allSelected = allSel))

            // Recente items als speciale visuele groep (direct add to avoid intermediate list)
            recents.forEach { items.add(SoortSelectieSectionedAdapter.RowUi.RecenteSpecies(it)) }

            // Footer divider voor afsluiting van recente groep
            items.add(SoortSelectieSectionedAdapter.RowUi.RecentsFooter)
        }

        // Rest van de items zoals gewoonlijk (direct add to avoid intermediate list)
        restAlpha.forEach { items.add(SoortSelectieSectionedAdapter.RowUi.Species(it)) }

        gridAdapter.submitList(items)
    }
    /**
     * Normaliseert een string voor insensitive zoeken
     * - lowercase
     * - diacritics verwijderen
     * - trim en extra spaces verwijderen
     */
    private fun updateSuggestions(q: String) {
        val text = q.trim()
        if (text.isEmpty()) {
            suggestAdapter.submitList(emptyList())
            showSuggestions(false)
            // rebuild grid (recents + rest) zodat header-state klopt
            // Optimize: avoid creating intermediate filtered list
            val restAlpha = if (recentIds.isEmpty()) {
                baseAlphaRows
            } else {
                baseAlphaRows.filterNot { it.soortId in recentIds }
            }
            submitGrid(recentRows, restAlpha)
            updateCounter()
            return
        }

        // Normaliseren voor case-insensitive en diacritiek-insensitive zoeken
        val normalizedQuery = normalizeString(text)

        val max = 12
        // Pre-allocate result list to avoid resizing
        val filtered = ArrayList<Row>(max)

        // Eerst zoeken in site_species (baseAlphaRows)
        for (row in baseAlphaRows) {
            if (matchesQuery(row, normalizedQuery)) {
                filtered.add(row)
                if (filtered.size >= max) break
            }
        }

        // Als er niet genoeg resultaten zijn, ook zoeken in de wereldlijst (species.json)
        if (filtered.size < max) {
            for (row in worldSpeciesRows) {
                if (matchesQuery(row, normalizedQuery)) {
                    filtered.add(row)
                    if (filtered.size >= max) break
                }
            }
        }

        suggestAdapter.submitList(filtered)
        showSuggestions(filtered.isNotEmpty())
        updateCounter()
    }

    /**
     * Update de selectiestatus in suggesties (indien zichtbaar)
     */
    private fun updateSuggestionsSelection() {
        if (binding.rvSuggesties.isVisible) {
            for (i in 0 until suggestAdapter.itemCount) {
                suggestAdapter.notifyItemChanged(i, SoortSelectieAdapter.PAYLOAD_SELECTION)
            }
        }
    }

    /**
     * Update de header checkbox status op basis van selecties
     */
    private fun updateHeaderState() {
        val idx = gridAdapter.currentList.indexOfFirst { it is SoortSelectieSectionedAdapter.RowUi.RecentsHeader }
        if (idx >= 0) {
            val allRecentsSelected = recentIds.isNotEmpty() && recentIds.all { it in selectedIds }
            val header = (gridAdapter.currentList[idx] as? SoortSelectieSectionedAdapter.RowUi.RecentsHeader)?.copy(allSelected = allRecentsSelected)
                ?: return

            // Update alleen als status veranderd is
            val current = gridAdapter.currentList[idx] as? SoortSelectieSectionedAdapter.RowUi.RecentsHeader
            if (current?.allSelected != header.allSelected) {
                val updatedList = gridAdapter.currentList.toMutableList().apply {
                    set(idx, header)
                }
                gridAdapter.submitList(updatedList)
                gridAdapter.notifyItemChanged(idx, SoortSelectieSectionedAdapter.PAYLOAD_HEADER_STATE)
            }
        }
    }

    private fun showSuggestions(visible: Boolean) {
        binding.rvSuggesties.visibility = if (visible) View.VISIBLE else View.GONE
        binding.dividerTop.visibility = binding.rvSuggesties.visibility
        binding.dividerBottom.visibility = binding.rvSuggesties.visibility
    }

    override fun onResume() {
        super.onResume()

        // Alleen refreshen wanneer er geen zoekfilter actief is
        if (lastSearchQuery.isEmpty() && this::gridAdapter.isInitialized) {
            // baseAlphaRows en recentRows horen al in memory te staan; we berekenen recents opnieuw
            uiScope.launch {
                // Recente items ophalen en bijwerken
                recentRows = computeRecents(baseAlphaRows)

                // Performance: avoid filtering when no recents, use Set lookup for O(1) instead of O(n)
                val restAlpha = if (recentIds.isEmpty()) {
                    baseAlphaRows
                } else {
                    baseAlphaRows.filterNot { it.soortId in recentIds }
                }

                submitGrid(recents = recentRows, restAlpha = restAlpha)
                updateCounter()
            }
        }
    }

    private fun updateCounter() {
        val totaal = gridAdapter.currentList.count { it is SoortSelectieSectionedAdapter.RowUi.Species }
        val sel = selectedIds.size
        binding.tvTeller.text = getString(R.string.soort_selection_info, totaal, sel)
    }

    companion object {
        /**
         * Normaliseert een string voor zoekdoeleinden
         * - lowercase
         * - diacritical marks verwijderen
         * - spaties normaliseren
         */
        private const val TAG = "SoortSelectieScherm"
        const val EXTRA_TELPOST_ID = "extra_telpost_id"
        const val EXTRA_SELECTED_SOORT_IDS = "extra_selected_soort_ids"

        fun normalizeString(text: String): String {
            return Normalizer.normalize(text, Normalizer.Form.NFD)
                .replace("\\p{InCombiningDiacriticalMarks}+".toRegex(), "")
                .lowercase(Locale.getDefault())
                .trim()
                .replace("\\s+".toRegex(), " ")
        }
    }
}

package com.yvesds.vt5.features.soort.ui

import android.os.Bundle
import android.text.Editable
import android.text.TextWatcher
import android.util.Log
import android.view.View
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.isVisible
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.yvesds.vt5.R
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.core.ui.ProgressDialogHelper
import com.yvesds.vt5.databinding.SchermSoortSelectieBinding
import com.yvesds.vt5.features.alias.AliasManager
import com.yvesds.vt5.features.recent.SpeciesUsageScoreStore
import com.yvesds.vt5.features.serverdata.model.DataSnapshot
import com.yvesds.vt5.features.serverdata.model.ServerDataCache
import com.yvesds.vt5.features.telling.TellingSessionManager
import com.yvesds.vt5.hoofd.InstellingenScherm
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.Normalizer
import java.util.Locale
import java.util.concurrent.ConcurrentHashMap

/**
 * Soort-voorselectie met geoptimaliseerde prestaties:
 * - Efficiënte caching en data-filtering
 * - Verbeterde zoekfunctionaliteit met normalisatie
 * - Geoptimaliseerde UI updates met DiffUtil en payloads
 * - Verminderde GC pressure door object pooling
 * - Sectioned adapter met "recente soorten" bovenaan
 * 
 * UPDATE: Gebruikt nu ALLE unieke soorten uit alias_master.json (via AliasManager)
 * in plaats van site-specifieke filtering. Dit zorgt voor een complete soortenlijst
 * die alle soorten uit site_species.json bevat, ongeacht telpost assignment.
 */
class SoortSelectieScherm : AppCompatActivity() {

    private lateinit var binding: SchermSoortSelectieBinding
    private val uiScope = CoroutineScope(Job() + Dispatchers.Main)

    private var telpostId: String? = null
    private var snapshot: DataSnapshot = DataSnapshot()

    // SAF helper for alias manager access
    private lateinit var saf: SaFStorageHelper

    // Datamodels
    data class Row(val soortId: String, val naam: String) {
        // Performance: Lazy cache voor genormaliseerde naam - alleen berekend bij eerste gebruik
        // Vermijdt onnodige string normalisatie voor items die nooit gezocht worden
        val normalizedName: String by lazy { normalizeString(naam) }
    }

    // Alfabetische basislijst (site-filter toegepast indien beschikbaar)
    private var baseAlphaRows: List<Row> = emptyList()
    // Wereldwijde soortenlijst (alle soorten uit species.json, voor uitgebreide zoekfunctie)
    private var worldSpeciesRows: List<Row> = emptyList()
    // Set van site species IDs voor snelle lookup
    private var siteSpeciesIds: Set<String> = emptySet()
    // Cache voor snelle lookup op ID (inclusief wereldwijde soorten)
    private var rowsByIdCache = ConcurrentHashMap<String, Row>()

    // Recents (subset van baseAlphaRows, meest recent eerst)
    private var recentRows: List<Row> = emptyList()
    private val recentIds: Set<String> get() = recentRows.map { it.soortId }.toSet()

    // Geselecteerde ids
    private val selectedIds = mutableSetOf<String>()

    // Adapters
    private lateinit var gridAdapter: SoortSelectieSectionedAdapter
    private lateinit var suggestAdapter: SoortSelectieAdapter

    // Laatste zoekopdracht voor onResume restore
    private var lastSearchQuery = ""

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = SchermSoortSelectieBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Initialize SAF helper for alias manager access
        saf = SaFStorageHelper(this)

        telpostId = intent.getStringExtra(EXTRA_TELPOST_ID)

        // Begin altijd met een lege selectie: alle checkboxes zijn standaard unchecked.
        // Dit voorkomt dat grote aantallen site-specific soorten automatisch zijn aangevinkt
        // bij het openen van het scherm. De gebruiker kan zelf items aanvinken.
        selectedIds.clear()

        setupAdapters()
        setupListeners()
        loadData()
    }
    private fun setupAdapters() {
        // GRID: sectioned (recents header + items)
        gridAdapter = SoortSelectieSectionedAdapter(
            isSelected = { id -> id in selectedIds },
            onToggleSpecies = { id, checked, position ->
                if (checked) selectedIds += id else selectedIds -= id
                gridAdapter.notifyItemChanged(position, SoortSelectieSectionedAdapter.PAYLOAD_SELECTION)

                // Update suggesties indien zichtbaar
                updateSuggestionsSelection()

                // Header checkbox updaten (alle recents geselecteerd?)
                updateHeaderState()

                updateCounter()
            },
            onToggleAllRecents = { checked ->
                if (checked) {
                    selectedIds.addAll(recentIds)
                } else {
                    selectedIds.removeAll(recentIds)
                }

                // Alleen recents-items refreshen + headerstate bijwerken
                gridAdapter.notifyRecentsSelectionChanged(recentIds)

                // Update suggesties indien zichtbaar
                updateSuggestionsSelection()

                updateCounter()
            }
        )

        // Optimalisatie: SpanSizeLookup voor header over volle breedte
        val spanCount = if (resources.configuration.smallestScreenWidthDp >= 600) 3 else 2
        val glm = GridLayoutManager(this, spanCount, RecyclerView.VERTICAL, false).apply {
            spanSizeLookup = object : GridLayoutManager.SpanSizeLookup() {
                override fun getSpanSize(position: Int): Int {
                    return when {
                        gridAdapter.isHeader(position) -> spanCount // Header over volle breedte
                        gridAdapter.isFooter(position) -> spanCount // Footer over volle breedte
                        else -> 1                           // Items in 2 kolommen
                    }
                }
            }
        }
        // Pool instellen voor view recycling
        binding.rvSoorten.setItemViewCacheSize(30)
        binding.rvSoorten.layoutManager = glm
        binding.rvSoorten.setHasFixedSize(true)
        binding.rvSoorten.adapter = gridAdapter

        // SUGGESTIES: eenvoudige lijst (zelfde rijlayout)
        suggestAdapter = SoortSelectieAdapter(
            isSelected = { id -> id in selectedIds },
            onToggle = { id, checked, position ->
                if (checked) selectedIds += id else selectedIds -= id

                // Update het item in de suggestielijst
                suggestAdapter.notifyItemChanged(position, SoortSelectieAdapter.PAYLOAD_SELECTION)

                // Zoek en update het corresponderende item in de grid
                val idx = gridAdapter.currentList.indexOfFirst {
                    it is SoortSelectieSectionedAdapter.RowUi.Species && it.item.soortId == id
                }
                if (idx >= 0) gridAdapter.notifyItemChanged(idx, SoortSelectieSectionedAdapter.PAYLOAD_SELECTION)

                // Update header status
                updateHeaderState()
                updateCounter()
            }
        )

        binding.rvSuggesties.layoutManager = LinearLayoutManager(this)
        binding.rvSuggesties.setHasFixedSize(true)
        binding.rvSuggesties.adapter = suggestAdapter
        showSuggestions(false)
    }

    private fun setupListeners() {
        binding.btnAnnuleer.setOnClickListener {
            setResult(RESULT_CANCELED)
            finish()
        }

        binding.btnOk.setOnClickListener {
            // Pas bij bevestigen de keuze opslaan in de session manager
            val chosen = ArrayList(selectedIds)
            TellingSessionManager.setPreselectedSoorten(chosen)
            val data = intent.apply { putExtra(EXTRA_SELECTED_SOORT_IDS, chosen) }
            setResult(RESULT_OK, data)
            finish()
        }

        // Debounced zoekfunctie (optimalisatie)
        val searchJob = arrayOfNulls<Job>(1)
        binding.etZoek.addTextChangedListener(object : TextWatcher {
            override fun afterTextChanged(s: Editable?) {
                val query = s?.toString().orEmpty()
                lastSearchQuery = query

                // Cancel lopende zoekopdracht en start een nieuwe na kleine vertraging
                searchJob[0]?.cancel()
                searchJob[0] = uiScope.launch {
                    updateSuggestions(query)
                }
            }
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}
        })
    }

    private fun loadData() {
        uiScope.launch {
            try {
                // Fast-path: check cache first without showing dialog
                val cachedData = ServerDataCache.getCachedOrNull()
                if (cachedData?.hasSpeciesData() == true) {
                    // Cache hit - process immediately without dialog
                    snapshot = cachedData

                    // Process data synchronously (it's fast with cached data)
                    baseAlphaRows = buildAlphaRowsForTelpost()

                    // Build site species ID set for quick lookup
                    siteSpeciesIds = baseAlphaRows.map { it.soortId }.toSet()

                    // Build world species list (alle species.json soorten die NIET in site_species zitten)
                    worldSpeciesRows = buildWorldSpeciesRows()

                    // Build ID cache for O(1) lookups (inclusief wereldwijde soorten)
                    rowsByIdCache.clear()
                    baseAlphaRows.forEach { row -> rowsByIdCache[row.soortId] = row }
                    worldSpeciesRows.forEach { row -> rowsByIdCache[row.soortId] = row }

                    recentRows = computeRecents(baseAlphaRows)
                    submitGrid(recents = recentRows, restAlpha = baseAlphaRows.filterNot { it.soortId in recentIds })
                    updateCounter()

                    return@launch
                }

                // Slow-path: need to load from storage
                val dialog = ProgressDialogHelper.show(this@SoortSelectieScherm, "Soorten laden...")

                try {
                    snapshot = withContext(Dispatchers.IO) {
                        ServerDataCache.getOrLoad(this@SoortSelectieScherm)
                    }

                    // Basislijst opbouwen en sorteren
                    baseAlphaRows = buildAlphaRowsForTelpost()

                    // Build site species ID set for quick lookup
                    siteSpeciesIds = baseAlphaRows.map { it.soortId }.toSet()

                    // Build world species list (alle species.json soorten die NIET in site_species zitten)
                    worldSpeciesRows = buildWorldSpeciesRows()

                    // ID cache opbouwen voor snelle lookup (inclusief wereldwijde soorten)
                    rowsByIdCache.clear()
                    baseAlphaRows.forEach { row -> rowsByIdCache[row.soortId] = row }
                    worldSpeciesRows.forEach { row -> rowsByIdCache[row.soortId] = row }

                    // Recents berekenen
                    recentRows = computeRecents(baseAlphaRows)

                    // Submit naar grid
                    submitGrid(recents = recentRows, restAlpha = baseAlphaRows.filterNot { it.soortId in recentIds })
                    updateCounter()

                    if (baseAlphaRows.isEmpty()) {
                        Toast.makeText(this@SoortSelectieScherm, getString(R.string.soort_no_species_download), Toast.LENGTH_LONG).show()
                    }
                } finally {
                    dialog.dismiss()
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error loading data", e)
                Toast.makeText(this@SoortSelectieScherm, getString(R.string.soort_error_loading, e.message ?: ""), Toast.LENGTH_LONG).show()
            }
        }
    }

    /**
     * Build alphabetically sorted species list.
     * 
     * NEW: Uses ALL unique species from alias_master.json (via AliasManager)
     * instead of filtering by telpost. This provides the complete "truth list"
     * of all species from site_species.json regardless of site assignment.
     * 
     * Performance: Runs synchronously but data is already loaded in memory
     * by AliasManager (loaded during MetadataScherm background preload).
     */
    private suspend fun buildAlphaRowsForTelpost(): List<Row> = withContext(Dispatchers.IO) {
        // Try to get all species from alias index first (preferred source)
        val aliasSpecies = try {
            AliasManager.getAllSpeciesFromIndex(this@SoortSelectieScherm, saf)
        } catch (ex: Exception) {
            Log.w(TAG, "Failed to get species from alias index: ${ex.message}")
            emptyMap()
        }

        // If alias index has species, use that as the source of truth
        val base = if (aliasSpecies.isNotEmpty()) {
            ArrayList<Row>(aliasSpecies.size).apply {
                aliasSpecies.forEach { (sid, naam) ->
                    add(Row(sid, naam))
                }
            }
        } else {
            // Fallback to snapshot.speciesById (all species, no filtering)
            ArrayList<Row>(snapshot.speciesById.size).apply {
                snapshot.speciesById.values.forEach { 
                    add(Row(it.soortid, it.soortnaam)) 
                }
            }
        }

        // Sort by pre-computed lowercase to avoid repeated lowercase() calls
        return@withContext base.sortedBy { it.naam.lowercase() }
    }

    /**
     * Build world species list from species.json (snapshot.speciesById).
     * 
     * Contains ONLY species that are NOT in the site species list (siteSpeciesIds).
     * This allows the search function to extend beyond site-specific species
     * when no match is found in the site species list.
     * 
     * Performance: O(n) filter but cached in memory for fast search.
     */
    private fun buildWorldSpeciesRows(): List<Row> {
        // Filter species.json to exclude those already in site_species, map to Row and sort
        return snapshot.speciesById.values
            .filter { it.soortid !in siteSpeciesIds }
            .map { Row(it.soortid, it.soortnaam) }
            .sortedBy { it.naam.lowercase() }
    }

    /**
     * Check if a row matches the normalized search query.
     */
    private fun matchesQuery(row: Row, normalizedQuery: String): Boolean {
        return row.normalizedName.contains(normalizedQuery) || 
               row.soortId.lowercase().contains(normalizedQuery)
    }

    private fun computeRecents(baseAlpha: List<Row>): List<Row> {
        val prefLimit = InstellingenScherm.getMaxFavorieten(this)
        val recentsOrderedIds = SpeciesUsageScoreStore.getTopSpeciesIds(
            this,
            limit = if (prefLimit == InstellingenScherm.MAX_FAVORIETEN_ALL) 0 else prefLimit
        )

        // Pre-allocate result list with expected size
        val result = ArrayList<Row>(recentsOrderedIds.size.coerceAtMost(baseAlpha.size))

        // Use the cached rowsByIdCache for O(1) lookups if available, otherwise build temporary map
        if (rowsByIdCache.isNotEmpty()) {
            recentsOrderedIds.forEach { id ->
                rowsByIdCache[id]?.let { result.add(it) }
            }
        } else {
            // Fallback: build temporary map (should rarely happen)
            val byId = baseAlpha.associateBy { it.soortId }
            recentsOrderedIds.forEach { id ->
                byId[id]?.let { result.add(it) }
            }
        }

        return result
    }

    private fun submitGrid(recents: List<Row>, restAlpha: List<Row>) {
        // Pre-allocate list with known capacity to avoid resizing
        val estimatedSize = if (recents.isNotEmpty()) {
            recents.size + restAlpha.size + 2 // +2 for header and footer
        } else {
            restAlpha.size
        }
        val items = ArrayList<SoortSelectieSectionedAdapter.RowUi>(estimatedSize)

        if (recents.isNotEmpty()) {
            // Check if all recents are selected (optimized with any { } short-circuit)
            val allSel = !recents.any { !selectedIds.contains(it.soortId) }

            // Header voor recente items
            items.add(SoortSelectieSectionedAdapter.RowUi.RecentsHeader(recentsCount = recents.size, allSelected = allSel))

            // Recente items als speciale visuele groep (direct add to avoid intermediate list)
            recents.forEach { items.add(SoortSelectieSectionedAdapter.RowUi.RecenteSpecies(it)) }

            // Footer divider voor afsluiting van recente groep
            items.add(SoortSelectieSectionedAdapter.RowUi.RecentsFooter)
        }

        // Rest van de items zoals gewoonlijk (direct add to avoid intermediate list)
        restAlpha.forEach { items.add(SoortSelectieSectionedAdapter.RowUi.Species(it)) }

        gridAdapter.submitList(items)
    }
    /**
     * Normaliseert een string voor insensitive zoeken
     * - lowercase
     * - diacritics verwijderen
     * - trim en extra spaces verwijderen
     */
    private fun updateSuggestions(q: String) {
        val text = q.trim()
        if (text.isEmpty()) {
            suggestAdapter.submitList(emptyList())
            showSuggestions(false)
            // rebuild grid (recents + rest) zodat header-state klopt
            // Optimize: avoid creating intermediate filtered list
            val restAlpha = if (recentIds.isEmpty()) {
                baseAlphaRows
            } else {
                baseAlphaRows.filterNot { it.soortId in recentIds }
            }
            submitGrid(recentRows, restAlpha)
            updateCounter()
            return
        }

        // Normaliseren voor case-insensitive en diacritiek-insensitive zoeken
        val normalizedQuery = normalizeString(text)

        val max = 12
        // Pre-allocate result list to avoid resizing
        val filtered = ArrayList<Row>(max)

        // Eerst zoeken in site_species (baseAlphaRows)
        for (row in baseAlphaRows) {
            if (matchesQuery(row, normalizedQuery)) {
                filtered.add(row)
                if (filtered.size >= max) break
            }
        }

        // Als er niet genoeg resultaten zijn, ook zoeken in de wereldlijst (species.json)
        if (filtered.size < max) {
            for (row in worldSpeciesRows) {
                if (matchesQuery(row, normalizedQuery)) {
                    filtered.add(row)
                    if (filtered.size >= max) break
                }
            }
        }

        suggestAdapter.submitList(filtered)
        showSuggestions(filtered.isNotEmpty())
        updateCounter()
    }

    /**
     * Update de selectiestatus in suggesties (indien zichtbaar)
     */
    private fun updateSuggestionsSelection() {
        if (binding.rvSuggesties.isVisible) {
            for (i in 0 until suggestAdapter.itemCount) {
                suggestAdapter.notifyItemChanged(i, SoortSelectieAdapter.PAYLOAD_SELECTION)
            }
        }
    }

    /**
     * Update de header checkbox status op basis van selecties
     */
    private fun updateHeaderState() {
        val idx = gridAdapter.currentList.indexOfFirst { it is SoortSelectieSectionedAdapter.RowUi.RecentsHeader }
        if (idx >= 0) {
            val allRecentsSelected = recentIds.isNotEmpty() && recentIds.all { it in selectedIds }
            val header = (gridAdapter.currentList[idx] as? SoortSelectieSectionedAdapter.RowUi.RecentsHeader)?.copy(allSelected = allRecentsSelected)
                ?: return

            // Update alleen als status veranderd is
            val current = gridAdapter.currentList[idx] as? SoortSelectieSectionedAdapter.RowUi.RecentsHeader
            if (current?.allSelected != header.allSelected) {
                val updatedList = gridAdapter.currentList.toMutableList().apply {
                    set(idx, header)
                }
                gridAdapter.submitList(updatedList)
                gridAdapter.notifyItemChanged(idx, SoortSelectieSectionedAdapter.PAYLOAD_HEADER_STATE)
            }
        }
    }

    private fun showSuggestions(visible: Boolean) {
        binding.rvSuggesties.visibility = if (visible) View.VISIBLE else View.GONE
        binding.dividerTop.visibility = binding.rvSuggesties.visibility
        binding.dividerBottom.visibility = binding.rvSuggesties.visibility
    }

    override fun onResume() {
        super.onResume()

        // Alleen refreshen wanneer er geen zoekfilter actief is
        if (lastSearchQuery.isEmpty() && this::gridAdapter.isInitialized) {
            // baseAlphaRows en recentRows horen al in memory te staan; we berekenen recents opnieuw
            uiScope.launch {
                // Recente items ophalen en bijwerken
                recentRows = computeRecents(baseAlphaRows)

                // Performance: avoid filtering when no recents, use Set lookup for O(1) instead of O(n)
                val restAlpha = if (recentIds.isEmpty()) {
                    baseAlphaRows
                } else {
                    baseAlphaRows.filterNot { it.soortId in recentIds }
                }

                submitGrid(recents = recentRows, restAlpha = restAlpha)
                updateCounter()
            }
        }
    }

    private fun updateCounter() {
        val totaal = gridAdapter.currentList.count { it is SoortSelectieSectionedAdapter.RowUi.Species }
        val sel = selectedIds.size
        binding.tvTeller.text = getString(R.string.soort_selection_info, totaal, sel)
    }

    companion object {
        /**
         * Normaliseert een string voor zoekdoeleinden
         * - lowercase
         * - diacritical marks verwijderen
         * - spaties normaliseren
         */
        private const val TAG = "SoortSelectieScherm"
        const val EXTRA_TELPOST_ID = "extra_telpost_id"
        const val EXTRA_SELECTED_SOORT_IDS = "extra_selected_soort_ids"

        fun normalizeString(text: String): String {
            return Normalizer.normalize(text, Normalizer.Form.NFD)
                .replace("\\p{InCombiningDiacriticalMarks}+".toRegex(), "")
                .lowercase(Locale.getDefault())
                .trim()
                .replace("\\s+".toRegex(), " ")
        }
    }
}

package com.yvesds.vt5.features.telling

import android.content.Context
import android.util.Log
import androidx.core.content.edit
import androidx.documentfile.provider.DocumentFile
import com.yvesds.vt5.VT5App
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.repository.HybridTellingRepository
import com.yvesds.vt5.core.database.toServerEnvelope
import com.yvesds.vt5.core.database.toServerItem
import com.yvesds.vt5.net.ServerTellingDataItem
import com.yvesds.vt5.net.ServerTellingEnvelope
import com.yvesds.vt5.utils.SessionRemarksMarker
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.json.Json
import java.util.Date

/**
 * TellingAfrondHandler: Handles the complete "Afronden" (finalize) flow for TellingScherm.
 * 
 * Responsibilities:
 * - Building the final envelope with counts from Room (Hybrid System)
 * - Uploading to server
 * - Handling server response
 * - Cleanup of temporary files and preferences
 * - Cleanup of active_telling.json (historical)
 * - Error handling and user feedback
 */
class TellingAfrondHandler(
    private val context: Context,
    private val backupManager: TellingBackupManager,
    private val dataProcessor: TellingDataProcessor,
    private val envelopePersistence: TellingEnvelopePersistence? = null
) {
    private val database by lazy { VoiceTallyDatabase.getDatabase(context) }
    private val hybridRepository by lazy { HybridTellingRepository(context) }

    companion object {
        private const val TAG = "TellingAfrondHandler"
        private const val PREFS_NAME = "vt5_prefs"
        private const val PREF_SAVED_ENVELOPE_JSON = "pref_saved_envelope_json"
        private const val PREF_ONLINE_ID = "pref_online_id"
        private const val PREF_TELLING_ID = "pref_telling_id"

        private val PRETTY_JSON: Json by lazy { Json { prettyPrint = true; encodeDefaults = true } }
    }

    /**
     * Result of handleAfronden operation.
     */
    sealed class AfrondResult {
        data class Success(
            val savedPrettyPath: String?,
            val auditPath: String?
        ) : AfrondResult()

        data class Failure(
            val title: String,
            val message: String,
            val savedPrettyPath: String? = null,
            val auditPath: String? = null
        ) : AfrondResult()
    }

    /**
     * Handle the complete Afronden (finalize and upload) flow.
     * Uses Room as the primary source of truth for records and metadata.
     * 
     * @param pendingRecordsSnapshot Snaphot of records from memory (as backup/sync source)
     * @param pendingBackupDocs List of backup document files to clean up on success
     * @param pendingBackupInternalPaths List of internal backup paths to clean up on success
     * @param metadataUpdates Optional metadata updates (begintijd, eindtijd, opmerkingen)
     */
    suspend fun handleAfronden(
        pendingRecordsSnapshot: List<ServerTellingDataItem>,
        pendingBackupDocs: List<DocumentFile>,
        pendingBackupInternalPaths: List<String>,
        metadataUpdates: MetadataUpdates? = null
    ): AfrondResult = withContext(Dispatchers.IO) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val tellingId = prefs.getString(PREF_TELLING_ID, null)

        // 1. Fetch metadata and records from Room (Hybride Systeem source of truth)
        val header = if (!tellingId.isNullOrBlank()) {
            database.tellingDao().getHeader(tellingId)
        } else null

        val roomRecords = if (!tellingId.isNullOrBlank()) {
            database.tellingDao().getWaarnemingenList(tellingId)
        } else emptyList()

        val baseEnv = if (header != null) {
            // Build envelope from database state
            header.toServerEnvelope(roomRecords)
        } else {
            // LEGACY FALLBACK: Use saved JSON if Room header is missing
            val savedEnvelopeJson = prefs.getString(PREF_SAVED_ENVELOPE_JSON, null)
            if (savedEnvelopeJson.isNullOrBlank()) {
                return@withContext AfrondResult.Failure(
                    title = "Geen metadata",
                    message = "Er is geen opgeslagen metadata gevonden in Room of JSON. Keer terug naar metadata en start een telling."
                )
            }

            val envelopeList = try {
                VT5App.json.decodeFromString(
                    ListSerializer(ServerTellingEnvelope.serializer()), 
                    savedEnvelopeJson
                )
            } catch (e: Exception) {
                Log.w(TAG, "Failed decoding saved envelope JSON fallback: ${e.message}", e)
                null
            }

            if (envelopeList.isNullOrEmpty()) {
                return@withContext AfrondResult.Failure(
                    title = "Ongeldige metadata",
                    message = "Metadata in database ontbreekt en JSON fallback is ongeldig."
                )
            }
            envelopeList[0]
        }

        val savedOnlineId = prefs.getString(PREF_ONLINE_ID, baseEnv.onlineid)

        // 2. Build final envelope with times and records
        val nowEpoch = (System.currentTimeMillis() / 1000L)
        val nowEpochStr = nowEpoch.toString()

        // Apply metadata updates if provided
        val effectiveBegintijd = metadataUpdates?.begintijd?.ifBlank { null } ?: baseEnv.begintijd
        val effectiveEindtijd = metadataUpdates?.eindtijd?.ifBlank { null } ?: nowEpochStr
        val effectiveOpmerkingen = SessionRemarksMarker.remove(metadataUpdates?.opmerkingen ?: baseEnv.opmerkingen)

        // Combine current Room records (primary) with base metadata
        val finalRecords = if (roomRecords.isNotEmpty()) {
            roomRecords.map { it.toServerItem() }
        } else {
            // Fallback to memory snapshot if Room is somehow empty but memory has data
            pendingRecordsSnapshot
        }

        val nrec = finalRecords.size
        val nsoort = finalRecords.map { it.soortid }.filter { it.isNotBlank() }.toSet().size

        val finalEnvDraft = baseEnv.copy(
            begintijd = effectiveBegintijd,
            eindtijd = effectiveEindtijd,
            opmerkingen = effectiveOpmerkingen,
            nrec = nrec.toString(),
            nsoort = nsoort.toString(), 
            data = finalRecords
        )

        val uploadCore = TellingUploadCore(context)
        val finalEnv = uploadCore.prepareEnvelopeForUpload(
            sourceEnvelope = finalEnvDraft,
            useStoredOnlineIdWhenBlank = false,
            now = Date()
        )
        val envelopeToSend = listOf(finalEnv)

        // 3. Pretty print and save envelope (historical JSON archive)
        val prettyJson = try {
            PRETTY_JSON.encodeToString(
                ListSerializer(ServerTellingEnvelope.serializer()), 
                envelopeToSend
            )
        } catch (e: Exception) {
            Log.w(TAG, "pretty encode failed: ${e.message}", e)
            null
        }

        val onlineIdForFilename = finalEnv.onlineid.ifBlank { 
            savedOnlineId?.ifBlank { "unknown" } ?: "unknown" 
        }
        var savedPrettyPath: String? = null
        if (prettyJson != null) {
            savedPrettyPath = backupManager.writePrettyEnvelopeToSaf(
                onlineIdForFilename, 
                prettyJson
            ) ?: backupManager.writePrettyEnvelopeInternal(
                onlineIdForFilename, 
                prettyJson
            )
        }

        // 4. Upload to server via centrale uploadkern
        val uploadResult = uploadCore.uploadPrepared(
            TellingUploadCore.UploadRequest(
                mode = TellingUploadCore.Mode.FINALIZE,
                preparedEnvelope = finalEnv,
                persistReturnedOnlineId = true,
                persistPreparedEnvelopeToPrefs = true,
                markTellingSent = true
            )
        )
        val resp = uploadResult.responseText

        // 5. Write audit file
        val auditPath = try {
            backupManager.writeEnvelopeResponseToSaf(
                finalEnv.tellingid, 
                prettyJson ?: "{}", 
                resp
            ) ?: backupManager.writeEnvelopeResponseInternal(
                finalEnv.tellingid, 
                prettyJson ?: "{}", 
                resp
            )
        } catch (e: Exception) {
            Log.w(TAG, "Failed to write audit: ${e.message}", e)
            null
        }

        // 6. Handle result
        if (!uploadResult.success) {
            return@withContext AfrondResult.Failure(
                title = "Upload mislukt",
                message = "Kon telling niet uploaden:\n${uploadResult.errorMessage ?: resp}\n\n" +
                         "Envelope opgeslagen: ${savedPrettyPath ?: "niet beschikbaar"}\n" +
                         "Auditbestand: ${auditPath ?: "niet beschikbaar"}",
                savedPrettyPath = savedPrettyPath,
                auditPath = auditPath
            )
        }
        val effectiveOnlineId = uploadResult.effectiveOnlineId ?: savedOnlineId ?: finalEnv.onlineid

        // 7. Cleanup: remove backups and clear preferences
        try {
            pendingBackupDocs.forEach { doc -> 
                try { doc.delete() } catch (_: Exception) {} 
            }

            pendingBackupInternalPaths.forEach { path -> 
                try { java.io.File(path).delete() } catch (_: Exception) {} 
            }

            // Remove telling-related preferences
            prefs.edit {
                remove(PREF_ONLINE_ID)
                remove(PREF_TELLING_ID)
                remove(PREF_SAVED_ENVELOPE_JSON)
            }

            // Hybride System final actions:
            try {
                val currentTellingId = finalEnv.tellingid
                val archiveOnlineId = effectiveOnlineId.ifBlank { finalEnv.onlineid }

                // Room shadow update: Update the header with final times and counts
                hybridRepository.saveHeaderToRoom(uploadResult.preparedEnvelope, status = "geupload")

                // Extra check: Zorg dat álle records ook in Room staan (Fase 4 consistentie)
                finalRecords.forEach { record ->
                    hybridRepository.saveWaarnemingToRoom(record)
                }

                // Archive the JSON to counts folder (historical reference)
                if (prettyJson != null) {
                    envelopePersistence?.saveFinalEnvelopeToCountsDir(currentTellingId, archiveOnlineId, prettyJson)
                }

            } catch (ex: Exception) {
                Log.w(TAG, "Hybride cleanup actions failed: ${ex.message}", ex)
            }
        } catch (e: Exception) {
            Log.w(TAG, "Cleanup after successful Afronden failed: ${e.message}", e)
        }

        return@withContext AfrondResult.Success(
            savedPrettyPath = savedPrettyPath,
            auditPath = auditPath
        )
    }



    /**
     * Build envelope summary for display.
     */
    fun buildEnvelopeSummary(envelope: ServerTellingEnvelope): String {
        return dataProcessor.buildEnvelopeSummary(envelope)
    }
}

package com.yvesds.vt5.features.telling

import android.content.Context
import android.util.Log
import androidx.core.content.edit
import androidx.documentfile.provider.DocumentFile
import com.yvesds.vt5.VT5App
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.database.repository.HybridTellingRepository
import com.yvesds.vt5.core.database.toServerEnvelope
import com.yvesds.vt5.core.database.toServerItem
import com.yvesds.vt5.net.ServerTellingDataItem
import com.yvesds.vt5.net.ServerTellingEnvelope
import com.yvesds.vt5.utils.SessionRemarksMarker
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.json.Json
import java.util.Date

/**
 * TellingAfrondHandler: Handles the complete "Afronden" (finalize) flow for TellingScherm.
 * 
 * Responsibilities:
 * - Building the final envelope with counts from Room (Hybrid System)
 * - Uploading to server
 * - Handling server response
 * - Cleanup of temporary files and preferences
 * - Cleanup of active_telling.json (historical)
 * - Error handling and user feedback
 */
class TellingAfrondHandler(
    private val context: Context,
    private val backupManager: TellingBackupManager,
    private val dataProcessor: TellingDataProcessor,
    private val envelopePersistence: TellingEnvelopePersistence? = null
) {
    private val database by lazy { VoiceTallyDatabase.getDatabase(context) }
    private val hybridRepository by lazy { HybridTellingRepository(context) }

    companion object {
        private const val TAG = "TellingAfrondHandler"
        private const val PREFS_NAME = "vt5_prefs"
        private const val PREF_SAVED_ENVELOPE_JSON = "pref_saved_envelope_json"
        private const val PREF_ONLINE_ID = "pref_online_id"
        private const val PREF_TELLING_ID = "pref_telling_id"

        private val PRETTY_JSON: Json by lazy { Json { prettyPrint = true; encodeDefaults = true } }
    }

    /**
     * Result of handleAfronden operation.
     */
    sealed class AfrondResult {
        data class Success(
            val savedPrettyPath: String?,
            val auditPath: String?
        ) : AfrondResult()

        data class Failure(
            val title: String,
            val message: String,
            val savedPrettyPath: String? = null,
            val auditPath: String? = null
        ) : AfrondResult()
    }

    /**
     * Handle the complete Afronden (finalize and upload) flow.
     * Uses Room as the primary source of truth for records and metadata.
     * 
     * @param pendingRecordsSnapshot Snaphot of records from memory (as backup/sync source)
     * @param pendingBackupDocs List of backup document files to clean up on success
     * @param pendingBackupInternalPaths List of internal backup paths to clean up on success
     * @param metadataUpdates Optional metadata updates (begintijd, eindtijd, opmerkingen)
     */
    suspend fun handleAfronden(
        pendingRecordsSnapshot: List<ServerTellingDataItem>,
        pendingBackupDocs: List<DocumentFile>,
        pendingBackupInternalPaths: List<String>,
        metadataUpdates: MetadataUpdates? = null
    ): AfrondResult = withContext(Dispatchers.IO) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val tellingId = prefs.getString(PREF_TELLING_ID, null)

        // 1. Fetch metadata and records from Room (Hybride Systeem source of truth)
        val header = if (!tellingId.isNullOrBlank()) {
            database.tellingDao().getHeader(tellingId)
        } else null

        val roomRecords = if (!tellingId.isNullOrBlank()) {
            database.tellingDao().getWaarnemingenList(tellingId)
        } else emptyList()

        val baseEnv = if (header != null) {
            // Build envelope from database state
            header.toServerEnvelope(roomRecords)
        } else {
            // LEGACY FALLBACK: Use saved JSON if Room header is missing
            val savedEnvelopeJson = prefs.getString(PREF_SAVED_ENVELOPE_JSON, null)
            if (savedEnvelopeJson.isNullOrBlank()) {
                return@withContext AfrondResult.Failure(
                    title = "Geen metadata",
                    message = "Er is geen opgeslagen metadata gevonden in Room of JSON. Keer terug naar metadata en start een telling."
                )
            }

            val envelopeList = try {
                VT5App.json.decodeFromString(
                    ListSerializer(ServerTellingEnvelope.serializer()), 
                    savedEnvelopeJson
                )
            } catch (e: Exception) {
                Log.w(TAG, "Failed decoding saved envelope JSON fallback: ${e.message}", e)
                null
            }

            if (envelopeList.isNullOrEmpty()) {
                return@withContext AfrondResult.Failure(
                    title = "Ongeldige metadata",
                    message = "Metadata in database ontbreekt en JSON fallback is ongeldig."
                )
            }
            envelopeList[0]
        }

        val savedOnlineId = prefs.getString(PREF_ONLINE_ID, baseEnv.onlineid)

        // 2. Build final envelope with times and records
        val nowEpoch = (System.currentTimeMillis() / 1000L)
        val nowEpochStr = nowEpoch.toString()

        // Apply metadata updates if provided
        val effectiveBegintijd = metadataUpdates?.begintijd?.ifBlank { null } ?: baseEnv.begintijd
        val effectiveEindtijd = metadataUpdates?.eindtijd?.ifBlank { null } ?: nowEpochStr
        val effectiveOpmerkingen = SessionRemarksMarker.remove(metadataUpdates?.opmerkingen ?: baseEnv.opmerkingen)

        // Combine current Room records (primary) with base metadata
        val finalRecords = if (roomRecords.isNotEmpty()) {
            roomRecords.map { it.toServerItem() }
        } else {
            // Fallback to memory snapshot if Room is somehow empty but memory has data
            pendingRecordsSnapshot
        }

        val nrec = finalRecords.size
        val nsoort = finalRecords.map { it.soortid }.filter { it.isNotBlank() }.toSet().size

        val finalEnvDraft = baseEnv.copy(
            begintijd = effectiveBegintijd,
            eindtijd = effectiveEindtijd,
            opmerkingen = effectiveOpmerkingen,
            onlineid = "",
            nrec = nrec.toString(),
            nsoort = nsoort.toString(), 
            data = finalRecords
        )

        val uploadCore = TellingUploadCore(context)
        val finalEnv = uploadCore.prepareEnvelopeForUpload(
            sourceEnvelope = finalEnvDraft,
            useStoredOnlineIdWhenBlank = false,
            now = Date()
        )
        val envelopeToSend = listOf(finalEnv)

        // 3. Pretty print and save envelope (historical JSON archive)
        val prettyJson = try {
            PRETTY_JSON.encodeToString(
                ListSerializer(ServerTellingEnvelope.serializer()), 
                envelopeToSend
            )
        } catch (e: Exception) {
            Log.w(TAG, "pretty encode failed: ${e.message}", e)
            null
        }

        val onlineIdForFilename = finalEnv.onlineid.ifBlank { 
            savedOnlineId?.ifBlank { "unknown" } ?: "unknown" 
        }
        var savedPrettyPath: String? = null
        if (prettyJson != null) {
            savedPrettyPath = backupManager.writePrettyEnvelopeToSaf(
                onlineIdForFilename, 
                prettyJson
            ) ?: backupManager.writePrettyEnvelopeInternal(
                onlineIdForFilename, 
                prettyJson
            )
        }

        // 4. Upload to server via centrale uploadkern
        val uploadResult = uploadCore.uploadPrepared(
            TellingUploadCore.UploadRequest(
                mode = TellingUploadCore.Mode.FINALIZE,
                preparedEnvelope = finalEnv,
                persistReturnedOnlineId = true,
                persistPreparedEnvelopeToPrefs = true,
                markTellingSent = true
            )
        )
        val resp = uploadResult.responseText

        // 5. Write audit file
        val auditPath = try {
            backupManager.writeEnvelopeResponseToSaf(
                finalEnv.tellingid, 
                prettyJson ?: "{}", 
                resp
            ) ?: backupManager.writeEnvelopeResponseInternal(
                finalEnv.tellingid, 
                prettyJson ?: "{}", 
                resp
            )
        } catch (e: Exception) {
            Log.w(TAG, "Failed to write audit: ${e.message}", e)
            null
        }

        // 6. Handle result
        if (!uploadResult.success) {
            return@withContext AfrondResult.Failure(
                title = "Upload mislukt",
                message = "Kon telling niet uploaden:\n${uploadResult.errorMessage ?: resp}\n\n" +
                         "Envelope opgeslagen: ${savedPrettyPath ?: "niet beschikbaar"}\n" +
                         "Auditbestand: ${auditPath ?: "niet beschikbaar"}",
                savedPrettyPath = savedPrettyPath,
                auditPath = auditPath
            )
        }
        val effectiveOnlineId = uploadResult.effectiveOnlineId ?: savedOnlineId ?: finalEnv.onlineid

        // 7. Cleanup: remove backups and clear preferences
        try {
            pendingBackupDocs.forEach { doc -> 
                try { doc.delete() } catch (_: Exception) {} 
            }

            pendingBackupInternalPaths.forEach { path -> 
                try { java.io.File(path).delete() } catch (_: Exception) {} 
            }

            // Remove telling-related preferences
            prefs.edit {
                remove(PREF_ONLINE_ID)
                remove(PREF_TELLING_ID)
                remove(PREF_SAVED_ENVELOPE_JSON)
            }

            // Hybride System final actions:
            try {
                val currentTellingId = finalEnv.tellingid
                val archiveOnlineId = effectiveOnlineId.ifBlank { finalEnv.onlineid }

                // Room shadow update: Update the header with final times and counts
                hybridRepository.saveHeaderToRoom(uploadResult.preparedEnvelope, status = "geupload")

                // Extra check: Zorg dat álle records ook in Room staan (Fase 4 consistentie)
                finalRecords.forEach { record ->
                    hybridRepository.saveWaarnemingToRoom(record)
                }

                // Archive the JSON to counts folder (historical reference)
                if (prettyJson != null) {
                    envelopePersistence?.saveFinalEnvelopeToCountsDir(currentTellingId, archiveOnlineId, prettyJson)
                }

            } catch (ex: Exception) {
                Log.w(TAG, "Hybride cleanup actions failed: ${ex.message}", ex)
            }
        } catch (e: Exception) {
            Log.w(TAG, "Cleanup after successful Afronden failed: ${e.message}", e)
        }

        return@withContext AfrondResult.Success(
            savedPrettyPath = savedPrettyPath,
            auditPath = auditPath
        )
    }



    /**
     * Build envelope summary for display.
     */
    fun buildEnvelopeSummary(envelope: ServerTellingEnvelope): String {
        return dataProcessor.buildEnvelopeSummary(envelope)
    }
}

package com.yvesds.vt5.features.telling

import android.content.Context
import android.util.Log
import androidx.documentfile.provider.DocumentFile
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.net.ServerTellingDataItem
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * TellingBackupManager: Handles backup operations for counting records.
 * 
 * Responsibilities:
 * - Writing record backups to SAF (Storage Access Framework)
 * - Writing record backups to internal storage (fallback)
 * - Writing envelope JSON files
 * - Writing audit/response files
 */
class TellingBackupManager(
    private val context: Context,
    private val safHelper: SaFStorageHelper
) {
    companion object {
        private const val TAG = "TellingBackupManager"
        private const val VT5_DIR = "VT5"
        private const val EXPORTS_DIR = "exports"
    }

    /**
     * Write a single record backup via SAF into Documents/VT5/exports.
     * Returns the created DocumentFile or null if failed.
     */
    fun writeRecordBackupSaf(tellingId: String, item: ServerTellingDataItem): DocumentFile? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss_SSS", Locale.US).format(Date())
            val filename = "${nowStr}_rec_${item.idLocal}.txt"

            val doc = exportsDir.createFile("text/plain", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create record backup file via SAF: $filename")
                return null
            }

            val content = buildRecordBackupContent(tellingId, item)
            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(content.toByteArray(Charsets.UTF_8))
            }

            return doc
        } catch (e: Exception) {
            Log.w(TAG, "writeRecordBackupSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write a single record backup to internal storage as fallback.
     * Returns the absolute path or null if failed.
     */
    fun writeRecordBackupInternal(tellingId: String, item: ServerTellingDataItem): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss_SSS", Locale.US).format(Date())
            val filename = "${nowStr}_rec_${item.idLocal}.txt"
            val file = File(root, filename)

            val content = buildRecordBackupContent(tellingId, item)
            file.writeText(content, Charsets.UTF_8)

            return file.absolutePath
        } catch (e: Exception) {
            Log.w(TAG, "writeRecordBackupInternal failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write pretty envelope JSON to SAF as "<timestamp>_count_<onlineid>.json".
     * Returns "saf:<uri>" or null if failed.
     */
    fun writePrettyEnvelopeToSaf(onlineId: String, prettyJson: String): String? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_count_$onlineId.json"

            val doc = exportsDir.createFile("application/json", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create envelope file via SAF: $filename")
                return null
            }

            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(prettyJson.toByteArray(Charsets.UTF_8))
            }

            return "saf:${doc.uri}"
        } catch (e: Exception) {
            Log.w(TAG, "writePrettyEnvelopeToSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write pretty envelope JSON to internal storage as fallback.
     * Returns "internal:<path>" or null if failed.
     */
    fun writePrettyEnvelopeInternal(onlineId: String, prettyJson: String): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_count_$onlineId.json"
            val file = File(root, filename)

            file.writeText(prettyJson, Charsets.UTF_8)

            return "internal:${file.absolutePath}"
        } catch (e: Exception) {
            Log.w(TAG, "writePrettyEnvelopeInternal failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write envelope response (audit) to SAF.
     * Returns path string or null if failed.
     */
    fun writeEnvelopeResponseToSaf(
        tellingId: String,
        envelopeJson: String,
        responseText: String
    ): String? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_audit_${tellingId}.txt"

            val doc = exportsDir.createFile("text/plain", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create audit file via SAF: $filename")
                return null
            }

            val content = buildAuditContent(envelopeJson, responseText)
            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(content.toByteArray(Charsets.UTF_8))
            }

            return "saf:${doc.uri}"
        } catch (e: Exception) {
            Log.w(TAG, "writeEnvelopeResponseToSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write envelope response (audit) to internal storage as fallback.
     * Returns path string or null if failed.
     */
    fun writeEnvelopeResponseInternal(
        tellingId: String,
        envelopeJson: String,
        responseText: String
    ): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_audit_${tellingId}.txt"
            val file = File(root, filename)

            val content = buildAuditContent(envelopeJson, responseText)
            file.writeText(content, Charsets.UTF_8)

            return "internal:${file.absolutePath}"
        } catch (e: Exception) {
            Log.w(TAG, "writeEnvelopeResponseInternal failed: ${e.message}", e)
            return null
        }
    }

    // Private helpers

    private fun buildRecordBackupContent(tellingId: String, item: ServerTellingDataItem): String {
        return """
            |Record Backup
            |TellingId: $tellingId
            |IdLocal: ${item.idLocal}
            |SoortId: ${item.soortid}
            |Aantal: ${item.aantal}
            |Timestamp: ${item.tijdstip}
            |GroupId: ${item.groupid}
            |---
            |Full Item: $item
        """.trimMargin()
    }

    private fun buildAuditContent(envelopeJson: String, responseText: String): String {
        return """
            |=== Envelope JSON ===
            |$envelopeJson
            |
            |=== Server Response ===
            |$responseText
        """.trimMargin()
    }
}

package com.yvesds.vt5.features.telling

import android.content.Context
import android.util.Log
import androidx.documentfile.provider.DocumentFile
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.features.serverdata.model.ServerDataCache
import com.yvesds.vt5.net.ServerTellingDataItem
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * TellingBackupManager: Handles backup operations for counting records.
 * 
 * Responsibilities:
 * - Writing record backups to SAF (Storage Access Framework)
 * - Writing record backups to internal storage (fallback)
 * - Writing envelope JSON files
 * - Writing audit/response files
 */
class TellingBackupManager(
    private val context: Context,
    private val safHelper: SaFStorageHelper
) {
    companion object {
        private const val TAG = "TellingBackupManager"
        private const val VT5_DIR = "VT5"
        private const val EXPORTS_DIR = "exports"
    }

    /**
     * Write a single record backup via SAF into Documents/VT5/exports.
     * Returns the created DocumentFile or null if failed.
     */
    fun writeRecordBackupSaf(tellingId: String, item: ServerTellingDataItem): DocumentFile? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss_SSS", Locale.US).format(Date())
            val filename = "${nowStr}_rec_${item.idLocal}.txt"
            
            val doc = exportsDir.createFile("text/plain", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create record backup file via SAF: $filename")
                return null
            }

            val content = buildRecordBackupContent(tellingId, item)
            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(content.toByteArray(Charsets.UTF_8))
            }

            return doc
        } catch (e: Exception) {
            Log.w(TAG, "writeRecordBackupSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write a single record backup to internal storage as fallback.
     * Returns the absolute path or null if failed.
     */
    fun writeRecordBackupInternal(tellingId: String, item: ServerTellingDataItem): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss_SSS", Locale.US).format(Date())
            val filename = "${nowStr}_rec_${item.idLocal}.txt"
            val file = File(root, filename)

            val content = buildRecordBackupContent(tellingId, item)
            file.writeText(content, Charsets.UTF_8)

            return file.absolutePath
        } catch (e: Exception) {
            Log.w(TAG, "writeRecordBackupInternal failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write pretty envelope JSON to SAF as "<timestamp>_count_<onlineid>.json".
     * Returns "saf:<uri>" or null if failed.
     */
    fun writePrettyEnvelopeToSaf(onlineId: String, prettyJson: String): String? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_count_$onlineId.json"
            
            val doc = exportsDir.createFile("application/json", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create envelope file via SAF: $filename")
                return null
            }

            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(prettyJson.toByteArray(Charsets.UTF_8))
            }

            return "saf:${doc.uri}"
        } catch (e: Exception) {
            Log.w(TAG, "writePrettyEnvelopeToSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write pretty envelope JSON to internal storage as fallback.
     * Returns "internal:<path>" or null if failed.
     */
    fun writePrettyEnvelopeInternal(onlineId: String, prettyJson: String): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_count_$onlineId.json"
            val file = File(root, filename)

            file.writeText(prettyJson, Charsets.UTF_8)

            return "internal:${file.absolutePath}"
        } catch (e: Exception) {
            Log.w(TAG, "writePrettyEnvelopeInternal failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write envelope response (audit) to SAF.
     * Returns path string or null if failed.
     */
    fun writeEnvelopeResponseToSaf(
        tellingId: String,
        envelopeJson: String,
        responseText: String
    ): String? {
        try {
            var vt5Dir: DocumentFile? = safHelper.getVt5DirIfExists()
            if (vt5Dir == null) {
                try { safHelper.ensureFolders() } catch (_: Exception) {}
                vt5Dir = safHelper.getVt5DirIfExists()
            }
            if (vt5Dir == null) {
                Log.w(TAG, "VT5 root folder not available via SAF")
                return null
            }

            var exportsDir = vt5Dir.findFile(EXPORTS_DIR)
            if (exportsDir == null || !exportsDir.isDirectory) {
                exportsDir = vt5Dir.createDirectory(EXPORTS_DIR)
            }
            if (exportsDir == null) {
                Log.w(TAG, "Could not create/find exports dir in SAF")
                return null
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_audit_${tellingId}.txt"
            
            val doc = exportsDir.createFile("text/plain", filename)
            if (doc == null) {
                Log.w(TAG, "Could not create audit file via SAF: $filename")
                return null
            }

            val content = buildAuditContent(envelopeJson, responseText)
            context.contentResolver.openOutputStream(doc.uri)?.use { out ->
                out.write(content.toByteArray(Charsets.UTF_8))
            }

            return "saf:${doc.uri}"
        } catch (e: Exception) {
            Log.w(TAG, "writeEnvelopeResponseToSaf failed: ${e.message}", e)
            return null
        }
    }

    /**
     * Write envelope response (audit) to internal storage as fallback.
     * Returns path string or null if failed.
     */
    fun writeEnvelopeResponseInternal(
        tellingId: String,
        envelopeJson: String,
        responseText: String
    ): String? {
        try {
            val root = File(context.filesDir, "$VT5_DIR/$EXPORTS_DIR")
            if (!root.exists()) {
                root.mkdirs()
            }

            val nowStr = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val filename = "${nowStr}_audit_${tellingId}.txt"
            val file = File(root, filename)

            val content = buildAuditContent(envelopeJson, responseText)
            file.writeText(content, Charsets.UTF_8)

            return "internal:${file.absolutePath}"
        } catch (e: Exception) {
            Log.w(TAG, "writeEnvelopeResponseInternal failed: ${e.message}", e)
            return null
        }
    }

    // Private helpers

    private fun buildRecordBackupContent(tellingId: String, item: ServerTellingDataItem): String {
        val prefs = context.getSharedPreferences("vt5_prefs", Context.MODE_PRIVATE)
        val storedTellingId = prefs.getString("pref_telling_id", "").orEmpty().trim()
        val onlineId = if (storedTellingId == tellingId.trim()) {
            prefs.getString("pref_online_id", "").orEmpty().trim()
        } else {
            ""
        }.ifBlank { "-" }

        val speciesName = runCatching {
            ServerDataCache.getCachedOrNull()?.speciesById?.get(item.soortid)?.soortnaam
        }.getOrNull().orEmpty().ifBlank { item.soortid }

        val epoch = item.tijdstip.toLongOrNull() ?: 0L
        val timestampDate = when {
            epoch > 9_999_999_999L -> Date(epoch)
            epoch > 0L -> Date(epoch * 1000L)
            else -> null
        }
        val readableTime = timestampDate?.let {
            SimpleDateFormat("MM/dd/yyyy HH:mm:ss", Locale.US).format(it)
        } ?: "-"

        return """
            |Record Backup
            |TellingId: $tellingId
            |Onlineid: $onlineId
            |IdLocal: ${item.idLocal}
            |SoortId: ${item.soortid}
            |Soortnaam: $speciesName
            |Aantal: ${item.aantal}
            |Aantal terug: ${item.aantalterug}
            |Timestamp: ${item.tijdstip}
            |Tijd: $readableTime
            |GroupId: ${item.groupid}
            |---
            |Full Item: $item
        """.trimMargin()
    }

    private fun buildAuditContent(envelopeJson: String, responseText: String): String {
        return """
            |=== Envelope JSON ===
            |$envelopeJson
            |
            |=== Server Response ===
            |$responseText
        """.trimMargin()
    }
}

