// Paged variant to avoid loading huge resultsets in a single query @Query(""" SELECT waarnemingen.* FROM waarnemingen JOIN telling_headers ON waarnemingen.tellingid = telling_headers.tellingid WHERE waarnemingen.soortid = :soortId AND (:year IS NULL OR strftime('%Y', datetime( CASE WHEN CAST(telling_headers.begintijd AS INTEGER) > 9999999999 THEN CAST(telling_headers.begintijd AS INTEGER)/1000 ELSE CAST(telling_headers.begintijd AS INTEGER) END , 'unixepoch')) = :year) ORDER BY waarnemingen.tijdstip DESC LIMIT :limit OFFSET :offset """) suspend fun getWaarnemingenBySoortAndYearPaged(soortId: String, year: String?, limit: Int, offset: Int): List<Waarneming>
@Query(""" SELECT COUNT(*) FROM waarnemingen JOIN telling_headers ON waarnemingen.tellingid = telling_headers.tellingid WHERE waarnemingen.soortid = :soortId AND (:year IS NULL OR strftime('%Y', datetime( CASE WHEN CAST(telling_headers.begintijd AS INTEGER) > 9999999999 THEN CAST(telling_headers.begintijd AS INTEGER)/1000 ELSE CAST(telling_headers.begintijd AS INTEGER) END , 'unixepoch')) = :year) """) suspend fun countWaarnemingenBySoortAndYear(soortId: String, year: String?): Int
@Query("SELECT * FROM waarnemingen WHERE idLocal = :idLocal AND tellingid = :tellingId") suspend fun getWaarnemingById(idLocal: String, tellingId: String): Waarneming?
@Query("DELETE FROM telling_headers") suspend fun clearAllHeaders()
@Query("DELETE FROM waarnemingen") suspend fun clearAllWaarnemingen()
@Query("DELETE FROM sync_logs") suspend fun clearAllSyncLogs()
@Query("SELECT COUNT(*) FROM telling_headers") suspend fun countHeaders(): Int
@Query("SELECT tellingid FROM telling_headers") suspend fun getAllHeaderIds(): List<String>
@Query("SELECT COUNT(*) FROM waarnemingen") suspend fun countWaarnemingen(): Int
// Lookup helpers by server online id @Query("SELECT tellingid FROM telling_headers WHERE onlineid = :onlineid LIMIT 1") suspend fun getLocalTellingIdForOnlineId(onlineid: String): String?
@Query("SELECT * FROM telling_headers WHERE onlineid = :onlineid LIMIT 1") suspend fun getHeaderByOnlineId(onlineid: String): TellingHeader?
@Query("SELECT * FROM waarnemingen WHERE onlineid = :onlineid") suspend fun getWaarnemingenByOnlineId(onlineid: String): List<Waarneming>
@Query("SELECT COUNT(*) FROM sync_logs") suspend fun countSyncLogs(): Int
@Query(""" SELECT telling_headers.begintijd AS begintijd, telling_headers.timezoneid AS timezoneid, telling_headers.windrichting AS windrichting, telling_headers.windkracht AS windkracht, CAST(COALESCE(NULLIF(waarnemingen.aantal, ''), '0') AS INTEGER) AS aantal, CAST(COALESCE(NULLIF(waarnemingen.aantalterug, ''), '0') AS INTEGER) AS aantalterug FROM waarnemingen JOIN telling_headers ON waarnemingen.tellingid = telling_headers.tellingid WHERE waarnemingen.soortid = :soortId AND telling_headers.begintijd IS NOT NULL AND telling_headers.begintijd != '' AND telling_headers.windrichting IS NOT NULL AND telling_headers.windrichting != '' ORDER BY CAST(telling_headers.begintijd AS INTEGER) ASC """) suspend fun getWindDatasetForSpecies(soortId: String): List<SpeciesWindDatasetRow>
@Query(""" SELECT telling_headers.begintijd AS begintijd, telling_headers.timezoneid AS timezoneid, CAST(COALESCE(NULLIF(waarnemingen.aantalterug, ''), '0') AS INTEGER) AS aantalterug FROM waarnemingen JOIN telling_headers ON waarnemingen.tellingid = telling_headers.tellingid WHERE telling_headers.begintijd IS NOT NULL AND telling_headers.begintijd != '' ORDER BY CAST(telling_headers.begintijd AS INTEGER) ASC """) suspend fun getAllReturnRows(): List<HeaderReturnRow>
@Query(""" SELECT waarnemingen.idLocal AS idLocal, waarnemingen.tellingid AS tellingid, waarnemingen.onlineid AS waarnemingOnlineId, telling_headers.onlineid AS headerOnlineId, telling_headers.begintijd AS begintijd, telling_headers.timezoneid AS timezoneid, telling_headers.windrichting AS windrichting, telling_headers.windkracht AS windkracht, CAST(COALESCE(NULLIF(waarnemingen.aantal, ''), '0') AS INTEGER) AS aantal, CAST(COALESCE(NULLIF(waarnemingen.aantalterug, ''), '0') AS INTEGER) AS aantalterug FROM waarnemingen JOIN telling_headers ON waarnemingen.tellingid = telling_headers.tellingid WHERE waarnemingen.soortid = :soortId AND telling_headers.begintijd IS NOT NULL AND telling_headers.begintijd != '' ORDER BY CAST(telling_headers.begintijd AS INTEGER) ASC """) suspend fun getWindDebugRowsForSpecies(soortId: String): List<SpeciesWindDebugRow>
// Retrieve distinct years available from telling_headers (derived from begintijd) @Query(""" SELECT DISTINCT strftime('%Y', datetime( CASE WHEN CAST(begintijd AS INTEGER) > 9999999999 THEN CAST(begintijd AS INTEGER)/1000 ELSE CAST(begintijd AS INTEGER) END , 'unixepoch')) as year FROM telling_headers WHERE begintijd IS NOT NULL AND begintijd != '' ORDER BY year DESC """) suspend fun getAvailableYears(): List<String> }

