    private fun startBirdNetPendingTickerIfNeeded() {
        if (!isBirdNetEnabled) {
            renderBirdNetDisabledState()
            return
        }

        birdNetPendingTickerView ?: return
        birdNetPendingTickerJob?.cancel()

        birdNetPendingTickerJob = lifecycleScope.launch {
            Log.i(TAG, "Start BirdNet process (Ticker job started)")

            // Stap 1: Auto-configuratie via NSD/mDNS als er nog niets is ingesteld
            var config = BirdNetConfig.load()
            if (!config.isConfigured) {
                runOnUiThread { setBirdNetTickerStatus(getString(R.string.telling_birdnet_discover_progress)) }
                Log.d(TAG, "Geen configuratie gevonden, start achtergrond discovery...")
                val candidates = BirdNetDiscovery.discoverAll(this@TellingScherm, port = config.port)
                if (candidates.isNotEmpty()) {
                    // Pak de eerste NSD hit als die er is, anders de eerste mDNS
                    val best = candidates.find { it.source == "NSD" } ?: candidates.first()
                    config = best.toConfig()
                    BirdNetConfig.save(config)
                    Log.i(TAG, "Achtergrond discovery succesvol: ${config.host} (Bron: ${best.source})")
                    runOnUiThread { 
                        Toast.makeText(this@TellingScherm, "BirdNET-GO automatisch gevonden: ${config.host}", Toast.LENGTH_SHORT).show()
                    }
                } else {
                    Log.w(TAG, "Achtergrond discovery mislukt, geen apparaten gevonden.")
                    runOnUiThread { setBirdNetTickerStatus(getString(R.string.telling_birdnet_pending_not_configured)) }
                    return@launch
                }
            }

            // Stap 2: Start de robuuste SSE stream via Flow
            while (isActive && isBirdNetEnabled) {
                runOnUiThread {
                    setBirdNetTickerStatus(
                        getString(
                        R.string.telling_birdnet_pending_connecting,
                        config.displayLabel.ifBlank { config.host }
                        )
                    )
                    // Als er al detecties in het geheugen/adapter zitten, houd cardBirdNetDetections zichtbaar
                    if (birdNetDetectionAdapter.itemCount > 0) {
                        uiManager.setBirdNetDetectionsVisible(true)
                    }
                }

                Log.i(TAG, "Verbinding maken met SSE stream op ${config.host}:${config.port}...")
                var receivedConnectedEvent = false

                try {
                    BirdNetSseClient.streamEvents(config).collect { event ->
                        when (event) {
                            is BirdNetSseClient.SseEvent.Connected -> {
                                receivedConnectedEvent = true
                                Log.i(TAG, "Verbonden met BirdNET-GO SSE!")
                                runOnUiThread {
                                    setBirdNetTickerStatus(getString(R.string.telling_birdnet_pending_waiting))
                                    uiManager.setBirdNetDetectionsVisible(true)
                                }
                            }

                            is BirdNetSseClient.SseEvent.Pending -> {
                                val text = formatBirdNetPendingTickerText(event.detections)
                                runOnUiThread { scheduleBirdNetPendingTickerUpdate(text) }
                            }

                            is BirdNetSseClient.SseEvent.Detection -> {
                                val currentConfig = BirdNetConfig.load()
                                val pct = event.detection.displayConfidencePct
                                if (pct >= currentConfig.minConfidencePct) {
                                    Log.d(TAG, "Live detectie ontvangen: ${event.detection.commonName} ($pct% >= ${currentConfig.minConfidencePct}%)")
                                    runOnUiThread { 
                                        birdNetDetectionAdapter.addDetection(event.detection)
                                        uiManager.setBirdNetDetectionsVisible(true)
                                        uiManager.scrollBirdNetToBottom()
                                    }
                                } else {
                                    Log.d(TAG, "Detectie ${event.detection.commonName} genegeerd ($pct% < ${currentConfig.minConfidencePct}%)")
                                }
                            }

                            is BirdNetSseClient.SseEvent.ConnectionError -> {
                                Log.w(TAG, "BirdNET SSE Verbindingsfout: ${event.message}")
                                throw Exception(event.message)
                            }

                            is BirdNetSseClient.SseEvent.Heartbeat -> {
                                Log.v(TAG, "BirdNET Heartbeat ontvangen (pijpleiding is open)")
                            }
                        }
                    }
                } catch (ex: Exception) {
                    if (!isActive || !isBirdNetEnabled) {
                        Log.d(TAG, "Ticker job gecanceld.")
                        break
                    }
                    Log.w(TAG, "BirdNET stream onderbroken: ${ex.message}. Herverbinden over enkele seconden...")
                }

                if (!isActive || !isBirdNetEnabled) break

                runOnUiThread {
                    setBirdNetTickerStatus(getString(R.string.telling_birdnet_pending_reconnecting))
                    if (birdNetDetectionAdapter.itemCount > 0) {
                        uiManager.setBirdNetDetectionsVisible(true)
                    }
                }

                // Reconnect delay
                delay(if (receivedConnectedEvent) 2_000L else 5_000L)
            }
        }
    }

    private fun handleRecognizedCandidateOnce(
        utteranceId: String?,
        candidate: Candidate,
        count: Int,
        isReturn: Boolean = false
    ) {
        val signature = speechMatchSignature(candidate.speciesId, count, isReturn)
        if (isSpeechMatchAlreadyCommitted(utteranceId, signature)) {
            Log.d(TAG, "Skipping duplicate speech final for utteranceId=$utteranceId signature=$signature")
            return
        }
        handleRecognizedCandidate(utteranceId, candidate, count, isReturn)
    }

    private fun isSpeechMatchAlreadyCommitted(utteranceId: String?, signature: String): Boolean {
        if (utteranceId.isNullOrBlank()) return false
        synchronized(committedSpeechMatchesByUtteranceId) {
            val signatures = committedSpeechMatchesByUtteranceId.getOrPut(utteranceId) { linkedSetOf() }
            val added = signatures.add(signature)
            pruneCommittedSpeechMatchesLocked()
            return !added
        }
    }

    private fun speechMatchSignature(speciesId: String, amount: Int, isReturn: Boolean): String {
        return "$speciesId|$amount|$isReturn"
    }

    private fun pruneCommittedSpeechMatchesLocked() {
        while (committedSpeechMatchesByUtteranceId.size > MAX_TRACKED_UTTERANCE_MATCHES) {
            val oldestKey = committedSpeechMatchesByUtteranceId.entries.iterator().next().key
            committedSpeechMatchesByUtteranceId.remove(oldestKey)
        }
    }

    private fun stopBirdNetPendingTicker() {
        birdNetPendingTickerJob?.cancel()
        birdNetPendingTickerJob = null
        cancelBirdNetPendingTickerHold()
    }

    private fun clearBirdNetSession() {
        stopBirdNetPendingTicker()
        uiManager.setBirdNetDetectionsVisible(false)
        birdNetDetectionAdapter.clear()
    }

    private fun handleBirdNetPressed() {
        val config = BirdNetConfig.load()
        val statusMessage = if (config.isConfigured) {
            "Huidige host: ${config.host}:${config.port}"
        } else {
            "Nog geen BirdNET-GO host ingesteld."
        }

        val options = mutableListOf("Auto-discover (NSD/mDNS)", "Handmatig IP/Host invoeren")
        if (config.isConfigured) {
            options.add("Configuratie wissen")
        }

        val dialog = AlertDialog.Builder(this)
            .setTitle("BirdNET-GO Verbinding")
            .setMessage(statusMessage)
            .setItems(options.toTypedArray()) { _, which ->
                when (which) {
                    0 -> discoverBirdNetHost()
                    1 -> showManualBirdNetConfigDialog()
                    2 -> {
                        BirdNetConfig.clear()
                        clearBirdNetSession()
                        Toast.makeText(this, "BirdNET-GO configuratie gewist", Toast.LENGTH_SHORT).show()
                    }
                }
            }
            .setNegativeButton("Annuleren", null)
            .create()
        DialogStyler.apply(dialog)
        dialog.show()
    }

    private fun showManualBirdNetConfigDialog() {
        val current = BirdNetConfig.load()
        val layout = android.widget.LinearLayout(this).apply {
            orientation = android.widget.LinearLayout.VERTICAL
            setPadding(48, 24, 48, 24)
        }

        val etHost = EditText(this).apply {
            hint = "Host (bijv. 192.168.1.50 of birdnet.local)"
            setText(current.host)
            setTextColor(Color.WHITE)
            setHintTextColor(Color.GRAY)
        }
        val etPort = EditText(this).apply {
            hint = "Poort (standaard 8080)"
            setText(current.port.toString())
            inputType = android.text.InputType.TYPE_CLASS_NUMBER
            setTextColor(Color.WHITE)
            setHintTextColor(Color.GRAY)
        }

        layout.addView(etHost)
        layout.addView(etPort)

        val dialog = AlertDialog.Builder(this)
            .setTitle("Handmatige Instellingen")
            .setView(layout)
            .setPositiveButton("Opslaan & Verbinden") { _, _ ->
                val host = etHost.text.toString().trim()
                val port = etPort.text.toString().toIntOrNull() ?: 8080
                if (host.isNotBlank()) {
                    val newConfig = BirdNetConfig(host = host, port = port)
                    BirdNetConfig.save(newConfig)
                    Log.i(TAG, "Handmatige configuratie opgeslagen: $host:$port")
                    if (isBirdNetEnabled) {
                        startBirdNetPendingTickerIfNeeded()
                    } else {
                        renderBirdNetDisabledState()
                    }
                }
            }
            .setNegativeButton("Terug", null)
            .create()
        DialogStyler.apply(dialog)
        dialog.show()
    }

    private fun discoverBirdNetHost() {
        if (!isBirdNetEnabled) {
            Toast.makeText(this, getString(R.string.telling_birdnet_enable_first), Toast.LENGTH_SHORT).show()
            return
        }

        lifecycleScope.launch {
            val progressDialog = ProgressDialogHelper.show(
                this@TellingScherm,
                "Zoeken naar BirdNET-GO apparaten..."
            )

            try {
                Log.i(TAG, "Start handmatige discovery via UI...")
                val currentConfig = BirdNetConfig.load()
                val candidates = BirdNetDiscovery.discoverAll(this@TellingScherm, port = currentConfig.port)
                progressDialog.dismiss()

                if (candidates.isEmpty()) {
                    Toast.makeText(this@TellingScherm, "Geen apparaten gevonden op het netwerk", Toast.LENGTH_LONG).show()
                    return@launch
                }

                val labels = candidates.map { it.displayLabel }.toTypedArray()
                val dialog = AlertDialog.Builder(this@TellingScherm)
                    .setTitle("Gevonden Apparaten")
                    .setItems(labels) { _, which ->
                        val selected = candidates[which]
                        BirdNetConfig.save(selected.toConfig())
                        Log.i(TAG, "Nieuwe configuratie geselecteerd via discovery: ${selected.host}")
                        startBirdNetPendingTickerIfNeeded()
                    }
                    .setNegativeButton("Annuleren", null)
                    .create()
                DialogStyler.apply(dialog)
                dialog.show()

            } catch (ex: Exception) {
                progressDialog.dismiss()
                Log.w(TAG, "Handmatige discovery mislukt: ${ex.message}", ex)
                Toast.makeText(this@TellingScherm, "Fout tijdens zoeken: ${ex.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun formatBirdNetPendingTickerText(detections: List<BirdNetPendingDetection>): String {
        if (detections.isEmpty()) {
            return getString(R.string.telling_birdnet_pending_waiting)
        }

        return detections
            .sortedWith(
                compareByDescending<BirdNetPendingDetection> { it.maxConfidence }
                    .thenByDescending { it.confidence }
                    .thenByDescending { it.hitCount }
            )
            .take(10)
            .joinToString(separator = "   •   ") { detection ->
                val dutchName = com.yvesds.vt5.features.birdnet.BirdNetSpeciesResolver.resolveDutchName(
                    context = this@TellingScherm,
                    scientificName = detection.scientificName,
                    commonName = detection.commonName
                )
                getString(
                    R.string.telling_birdnet_pending_item,
                    dutchName,
                    detection.displayConfidencePct,
                    detection.hitCount.coerceAtLeast(1)
                )
            }
    }

    private fun addBirdNetDetectionToCount(detection: com.yvesds.vt5.features.birdnet.BirdNetDetection) {
        val resolved = com.yvesds.vt5.features.birdnet.BirdNetSpeciesResolver.resolveSpecies(
            context = this,
            scientificName = detection.scientificName,
            commonName = detection.commonName
        )

        lifecycleScope.launch {
            // 1. Voeg de tegel toe aan het scherm indien nog niet aanwezig
            val addedNewTile = tegelBeheer.voegSoortToeIndienNodig(resolved.soortId, resolved.dutchName, 1)
            if (!addedNewTile) {
                // Tegel bestond al: verhoog het aantal met +1
                tegelBeheer.verhoogSoortAantal(resolved.soortId, 1)
            }

            // 2. Leg vast in de actieve tellingssessie (finals / records)
            speciesManager.collectFinalAsRecord(resolved.soortId, 1)

            // 3. Registreer als recent gebruikte soort voor favorieten
            RecentSpeciesStore.recordUse(this@TellingScherm, resolved.soortId)

            // 4. Feedback aan de gebruiker
            Toast.makeText(this@TellingScherm, "✓ +1 ${resolved.dutchName} opgenomen in telling", Toast.LENGTH_SHORT).show()
            Log.i(TAG, "BirdNET detectie toegevoegd aan telling: ${resolved.dutchName} (SoortID: ${resolved.soortId})")
        }
    }

    private fun openInstellingenScherm() {
        lifecycleScope.launch {
            tileTapAggregationManager.flushAllAndAwait()
            startActivity(Intent(this@TellingScherm, InstellingenScherm::class.java))
        }
    }

    private fun toggleHourlyAlarm() {
        val currentlyEnabled = HourlyAlarmManager.isEnabled(this)
        HourlyAlarmManager.setEnabled(this, !currentlyEnabled)
        updateAlarmToggleUi()
    }

    private fun updateAlarmToggleUi() {
        if (!::binding.isInitialized) return
        val enabled = HourlyAlarmManager.isEnabled(this)
        val color = if (enabled) Color.parseColor("#00C853") else Color.parseColor("#D50000")
        binding.btnToggleAlarm.setColorFilter(color)
        binding.btnToggleAlarm.contentDescription = getString(
            if (enabled) R.string.hoofd_alarm_enabled else R.string.hoofd_alarm_disabled
        )
    }

    private fun refreshDailyTotalsUi() {
        if (!::binding.isInitialized) return
        lifecycleScope.launch {
            val labels = withContext(Dispatchers.IO) {
                runCatching { TelpostDirectionLabelProvider.getForCurrentSession(this@TellingScherm) }
                    .getOrElse { TelpostDirectionLabelProvider.Labels(null, null, "Aantal :", "Aantal terug :") }
            }
            val totals = withContext(Dispatchers.IO) {
                DailyDirectionTotalsStore.getTodayTotalsForCurrentSession(this@TellingScherm)
            }

            binding.tvDailyMainTotal.text = getString(
                R.string.telling_daily_total_item,
                labels.mainShort ?: getString(R.string.telling_daily_total_main_fallback),
                totals.mainTotal
            )
            binding.tvDailyReturnTotal.text = getString(
                R.string.telling_daily_total_item,
                labels.returnShort ?: getString(R.string.telling_daily_total_return_fallback),
                totals.returnTotal
            )
        }
    }

    private fun checkDirectionAliases() {
        lifecycleScope.launch(Dispatchers.IO) {
            // Wait for startup rebuild to complete to ensure we have the latest index
            com.yvesds.vt5.VT5App.awaitStartupAliasRefresh()

            val repo = com.yvesds.vt5.features.alias.AliasRepository.getInstance(this@TellingScherm)
            if (!repo.isDataLoaded) {
                repo.loadAliasData()
            }
            val aliases = repo.getAliasesForSpecies(com.yvesds.vt5.features.alias.SPECIES_ID_DIR_RETURN)
            // Show tip if no user-trained aliases are present for direction
            val hasUserTrained = aliases.any { it.source == "user_field_training" }
            if (!hasUserTrained) {
                withContext(Dispatchers.Main) {
                    addLog("Tip: Train richtings-woorden door een richting in te spreken na het aantal (bijv. 'Buizerd 5 NOORD') en tik op de tekst om 'NOORD' als richting aan te leren (koppel aan 'Richting: Terug').", "systeem")
                }
            }
        }
    }

    private fun syncDailyTotalsRecord(item: ServerTellingDataItem) {
        DailyDirectionTotalsStore.upsertRecord(
            context = this,
            telpostId = TellingSessionManager.preselectState.value.telpostId,
            record = item
        )
        refreshDailyTotalsUi()
    }

    private fun syncDailyObservationRecord(item: ServerTellingDataItem, refreshOrder: Boolean = true) {
        DailySpeciesObservationRankStore.upsertRecord(this, item)
        if (refreshOrder) {
            refreshDailyObservationOrdering()
        }
    }

    private fun refreshDailyObservationOrdering() {
        if (!::tegelBeheer.isInitialized) return
        tegelBeheer.setDailyObservationCounts(DailySpeciesObservationRankStore.getTodayCounts(this))
    }

    private fun applyTileSortingPreference() {
        if (!::tegelBeheer.isInitialized) return
        tegelBeheer.setDynamicObservationSortingEnabled(
            InstellingenScherm.isDynamicTileSortingEnabled(this)
        )
    }

    /* ---------- UI Callback Handlers ---------- */

    /**
     * Handle tap on partial log entry - show alias dialog.
     */
    private fun handlePartialTap(@Suppress("UNUSED_PARAMETER") _pos: Int, row: SpeechLogRow) {
        when (row.bron) {
            "partial", "raw" -> {
                val (nameOnly, cnt) = parseNameAndCountFromDisplay(row.tekst)

                // Provide the full phrase and individual tokens as alias candidates
                val rawText = row.tekst.replace("(?i)^asr:\\s*".toRegex(), "").trim()
                val tokens = rawText.split("\\s+".toRegex())
                val aliasCandidates = mutableListOf<String>()
                if (nameOnly.isNotBlank()) aliasCandidates.add(nameOnly)
                tokens.forEach { t ->
                    val norm = com.yvesds.vt5.utils.TextUtils.normalizeLowerNoDiacritics(t)
                    if (norm.isNotBlank() && !com.yvesds.vt5.features.speech.NumberPatterns.isNumberWord(norm) && t.toIntOrNull() == null) {
                        if (!aliasCandidates.contains(t)) aliasCandidates.add(t)
                    }
                }

                ensureAvailableSpeciesFlat { flat ->
                    dialogHelper.showAddAliasDialog(aliasCandidates, cnt, flat, 
                        onAliasAdded = { speciesId, canonical, count ->
                            val trainedAlias = aliasCandidates.firstOrNull() ?: nameOnly // Approximate
                            addLog("Alias toegevoegd: '$canonical'", "alias")
                            Toast.makeText(this, getString(R.string.telling_alias_saved_buffer), Toast.LENGTH_SHORT).show()

                            lifecycleScope.launch {
                                Toast.makeText(this@TellingScherm, getString(R.string.telling_index_updating), Toast.LENGTH_SHORT).show()
                                val ok = withContext(Dispatchers.IO) {
                                    try {
                                        AliasManager.forceRebuildCborNow(this@TellingScherm, safHelper)
                                        true
                                    } catch (ex: Exception) {
                                        Log.w(TAG, "forceRebuildCborNow failed: ${ex.message}", ex)
                                        false
                                    }
                                }
                                if (ok) {
                                    Toast.makeText(this@TellingScherm, getString(R.string.telling_alias_saved_index_updated), Toast.LENGTH_SHORT).show()
                                    speciesManager.refreshAliasesRuntimeAsync(speechHandler) { context ->
                                        speechHandler.updateCachedMatchContext(context)
                                    }
                                } else {
                                    Toast.makeText(this@TellingScherm, getString(R.string.telling_alias_saved_index_later), Toast.LENGTH_LONG).show()
                                }
                            }

                            if (count > 0 && speciesId != com.yvesds.vt5.features.alias.SPECIES_ID_DIR_RETURN) {
                                lifecycleScope.launch {
                                    // Add species to tiles (creates tile if not present, or increases count)
                                    speciesManager.addSpeciesToTilesIfNeeded(speciesId, canonical, count)
                                    // Collect record; onRecordCollected will render the single finals row.
                                    speciesManager.collectFinalAsRecord(speciesId, count)
                                }
                            }
                        },
                        fragmentManager = supportFragmentManager
                    )
                }
            }
        }
    }

    /**
     * Handle tap on final log entry - open annotation screen.
     */
    private fun handleFinalTap(pos: Int, row: SpeechLogRow) {
        if (row.bron == "final" && !row.isPending) {
            annotationHandler.launchAnnotatieScherm(
                text = row.tekst,
                timestamp = row.ts,
                rowPosition = pos,
                recordLocalId = row.recordLocalId,
                recordGroupId = row.rowKey
            )
        }
    }

    /**
     * Handle Afronden button with confirmation dialog.
     * Shows a popup to allow editing begintijd, eindtijd, and opmerkingen.
     */
    private fun handleAfrondenWithConfirmation() {
        if (isClientFlowLocked()) {
            handleClientStopRequest()
            return
        }

        // Get current envelope data to show as defaults in dialog
        val envelopeData = getCurrentEnvelopeData()

        val dialog = AfrondConfirmDialog.newInstance(
            begintijdEpoch = envelopeData.begintijd,
            eindtijdEpoch = envelopeData.eindtijd,
            opmerkingen = envelopeData.opmerkingen
        )

        dialog.listener = object : AfrondConfirmDialog.AfrondConfirmListener {
            override fun onAfrondConfirmed(begintijdEpoch: String, eindtijdEpoch: String, opmerkingen: String) {
                lifecycleScope.launch {
                    val progressDialog = ProgressDialogHelper.show(this@TellingScherm, "Bezig met afronden upload...")
                    try { 
                        handleAfronden(
                            MetadataUpdates(
                                begintijd = begintijdEpoch,
                                eindtijd = eindtijdEpoch,
                                opmerkingen = opmerkingen
                            )
                        )
                    } finally { 
                        progressDialog.dismiss() 
                    }
                }
            }

            override fun onAfrondCancelled() {
                // User cancelled - do nothing
            }
        }

        dialog.show(supportFragmentManager, "afrondConfirm")
    }

    /**
     * Data class to hold current envelope metadata for the confirm dialog.
     */
    private data class EnvelopeData(
        val begintijd: String,
        val eindtijd: String,
        val opmerkingen: String
    )

    /**
     * Get current envelope data from saved preferences.
     */
    private fun getCurrentEnvelopeData(): EnvelopeData {
        return try {
            val savedEnvelopeJson = prefs.getString("pref_saved_envelope_json", null)
            if (savedEnvelopeJson.isNullOrBlank()) {
                // Return defaults with current time
                val nowEpoch = (System.currentTimeMillis() / 1000L).toString()
                return EnvelopeData(nowEpoch, nowEpoch, "")
            }

            val envelopeList = VT5App.json.decodeFromString(
                ListSerializer(ServerTellingEnvelope.serializer()),
                savedEnvelopeJson
            )

            if (envelopeList.isEmpty()) {
                val nowEpoch = (System.currentTimeMillis() / 1000L).toString()
                return EnvelopeData(nowEpoch, nowEpoch, "")
            }

            val envelope = envelopeList[0]
            EnvelopeData(
                begintijd = envelope.begintijd,
                eindtijd = envelope.eindtijd.ifBlank { (System.currentTimeMillis() / 1000L).toString() },
                opmerkingen = envelope.opmerkingen
            )
        } catch (e: Exception) {
            Log.w(TAG, "Failed to get envelope data: ${e.message}")
            val nowEpoch = (System.currentTimeMillis() / 1000L).toString()
            EnvelopeData(nowEpoch, nowEpoch, "")
        }
    }

    /**
     * Handle Save/Close button - show current status screen.
     */
    private fun handleSaveClose(tiles: List<SoortRow>) {
        val ids = ArrayList<String>(tiles.size)
        val names = ArrayList<String>(tiles.size)
        val countsMain = ArrayList<String>(tiles.size)
        val countsReturn = ArrayList<String>(tiles.size)
        for (row in tiles) {
            ids.add(row.soortId)
            names.add(row.naam)
            countsMain.add(row.countMain.toString())
            countsReturn.add(row.countReturn.toString())
        }

        // Get the telling begintijd (epoch seconds) for correct season determination
        val begintijdEpoch = getTellingBegintijdEpoch()

        val intent = Intent(this, HuidigeStandScherm::class.java).apply {
            putStringArrayListExtra(HuidigeStandScherm.EXTRA_SOORT_IDS, ids)
            putStringArrayListExtra(HuidigeStandScherm.EXTRA_SOORT_NAMEN, names)
            putStringArrayListExtra(HuidigeStandScherm.EXTRA_SOORT_AANTALLEN_MAIN, countsMain)
            putStringArrayListExtra(HuidigeStandScherm.EXTRA_SOORT_AANTALLEN_RETURN, countsReturn)
            if (begintijdEpoch > 0) {
                putExtra(HuidigeStandScherm.EXTRA_TELLING_BEGINTIJD_EPOCH, begintijdEpoch)
            }
        }
        startActivity(intent)
    }

    /**
     * Get the telling begintijd (start time) as epoch seconds from the saved envelope.
     * This is needed to correctly determine the season for column mapping in HuidigeStandScherm.
     * 
     * @return The begintijd as epoch seconds, or -1L if not available
     */
    private fun getTellingBegintijdEpoch(): Long {
        return try {
            val savedEnvelopeJson = prefs.getString("pref_saved_envelope_json", null)
            if (savedEnvelopeJson.isNullOrBlank()) return -1L

            val envelopeList = VT5App.json.decodeFromString(
                ListSerializer(ServerTellingEnvelope.serializer()),
                savedEnvelopeJson
            )

            if (envelopeList.isEmpty()) return -1L

            // The begintijd field is a string containing epoch seconds
            envelopeList[0].begintijd.toLongOrNull() ?: -1L
        } catch (e: Exception) {
            Log.w(TAG, "Failed to get telling begintijd: ${e.message}")
            -1L
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        // Check if this is triggered by the hourly alarm
        if (intent.getBooleanExtra(EXTRA_SHOW_HUIDIGE_STAND, false)) {
            showHuidigeStandScherm()
        }
        if (intent.hasExtra(EXTRA_CLIENT_QR_PAYLOAD)) {
            clientModeLocked = true
            handleClientStartIntent()
        }
        updateAlarmToggleUi()
    }

    /**
     * Show the HuidigeStandScherm with the current tile data.
     * Called by hourly alarm (via onCreate or onNewIntent).
     */
    private fun showHuidigeStandScherm() {
        if (::tegelBeheer.isInitialized) {
            val tiles = tegelBeheer.getTiles()
            val rows = tiles.map { tile ->
                SoortRow(
                    soortId = tile.soortId,
                    naam = tile.naam,
                    countMain = tile.countMain,
                    countReturn = tile.countReturn
                )
            }
            handleSaveClose(rows)
        }
    }

    override fun onRequestPermissionsResult(requestCode: Int, permissions: Array<out String>, grantResults: IntArray) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (::initializer.isInitialized) {
            initializer.onPermissionResult(requestCode, grantResults)
        }
    }

    override fun onResume() {
        super.onResume()
        // Start alarm monitoring when the screen is visible
        if (::alarmHandler.isInitialized) {
            alarmHandler.startMonitoring()
        }

        updateAlarmToggleUi()
        ensurePendingTellingPromptOnRestore()

        // Refresh log text size/color from settings
        val partialsSize = InstellingenScherm.getPartialsTextSizeSp(this)
        val finalsSize = InstellingenScherm.getFinalsTextSizeSp(this)
        val partialsColor = InstellingenScherm.getPartialsTextColor(this)
        val unmatchedPartialsColor = InstellingenScherm.getUnmatchedPartialsTextColor(this)
        val finalsColor = InstellingenScherm.getFinalsTextColor(this)
        partialsAdapter.updatePartialsTextSize(partialsSize)
        finalsAdapter.updateFinalsTextSize(finalsSize)
        partialsAdapter.updatePartialsTextColor(partialsColor)
        partialsAdapter.updateUnmatchedPartialsTextColor(unmatchedPartialsColor)
        finalsAdapter.updateFinalsTextColor(finalsColor)

        val tilesSize = InstellingenScherm.getLettergroottTegelsSp(this)
        refreshTileTapAggregationWindowFromSettings()
        tilesAdapter.updateTextSize(tilesSize)
        tilesAdapter.notifyDataSetChanged()

        uiManager.updatePartials(uiManager.getCurrentPartials())
        uiManager.updateFinals(uiManager.getCurrentFinals())
        updateMasterClientConnectionUi()
        maybeContinuePendingClientConnection()
        refreshFinalObservationUploadMarkers()
        refreshDailyTotalsUi()
        applyTileSortingPreference()
        refreshDailyObservationOrdering()

        // Herstel BirdNET detectiekaart & sessie-data bij terugkeer naar dit scherm
        if (::birdNetDetectionAdapter.isInitialized) {
            birdNetDetectionAdapter.restoreFromSession()
            if (birdNetDetectionAdapter.itemCount > 0) {
                uiManager.setBirdNetDetectionsVisible(true)
                uiManager.scrollBirdNetToBottom()
            }
        }
        if (isBirdNetEnabled) {
            startBirdNetPendingTickerIfNeeded()
        } else {
            renderBirdNetDisabledState()
        }
    }

    private fun initializeBirdNetToggle() {
        binding.swBirdNetEnabled.setOnCheckedChangeListener(null)
        binding.swBirdNetEnabled.isChecked = isBirdNetEnabled
        binding.swBirdNetEnabled.visibility = View.VISIBLE
        binding.birdnetContainer.visibility = View.VISIBLE
        binding.swBirdNetEnabled.setOnCheckedChangeListener { _, checked ->
            if (checked == isBirdNetEnabled) return@setOnCheckedChangeListener
            isBirdNetEnabled = checked
            if (checked) {
                birdNetPendingTickerView?.setTextColor(ContextCompat.getColor(this, R.color.vt5_white))
                startBirdNetPendingTickerIfNeeded()
            } else {
                renderBirdNetDisabledState()
            }
        }

        if (!isBirdNetEnabled) {
            renderBirdNetDisabledState()
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        outState.putBoolean(STATE_BIRDNET_ENABLED, isBirdNetEnabled)
        super.onSaveInstanceState(outState)
    }

    private fun renderBirdNetDisabledState() {
        stopBirdNetPendingTicker()
        uiManager.setBirdNetDetectionsVisible(false)
        birdNetPendingTickerView?.let { ticker ->
            ticker.text = getString(R.string.telling_birdnet_disabled)
            ticker.setTextColor(ContextCompat.getColor(this, R.color.vt5_on_surface))
        }
    }

    private fun setBirdNetTickerStatus(text: String) {
        birdNetPendingTickerView?.let { ticker ->
            ticker.setTextColor(ContextCompat.getColor(this, R.color.vt5_white))
            ticker.text = text
        }
        cancelBirdNetPendingTickerHold()
    }

    private fun scheduleBirdNetPendingTickerUpdate(text: String) {
        if (!isBirdNetEnabled) return
        val ticker = birdNetPendingTickerView ?: return
        val now = System.currentTimeMillis()

        if (now >= birdNetPendingTickerHoldUntilMs) {
            ticker.setTextColor(ContextCompat.getColor(this, R.color.vt5_white))
            ticker.text = text
            birdNetPendingTickerHoldUntilMs = now + BIRDNET_PENDING_HOLD_MS
            pendingBirdNetTickerText = null
            birdNetPendingTickerFlushJob?.cancel()
            birdNetPendingTickerFlushJob = null
            return
        }

        pendingBirdNetTickerText = text
        if (birdNetPendingTickerFlushJob?.isActive == true) return

        val delayMs = (birdNetPendingTickerHoldUntilMs - now).coerceAtLeast(0L)
        birdNetPendingTickerFlushJob = lifecycleScope.launch {
            delay(delayMs)
            val latestText = pendingBirdNetTickerText ?: return@launch
            if (!isBirdNetEnabled) return@launch
            birdNetPendingTickerView?.let { pendingTicker ->
                pendingTicker.setTextColor(ContextCompat.getColor(this@TellingScherm, R.color.vt5_white))
                pendingTicker.text = latestText
                birdNetPendingTickerHoldUntilMs = System.currentTimeMillis() + BIRDNET_PENDING_HOLD_MS
            }
            pendingBirdNetTickerText = null
            birdNetPendingTickerFlushJob = null
        }
    }

    private fun cancelBirdNetPendingTickerHold() {
        birdNetPendingTickerFlushJob?.cancel()
        birdNetPendingTickerFlushJob = null
        pendingBirdNetTickerText = null
        birdNetPendingTickerHoldUntilMs = 0L
    }

    private fun ensurePendingTellingPromptOnRestore() {
        if (intent?.getBooleanExtra(EXTRA_RESTORE_PENDING_TELLING, false) == true) return
        if (restoredFromSavedEnvelope) return
        if (pendingRecords.isNotEmpty()) return

        lifecycleScope.launch {
            try {
                if (!envelopePersistence.hasSavedEnvelope()) return@launch
                val savedEnvelope = envelopePersistence.loadSavedEnvelope() ?: return@launch
                if (savedEnvelope.data.isEmpty()) return@launch
                if (TellingUploadFlags.isSent(this@TellingScherm, savedEnvelope.tellingid, savedEnvelope.onlineid)) return@launch

                // Redirect to HoofdActiviteit so the resume prompt can be shown there.
                val intent = Intent(this@TellingScherm, HoofdActiviteit::class.java)
                intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP)
                startActivity(intent)
                finish()
            } catch (e: Exception) {
                Log.w(TAG, "ensurePendingTellingPromptOnRestore failed: ${e.message}", e)
            }
        }
    }

    private fun maybeContinuePendingClientConnection() {
        val payload = pendingClientConnectionPayload ?: return
        if (!McNetworkUtils.isWifiTransportActive(this)) return
        pendingClientConnectionPayload = null
        connectClientToMaster(payload.ip, payload.session)
    }

    private fun setupBackPressedCallback() {
        onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
            override fun handleOnBackPressed() {
                val pendingCount = pendingClientObservationCount()
                if (pendingCount > 0) {
                    showPendingClientObservationsDialog(pendingCount)
                    return
                }

                isEnabled = false
                onBackPressedDispatcher.onBackPressed()
            }
        })
    }

    private fun pendingClientObservationCount(): Int {
        return if (isClientFlowLocked()) {
            mcEventQueue?.totalUnacknowledged() ?: 0
        } else {
            0
        }
    }

    private fun isClientFlowLocked(): Boolean = clientModeLocked && mcMasterServer == null

    private fun showPendingClientObservationsDialog(pendingCount: Int) {
        if (pendingCount > 0) {
            val dialog = AlertDialog.Builder(this)
                .setTitle(R.string.mc_dialog_leave_pending_title)
                .setMessage(getString(R.string.mc_dialog_leave_pending_message, pendingCount))
                .setPositiveButton(android.R.string.ok, null)
                .create()
            DialogStyler.apply(dialog)
            dialog.show()
        }
    }

    private fun handleClientStopRequest() {
        lifecycleScope.launch {
            val progressDialog = ProgressDialogHelper.show(
                this@TellingScherm,
                getString(R.string.mc_client_stop_progress)
            )
            try {
                tileTapAggregationManager.flushAllAndAwait()
                mcClientConnector?.flushQueue()

                val pendingCount = awaitClientObservationDrain()
                if (pendingCount > 0) {
                    showPendingClientObservationsDialog(pendingCount)
                    updateMasterClientConnectionUi()
                    return@launch
                }
            } finally {
                progressDialog.dismiss()
            }

            showClientStopConfirmationDialog()
        }
    }

    private suspend fun awaitClientObservationDrain(timeoutMs: Long = 2_500L): Int {
        if (!isClientFlowLocked()) return 0

        val deadline = System.currentTimeMillis() + timeoutMs
        var pendingCount = pendingClientObservationCount()
        while (pendingCount > 0 && System.currentTimeMillis() < deadline) {
            kotlinx.coroutines.delay(200L)
            mcClientConnector?.flushQueue()
            pendingCount = pendingClientObservationCount()
        }
        return pendingCount
    }

    private fun showClientStopConfirmationDialog() {
        val dialog = AlertDialog.Builder(this)
            .setTitle(R.string.mc_dialog_leave_title)
            .setMessage(R.string.mc_dialog_leave_message)
            .setPositiveButton(R.string.mc_dialog_leave_confirm) { _, _ ->
                completeClientStopAndNavigateHome()
            }
            .setNegativeButton(R.string.mc_dialog_leave_cancel, null)
            .create()
        DialogStyler.apply(dialog)
        dialog.show()
    }

    private fun completeClientStopAndNavigateHome() {
        val connector = mcClientConnector
        if (isClientFlowLocked() && connector?.leaveSession("gebruiker gestopt met tellen") == false) {
            val pendingCount = pendingClientObservationCount()
            if (pendingCount > 0) {
                showPendingClientObservationsDialog(pendingCount)
            }
            updateMasterClientConnectionUi()
            return
        }

        connector?.stop()
        mcClientConnector = null
        mcEventQueue = null
        clientModeLocked = false
        pendingClientConnectionPayload = null
        lastObservedClientState = ClientConnector.State.DISCONNECTED

        MasterClientRuntimeStore.clearClientRuntime(stopClient = false)
        MasterClientRuntimeStore.clearPreserveAcrossTellings()
        MasterClientPrefs.resetToSolo(this)
        TellingSessionManager.clear()

        prefs.edit()
            .remove("pref_saved_envelope_json")
            .remove("pref_online_id")
            .remove("pref_telling_id")
            .apply()

        updateMasterClientConnectionUi()
        Toast.makeText(this, getString(R.string.mc_toast_left_session), Toast.LENGTH_SHORT).show()

        val intent = Intent(this, HoofdActiviteit::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_CLEAR_TASK or Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        startActivity(intent)
        finish()
    }

    override fun onPause() {
        super.onPause()
        stopBirdNetPendingTicker()
        if (::alarmHandler.isInitialized) {
            alarmHandler.stopMonitoring()
        }
        lifecycleScope.launch {
            tileTapAggregationManager.flushAllAndAwait()

            // Always persist the latest envelope snapshot as a safety net
            withContext(Dispatchers.IO) {
                try {
                    val records = synchronized(pendingRecords) { pendingRecords.toList() }
                    if (records.isNotEmpty()) {
                        envelopePersistence.saveEnvelopeWithRecords(records)
                    }
                } catch (ex: Exception) {
                    Log.w(TAG, "Envelope persistence failed onPause: ${ex.message}", ex)
                }
            }
        }
    }

    override fun onDestroy() {
        stopBirdNetPendingTicker()
        dismissMasterPairingDialog()
        synchronized(committedSpeechMatchesByUtteranceId) {
            committedSpeechMatchesByUtteranceId.clear()
        }
        try {
            unregisterReceiver(aliasReloadReceiver)
        } catch (_: Exception) {}
        try {
            if (::speechHandler.isInitialized) {
                speechHandler.cleanup()
            }
        } catch (_: Exception) {}
        parseJobsByUtteranceId.values.forEach { it.cancel() }
        parseJobsByUtteranceId.clear()
        try {
            if (::alarmHandler.isInitialized) {
                alarmHandler.cleanup()
            }
        } catch (_: Exception) {}
        try {
            if (!MasterClientRuntimeStore.isPreservingAcrossTellings()) {
                mcMasterServer?.stop()
                mcClientConnector?.stop()
                MasterClientRuntimeStore.clearAll()
            }
        } catch (_: Exception) {}
        super.onDestroy()
    }

