    private fun clearSpeechPartialLog(utteranceId: String?) {
        if (utteranceId.isNullOrBlank()) return
        val updatedPartials = logManager.clearSpeechPartialLog(utteranceId)
        lifecycleScope.launch(Dispatchers.Main) {
