    private fun broadcastTileSyncIfMaster(tiles: List<SoortTile>) {
        mcMasterServer?.broadcastTileSync(
            tiles.map {
                TileSyncItem(
                    soortid = it.soortId,
                    naam = it.naam,
                    countMain = it.countMain,
