    private fun queueClientObservationIfNeeded(item: ServerTellingDataItem) {
        val connector = mcClientConnector ?: return
        if (mcMasterServer != null) return

        val clientEventId = connector.queueObservation(
            soortid = item.soortid,
            aantal = item.aantal.toIntOrNull() ?: 0,
            aantalterug = item.aantalterug.toIntOrNull() ?: 0,
            tijdstip = item.tijdstip.toLongOrNull() ?: (System.currentTimeMillis() / 1000L),
            geslacht = item.geslacht,
            leeftijd = item.leeftijd,
            kleed = item.kleed,
            opmerkingen = item.opmerkingen,
            recordPayload = encodeObservationRecordPayload(item)
        )

        if (!clientEventId.isNullOrBlank()) {
            mcClientEventIdByRecordId[item.idLocal] = clientEventId
            mcClientRecordIdByEvent[clientEventId] = item.idLocal
            persistClientEventMappings()
            updateClientFinalObservationRow(item, ObservationDeliveryState.PENDING)
            updateMasterClientConnectionUi()
        }
    }

    private fun queueClientObservationUpdateIfNeeded(item: ServerTellingDataItem) {
        val connector = mcClientConnector ?: return
        if (mcMasterServer != null) return

        val clientEventId = mcClientEventIdByRecordId[item.idLocal] ?: return
        connector.queueObservationUpdate(
            clientEventId = clientEventId,
            soortid = item.soortid,
            aantal = item.aantal.toIntOrNull() ?: 0,
            aantalterug = item.aantalterug.toIntOrNull() ?: 0,
            tijdstip = item.tijdstip.toLongOrNull() ?: (System.currentTimeMillis() / 1000L),
            geslacht = item.geslacht,
            leeftijd = item.leeftijd,
            kleed = item.kleed,
            opmerkingen = item.opmerkingen,
            recordPayload = encodeObservationRecordPayload(item)
        )
        updateClientFinalObservationRow(item, ObservationDeliveryState.PENDING)
    }

    private fun queueClientTileAnnouncementsIfNeeded(tiles: List<TellingSpeciesManager.AddedTileInfo>) {
        val connector = mcClientConnector ?: return
        if (mcMasterServer != null) return
        if (!isClientFlowLocked()) return

        tiles.asSequence()
            .filter { it.initialCount == 0 }
            .filter { it.soortId.isNotBlank() }
            .forEach { tile ->
                connector.queueObservation(
                    soortid = tile.soortId,
                    aantal = 0,
                    aantalterug = 0,
                    tijdstip = System.currentTimeMillis() / 1000L,
                    recordPayload = ""
                )
            }
        updateMasterClientConnectionUi()
    }

    private fun restoreClientEventMappings() {
        val raw = prefs.getString(KEY_CLIENT_EVENT_MAP_JSON, null) ?: return
        try {
            val json = org.json.JSONObject(raw)
            val keys = json.keys()
            while (keys.hasNext()) {
                val recordId = keys.next()
                val eventId = json.optString(recordId)
                if (recordId.isNotBlank() && eventId.isNotBlank()) {
                    mcClientEventIdByRecordId[recordId] = eventId
                    mcClientRecordIdByEvent[eventId] = recordId
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "Kon client event mapping niet herstellen: ${e.message}", e)
        }
    }

    private fun persistClientEventMappings() {
        try {
            val json = org.json.JSONObject()
            mcClientEventIdByRecordId.forEach { (recordId, eventId) ->
                json.put(recordId, eventId)
            }
            prefs.edit().putString(KEY_CLIENT_EVENT_MAP_JSON, json.toString()).apply()
        } catch (e: Exception) {
            Log.w(TAG, "Kon client event mapping niet bewaren: ${e.message}", e)
        }
    }

    private fun encodeObservationRecordPayload(record: ServerTellingDataItem): String {
        return try {
            VT5App.json.encodeToString(ServerTellingDataItem.serializer(), record)
        } catch (ex: Exception) {
            Log.w(TAG, "Kon client record payload niet serialiseren: ${ex.message}", ex)
            ""
        }
    }

    private suspend fun handleLiveClientEvent(
        clientId: String,
        clientEventId: String,
        isUpdate: Boolean,
        soortId: String,
        amount: Int,
        aantalterug: Int,
        tijdstip: Long,
        geslacht: String,
        leeftijd: String,
        kleed: String,
        opmerkingen: String,
        recordPayload: String
    ) {
        val eventKey = "$clientId::$clientEventId"
        val clientLogPrefix = resolveClientLogPrefix(clientId)
        val payloadRecord = runCatching {
            VT5App.json.decodeFromString(ServerTellingDataItem.serializer(), recordPayload)
        }.getOrNull()
        val isTileAnnouncementOnly = payloadRecord == null && amount <= 0 && aantalterug <= 0

        withContext(Dispatchers.Main.immediate) {
            val existingIdLocal = mcClientRecordIdByEvent[eventKey]
            if (isUpdate && !existingIdLocal.isNullOrBlank()) {
                mcClientLogPrefixByRecordId[existingIdLocal] = clientLogPrefix
                applyClientRecordUpdate(clientId, eventKey, existingIdLocal, soortId, amount, aantalterug, tijdstip, geslacht, leeftijd, kleed, opmerkingen, recordPayload)
                return@withContext
            }

            if (isUpdate && existingIdLocal.isNullOrBlank()) {
                applyClientRecordUpdate(clientId, eventKey, null, soortId, amount, aantalterug, tijdstip, geslacht, leeftijd, kleed, opmerkingen, recordPayload)
                return@withContext
            }

            val displayName = resolveSpeciesName(soortId)
            val tileAdded = tegelBeheer.voegSoortToeIndienNodig(soortId, displayName, 0)
            if (tileAdded) {
                updateSelectedSpeciesMap()
            }

            if (isTileAnnouncementOnly) {
                return@withContext
            }

            val tellingId = prefs.getString("pref_telling_id", null) ?: return@withContext
            val idLocal = com.yvesds.vt5.features.network.DataUploader.getAndIncrementRecordId(this@TellingScherm, tellingId)
            val uploadTimestamp = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", resources.configuration.locales[0]).format(java.util.Date())
            val item = buildMasterClientRecord(
                idLocal = idLocal,
                tellingId = tellingId,
                fallbackSoortId = soortId,
                fallbackAmount = amount,
                fallbackAantalterug = aantalterug,
                fallbackTijdstip = tijdstip,
                fallbackGeslacht = geslacht,
                fallbackLeeftijd = leeftijd,
                fallbackKleed = kleed,
                fallbackOpmerkingen = opmerkingen,
                groupId = eventKey,
                uploadtijdstip = uploadTimestamp,
                payloadRecord = payloadRecord
            )

            addOrReplacePendingRecord(item)
            mcClientRecordIdByEvent[eventKey] = idLocal
            mcClientLogPrefixByRecordId[idLocal] = clientLogPrefix
            if ((item.aantal.toIntOrNull() ?: 0) > 0) {
                speciesManager.updateSoortCountInternal(item.soortid, item.aantal.toIntOrNull() ?: 0)
            }
            if ((item.aantalterug.toIntOrNull() ?: 0) > 0) {
                tegelBeheer.verhoogSoortAantalReturn(item.soortid, item.aantalterug.toIntOrNull() ?: 0)
            }
            upsertFinalObservationRow(buildFinalObservationRow(item, isClientOrigin = true, clientLogPrefix = clientLogPrefix))
            refreshDailyObservationOrdering()
        }
    }

    private suspend fun applyClientRecordUpdate(
        clientId: String,
        eventKey: String,
        idLocal: String?,
        soortId: String,
        amount: Int,
        aantalterug: Int,
        tijdstip: Long,
        geslacht: String,
        leeftijd: String,
        kleed: String,
        opmerkingen: String,
        recordPayload: String
    ) {
        val idx = synchronized(pendingRecords) {
            when {
                !idLocal.isNullOrBlank() -> pendingRecords.indexOfFirst { it.idLocal == idLocal || it.groupid == eventKey }
                else -> pendingRecords.indexOfFirst { it.groupid == eventKey }
            }
        }
        if (idx < 0) return

        val resolvedIdLocal = synchronized(pendingRecords) { pendingRecords[idx].idLocal }
        val clientLogPrefix = mcClientLogPrefixByRecordId[resolvedIdLocal]
            ?: resolveClientLogPrefix(clientId).also { mcClientLogPrefixByRecordId[resolvedIdLocal] = it }

        val existing = synchronized(pendingRecords) { pendingRecords[idx] }
        val payloadRecord = runCatching {
            VT5App.json.decodeFromString(ServerTellingDataItem.serializer(), recordPayload)
        }.getOrNull()
        val updated = mergeClientRecordUpdate(
            existing = existing,
            fallbackSoortId = soortId,
            fallbackAmount = amount,
            fallbackAantalterug = aantalterug,
            fallbackTijdstip = tijdstip,
            fallbackGeslacht = geslacht,
            fallbackLeeftijd = leeftijd,
            fallbackKleed = kleed,
            fallbackOpmerkingen = opmerkingen,
            payloadRecord = payloadRecord
        )

        synchronized(pendingRecords) { pendingRecords[idx] = updated }
        if (::viewModel.isInitialized) {
            viewModel.setPendingRecords(synchronized(pendingRecords) { pendingRecords.toList() })
        }
        val recordsSnapshot = synchronized(pendingRecords) { pendingRecords.toList() }
        ensureTilesExistForRecords(recordsSnapshot)
        tegelBeheer.recalculateCountsFromRecords(recordsSnapshot)
        // persistEnvelopeAsync() // UITGESCHAKELD
        syncDailyTotalsRecord(updated)
        syncDailyObservationRecord(updated)

        if (hasClientAnnotationChanges(existing, updated) || existing.aantal != updated.aantal || existing.aantalterug != updated.aantalterug) {
            upsertFinalObservationRow(buildFinalObservationRow(updated, isClientOrigin = true, clientLogPrefix = clientLogPrefix))
        }
    }

    private fun buildFinalObservationRow(
        item: ServerTellingDataItem,
        deliveryState: ObservationDeliveryState = ObservationDeliveryState.NONE,
        isClientOrigin: Boolean = false,
        clientLogPrefix: String? = null
    ): SpeechLogRow {
        val name = resolveSpeciesName(item.soortid)
        val main = item.aantal.toIntOrNull() ?: 0
        val ret = item.aantalterug.toIntOrNull() ?: 0
        val normalizedPrefix = clientLogPrefix?.trim().orEmpty().ifBlank {
            if (isClientOrigin) getString(R.string.mc_log_client_prefix).trim().removePrefix("[").removeSuffix("]") else ""
        }
        val prefix = normalizedPrefix.takeIf { it.isNotBlank() }?.let { "[$it] " } ?: ""
        val statusSuffix = when (deliveryState) {
            ObservationDeliveryState.PENDING -> " ⏳"
            ObservationDeliveryState.RECEIVED -> " ✅"
            ObservationDeliveryState.REJECTED -> " ❌"
            ObservationDeliveryState.NONE -> ""
        }
        val annotationSuffix = if (hasAnnotationData(item)) " " else ""
        val display = when {
            main > 0 && ret <= 0 -> "$prefix$name -> +$main$annotationSuffix$statusSuffix"
            main <= 0 && ret > 0 -> "$prefix$name (tegenrichting) -> +$ret$annotationSuffix$statusSuffix"
            else -> "$prefix$name -> +$main / +$ret$annotationSuffix$statusSuffix"
        }
        val isUploadedToServer = UploadedObservationStateStore.isCurrentRecordUploaded(
            context = this,
            tellingId = item.tellingid,
            record = item
        )
        return SpeechLogRow(
            ts = item.tijdstip.toLongOrNull() ?: (System.currentTimeMillis() / 1000L),
            tekst = display,
            bron = "final",
            isPending = deliveryState == ObservationDeliveryState.PENDING,
            recordLocalId = item.idLocal,
            rowKey = item.idLocal.ifBlank { item.groupid },
            deliveryState = deliveryState,
            isClientOrigin = normalizedPrefix.isNotBlank() || isClientOrigin,
            isUploadedToServer = isUploadedToServer
        )
    }

    private fun hasAnnotationData(item: ServerTellingDataItem): Boolean {
        return item.leeftijd.isNotBlank() ||
            item.geslacht.isNotBlank() ||
            item.kleed.isNotBlank() ||
            item.location.isNotBlank() ||
            item.height.isNotBlank() ||
            item.sightingdirection.isNotBlank() ||
            item.opmerkingen.isNotBlank() ||
            item.markeren == "1" ||
            item.markerenlokaal == "1" ||
            item.teltype.isNotBlank()
    }

    private fun observeUploadedObservationState() {
        lifecycleScope.launch {
            UploadedObservationStateStore.updates().collect { changedTellingId ->
                val activeTellingId = prefs.getString("pref_telling_id", null).orEmpty()
                    .ifBlank { synchronized(pendingRecords) { pendingRecords.firstOrNull()?.tellingid }.orEmpty() }
                if (activeTellingId.isBlank() || activeTellingId != changedTellingId) return@collect
                refreshFinalObservationUploadMarkers()
            }
        }
    }

    private fun refreshFinalObservationUploadMarkers() {
        val recordsById = synchronized(pendingRecords) {
            pendingRecords
                .filter { it.idLocal.isNotBlank() }
                .associateBy { it.idLocal }
        }
        if (recordsById.isEmpty()) return

        val currentFinals = logManager.getFinals()
        if (currentFinals.isEmpty()) return

        val updatedFinals = currentFinals.map { existing ->
            val recordId = existing.recordLocalId.orEmpty()
            val record = recordsById[recordId] ?: return@map existing
            buildFinalObservationRow(
                item = record,
                deliveryState = existing.deliveryState,
                isClientOrigin = existing.isClientOrigin,
                clientLogPrefix = mcClientLogPrefixByRecordId[recordId] ?: extractClientLogPrefix(existing.tekst)
            )
        }

        if (updatedFinals == currentFinals) return

        logManager.setFinals(updatedFinals)
        val updatedPartials = logManager.getPartials()
        lifecycleScope.launch(Dispatchers.Main) {
            if (::viewModel.isInitialized) {
                viewModel.setFinals(updatedFinals)
                viewModel.setPartials(updatedPartials)
            } else {
                uiManager.updateFinals(updatedFinals)
                uiManager.updatePartials(updatedPartials)
            }
        }
    }

    private fun extractClientLogPrefix(displayText: String): String? {
        if (!displayText.startsWith("[")) return null
        val endIdx = displayText.indexOf("] ")
        if (endIdx <= 1) return null
        return displayText.substring(1, endIdx)
    }

    private fun resolveClientLogPrefix(clientId: String): String {
        return mcMasterServer?.getClientLogPrefix(clientId).orEmpty().ifBlank {
            "CL:${clientId.take(6)}"
        }
    }

    private fun updateClientFinalObservationRow(
        item: ServerTellingDataItem,
        deliveryState: ObservationDeliveryState = existingDeliveryStateForRecord(item.idLocal)
    ) {
        upsertFinalObservationRow(buildFinalObservationRow(item = item, deliveryState = deliveryState, isClientOrigin = false))
    }

    private fun existingDeliveryStateForRecord(recordLocalId: String): ObservationDeliveryState {
        return logManager.getFinals().firstOrNull { it.recordLocalId == recordLocalId }?.deliveryState
            ?: ObservationDeliveryState.NONE
    }

    private fun markClientObservationStateByEventId(eventId: String, state: ObservationDeliveryState) {
        val recordLocalId = mcClientRecordIdByEvent[eventId].orEmpty()
        if (recordLocalId.isBlank()) return
        val currentRecord = synchronized(pendingRecords) { pendingRecords.firstOrNull { it.idLocal == recordLocalId } }
        if (currentRecord != null) {
            updateClientFinalObservationRow(currentRecord, state)
            return
        }
        val existingRow = logManager.getFinals().firstOrNull { it.recordLocalId == recordLocalId } ?: return
        upsertFinalObservationRow(existingRow.copy(isPending = state == ObservationDeliveryState.PENDING, deliveryState = state))
    }

    private fun ensureTilesExistForRecords(records: List<ServerTellingDataItem>) {
        records.asSequence()
            .map { it.soortid }
            .filter { it.isNotBlank() }
            .distinct()
            .forEach { soortId ->
                tegelBeheer.voegSoortToeIndienNodig(soortId, resolveSpeciesName(soortId), 0)
            }
    }

    private fun resolveSpeciesName(soortId: String): String {
        tegelBeheer.findNaamBySoortId(soortId)?.let { return it }
        return runCatching {
            com.yvesds.vt5.features.serverdata.model.ServerDataCache.getCachedOrNull()?.speciesById?.get(soortId)?.soortnaam
        }.getOrNull().orEmpty().ifBlank { soortId }
    }

    private fun buildMasterClientRecord(
        idLocal: String,
        tellingId: String,
        fallbackSoortId: String,
        fallbackAmount: Int,
        fallbackAantalterug: Int,
        fallbackTijdstip: Long,
        fallbackGeslacht: String,
        fallbackLeeftijd: String,
        fallbackKleed: String,
        fallbackOpmerkingen: String,
        groupId: String,
        uploadtijdstip: String,
        payloadRecord: ServerTellingDataItem?
    ): ServerTellingDataItem {
        val source = payloadRecord
        val soortid = source?.soortid?.ifBlank { fallbackSoortId } ?: fallbackSoortId
        val aantal = source?.aantal?.ifBlank { fallbackAmount.toString() } ?: fallbackAmount.toString()
        val aantalterug = source?.aantalterug?.ifBlank { fallbackAantalterug.toString() } ?: fallbackAantalterug.toString()
        val lokaal = source?.lokaal ?: "0"
        return ServerTellingDataItem(
            idLocal = idLocal,
            tellingid = tellingId,
            soortid = soortid,
            aantal = aantal,
            richting = source?.richting ?: "",
            aantalterug = aantalterug,
            richtingterug = source?.richtingterug ?: "",
            sightingdirection = source?.sightingdirection ?: "",
            lokaal = lokaal,
            aantal_plus = source?.aantal_plus ?: "0",
            aantalterug_plus = source?.aantalterug_plus ?: "0",
            lokaal_plus = source?.lokaal_plus ?: "0",
            markeren = source?.markeren ?: "0",
            markerenlokaal = source?.markerenlokaal ?: "0",
            geslacht = source?.geslacht ?: fallbackGeslacht,
            leeftijd = source?.leeftijd ?: fallbackLeeftijd,
            kleed = source?.kleed ?: fallbackKleed,
            opmerkingen = source?.opmerkingen ?: fallbackOpmerkingen,
            trektype = source?.trektype ?: "",
            teltype = source?.teltype ?: "",
            location = source?.location ?: "",
            height = source?.height ?: "",
            tijdstip = source?.tijdstip?.ifBlank { fallbackTijdstip.toString() } ?: fallbackTijdstip.toString(),
            groupid = source?.groupid?.ifBlank { groupId } ?: groupId,
            uploadtijdstip = source?.uploadtijdstip?.ifBlank { uploadtijdstip } ?: uploadtijdstip,
            totaalaantal = source?.totaalaantal?.ifBlank { calculateObservationTotal(aantal, aantalterug, lokaal) }
                ?: calculateObservationTotal(aantal, aantalterug, lokaal)
        )
    }

    private fun mergeClientRecordUpdate(
        existing: ServerTellingDataItem,
        fallbackSoortId: String,
        fallbackAmount: Int,
        fallbackAantalterug: Int,
        fallbackTijdstip: Long,
        fallbackGeslacht: String,
        fallbackLeeftijd: String,
        fallbackKleed: String,
        fallbackOpmerkingen: String,
        payloadRecord: ServerTellingDataItem?
    ): ServerTellingDataItem {
        val source = payloadRecord
        val soortid = source?.soortid?.ifBlank { fallbackSoortId } ?: fallbackSoortId
        val aantal = source?.aantal?.ifBlank { fallbackAmount.toString() } ?: fallbackAmount.toString()
        val aantalterug = source?.aantalterug?.ifBlank { fallbackAantalterug.toString() } ?: fallbackAantalterug.toString()
        val lokaal = source?.lokaal ?: existing.lokaal
        return existing.copy(
            soortid = soortid,
            aantal = aantal,
            richting = source?.richting ?: existing.richting,
            aantalterug = aantalterug,
            richtingterug = source?.richtingterug ?: existing.richtingterug,
            sightingdirection = source?.sightingdirection ?: existing.sightingdirection,
            lokaal = lokaal,
            aantal_plus = source?.aantal_plus ?: existing.aantal_plus,
            aantalterug_plus = source?.aantalterug_plus ?: existing.aantalterug_plus,
            lokaal_plus = source?.lokaal_plus ?: existing.lokaal_plus,
            markeren = source?.markeren ?: existing.markeren,
            markerenlokaal = source?.markerenlokaal ?: existing.markerenlokaal,
            geslacht = source?.geslacht ?: fallbackGeslacht,
            leeftijd = source?.leeftijd ?: fallbackLeeftijd,
            kleed = source?.kleed ?: fallbackKleed,
            opmerkingen = source?.opmerkingen ?: fallbackOpmerkingen,
            trektype = source?.trektype ?: existing.trektype,
            teltype = source?.teltype ?: existing.teltype,
            location = source?.location ?: existing.location,
            height = source?.height ?: existing.height,
            tijdstip = source?.tijdstip?.ifBlank { fallbackTijdstip.toString() } ?: fallbackTijdstip.toString(),
            uploadtijdstip = source?.uploadtijdstip ?: existing.uploadtijdstip,
            totaalaantal = source?.totaalaantal?.ifBlank { calculateObservationTotal(aantal, aantalterug, lokaal) }
                ?: calculateObservationTotal(aantal, aantalterug, lokaal)
        )
    }

    private fun hasClientAnnotationChanges(existing: ServerTellingDataItem, updated: ServerTellingDataItem): Boolean {
        return existing.geslacht != updated.geslacht ||
            existing.leeftijd != updated.leeftijd ||
            existing.kleed != updated.kleed ||
            existing.opmerkingen != updated.opmerkingen ||
            existing.location != updated.location ||
            existing.height != updated.height ||
            existing.lokaal != updated.lokaal
    }

    private fun calculateObservationTotal(aantal: String, aantalterug: String, lokaal: String): String {
        return ((aantal.toIntOrNull() ?: 0) + (aantalterug.toIntOrNull() ?: 0) + (lokaal.toIntOrNull() ?: 0)).toString()
    }

    private fun refreshTileRows(sourceTiles: List<SoortTile>? = null) {
        if (!::tilesAdapter.isInitialized) return
        val tiles = sourceTiles ?: tegelBeheer.getTiles()
        val rows = tiles.map { tile ->
            val pendingMain = if (::tileTapAggregationManager.isInitialized) {
                tileTapAggregationManager.getPendingMainCount(tile.soortId)
            } else {
                0
            }
            SoortRow(
                soortId = tile.soortId,
                naam = tile.naam,
                countMain = tile.countMain,
                countReturn = tile.countReturn,
                pendingMainCount = pendingMain
            )
        }
        tilesAdapter.submitList(rows)
        if (::viewModel.isInitialized) {
            viewModel.setTiles(rows)
        }
        broadcastTileSyncIfMaster(tiles)
    }

    private fun addOrReplacePendingRecord(item: ServerTellingDataItem) {
        synchronized(pendingRecords) {
            val index = pendingRecords.indexOfFirst { it.idLocal == item.idLocal }
            if (index >= 0) {
                pendingRecords[index] = item
            } else {
                pendingRecords.add(item)
            }
            if (::viewModel.isInitialized) {
                viewModel.setPendingRecords(pendingRecords.toList())
            }
        }
        // persistEnvelopeAsync() // UITGESCHAKELD: Room is nu de bron tijdens het tellen
        syncDailyTotalsRecord(item)
        syncDailyObservationRecord(item, refreshOrder = false)

        // Room shadow write - CRUCIAL voor Hybride Systeem
        lifecycleScope.launch(Dispatchers.IO) {
            hybridRepository.saveWaarnemingToRoom(item)
        }
    }

    private fun persistEnvelopeAsync() {
        lifecycleScope.launch(Dispatchers.IO) {
            try {
                val envelope = viewModel.activeEnvelope.value
                if (envelope != null) {
                    envelopePersistence.saveEnvelopeWithRecords(envelope.data)
                } else {
                    val records = synchronized(pendingRecords) { pendingRecords.toList() }
                    envelopePersistence.saveEnvelopeWithRecords(records)
                }
            } catch (ex: Exception) {
                Log.w(TAG, "Envelope persistence failed: ${ex.message}", ex)
            }
        }
    }

    private suspend fun backupObservationRecord(item: ServerTellingDataItem) {
        withContext(Dispatchers.IO) {
            try {
                backupManager.writeRecordBackupSaf(item.tellingid, item)
                    ?: backupManager.writeRecordBackupInternal(item.tellingid, item)
            } catch (ex: Exception) {
                Log.w(TAG, "Record backup failed during tile tap aggregation: ${ex.message}", ex)
            }
        }
    }

    private suspend fun commitTileTapAggregate(
        aggregate: TileTapAggregationManager.PendingAggregate,
        finalizedAtEpochSeconds: Long
    ) {
        removeFinalObservationRowByKey(aggregate.pendingKey)

        val record = speciesManager.buildObservationRecord(
            soortId = aggregate.speciesId,
            amountMain = aggregate.totalMainCount,
            amountReturn = 0,
            explicitTimestampSeconds = finalizedAtEpochSeconds
        )

        if (record != null) {
            addOrReplacePendingRecord(record)

            if (AutoAnnotationConfigManager.isAutoAnnotate(record.soortid)) {
                val displayName = resolveSpeciesName(record.soortid)
                val countDisplay = if ((record.aantalterug.toIntOrNull() ?: 0) > 0) "+${record.aantalterug} (terug)" else "+${record.aantal}"
                annotationHandler.enqueueAutoAnnotation(record.idLocal, "$displayName $countDisplay")
            }

            backupObservationRecord(record)
            queueClientObservationIfNeeded(record)
            val deliveryState = if (isClientFlowLocked()) {
                ObservationDeliveryState.PENDING
            } else {
                ObservationDeliveryState.NONE
            }
            updateClientFinalObservationRow(record, deliveryState)
        } else {
            addLog("Gegroepeerde tegelwaarneming kon niet als record opgeslagen worden", "systeem")
        }

        if (record == null) {
            upsertFinalObservationRow(
                SpeechLogRow(
                    ts = finalizedAtEpochSeconds,
                    tekst = "${aggregate.displayName} -> +${aggregate.totalMainCount}",
                    bron = "final",
                    isPending = false,
                    rowKey = aggregate.pendingKey
                )
            )
            refreshTileRows()
            return
        }
        refreshDailyObservationOrdering()
    }
}

package com.yvesds.vt5.ai

import android.content.Context
import android.util.Log
import com.yvesds.vt5.core.database.VoiceTallyDatabase
import com.yvesds.vt5.core.opslag.SaFStorageHelper
import com.yvesds.vt5.core.database.ui.SpeciesNameResolver
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import java.util.*
import kotlin.math.*

/**
 * Trainer - Plan B: Bio-Statistische Intelligentie (BSI) Profiler.
 * In plaats van TensorFlow te trainen, bouwen we razendsnelle statistische profielen 
 * in de Room DB en het geheugen. Dit is 100x sneller en vederlicht.
 */
class Trainer(private val context: Context, private val modelStore: ModelStore) {
    private val TAG = "BsiProfiler"

    suspend fun runOnDeviceTraining(onProgress: (String, Int, Int) -> Unit) = withContext(Dispatchers.Default) {
        try {
            Log.i(TAG, "Start BSI Training...")
            onProgress("Historische data analyseren...", 5, 100)

            val db = VoiceTallyDatabase.getDatabase(context)
            val dao = db.tellingDao()
            val preparer = TrainingDataPreparer(context)

            // 1. Haal alle unieke soorten op (dit bepaalt de output van ons netwerk)
            val allSpecies = dao.getAllSpeciesIds().sorted()
            val numSpecies = allSpecies.size.coerceAtLeast(1)

            // 2. Laad bestaand model of start vers
            onProgress("Bestaande hersencellen laden...", 10, 100)
            val engine = modelStore.loadNeuralEngine(numSpecies)

            // 3. Haal data op uit Room
            onProgress("Data voorbereiden vanuit Room DB...", 20, 100)
            val trainingSamples = preparer.getTrainingDataFromRoom { msg, curr, total ->
                onProgress(msg, curr, total)
            }

            if (trainingSamples.isEmpty()) {
                onProgress("Geen data om van te leren.", 0, 0)
                return@withContext
            }

            // 4. De Trainings-lus (De AI leert nu echt!)
            val total = trainingSamples.size
            var count = 0

            trainingSamples.forEachIndexed { index, sample ->
                engine.train(sample.features, sample.labelIndex)

                // Minder frequente updates om de Main thread te ontlasten (was 500)
                if (index % 2500 == 0 || index == total - 1) {
                    count = index
                    val perc = (20 + (index.toFloat() / total * 75)).toInt()
                    onProgress("AI leert van waarnemingen...\n($index van $total)", perc, 100)
                }
            }

            // 5. Sla de nieuwe gewichten op
            onProgress("Nieuwe ervaringen opslaan...", 95, 100)
            modelStore.saveNeuralEngine(engine)
            // Persistente labels zodat label-index mapping reproduceerbaar is
            try {
                modelStore.saveModelLabels(allSpecies)
            } catch (_: Exception) { /* Best effort - niet kritisch */ }

            // 6. Voer Retroactieve Piek-Analyse uit (Knowledge Base)
            onProgress("Meteorologische vingerafdrukken berekenen...", 96, 100)
            val kbManager = ExpertKnowledgeManager(context)
            kbManager.analyzeHistoricalPeaks { msg, curr, total ->
                onProgress(msg, curr, total)
            }

            // BSI 4.0: Bouw uurs-distributie profielen (Gouden Mal)
            onProgress("Uurs-distributie profielen (Gouden Mal) berekenen...", 97, 100)
            buildHourlyProfiles(allSpecies)

            // 7. Genereer Wetenschappelijke Taxonomie JSON
            onProgress("Wetenschappelijke taxonomie bijwerken...", 98, 100)
            val taxonomyManager = TaxonomyManager(context)
            taxonomyManager.generateActiveTaxonomyJson()

            // 8. Vogelbeelden archiveren (PROACTIEF & GEOPTIMALISEERD)
            val snapshot = try { com.yvesds.vt5.features.serverdata.model.ServerDataCache.getOrLoad(context) } catch(_: Exception) { null }
            if (snapshot != null) {
                val cachedLatinNames = dao.getAllCachedLatinNames().toSet()
                val uniqueSids = trainingSamples.map { allSpecies[it.labelIndex] }.distinct()

                // Bepaal welke beelden we echt nog missen
                val toFetch = uniqueSids.mapNotNull { sid ->
                    val latin = snapshot.speciesById[sid]?.latin ?: return@mapNotNull null
                    val clean = SpeciesImageHelper.cleanLatinName(latin)
                    if (clean.isNotEmpty() && !cachedLatinNames.contains(clean)) {
                        Pair(sid, latin)
                    } else null
                }

                val totalToFetch = toFetch.size
                if (totalToFetch > 0) {
                    toFetch.forEachIndexed { i, (sid, latin) ->
                        val name = snapshot.speciesById[sid]?.soortnaam ?: sid
                        if (i % 2 == 0 || i == totalToFetch - 1) { // Iets vaker updates voor nieuwe beelden
                            onProgress("Nieuwe beelden archiveren: $name (${i+1}/$totalToFetch)...", 99, 100)
                        }
                        SpeciesImageHelper.getThumbnail(latin)
                        delay(60) // Iets meer adempauze voor nieuwe fetches
                    }
                } else {
                    Log.i(TAG, "Alle vogelbeelden (${uniqueSids.size}) zijn reeds aanwezig in de cache.")
                    onProgress("Vogelbeelden cache is up-to-date.", 99, 100)
                }
            }

            // 8. VUL DE SCIENTIFIC VAULT (HD-Curves & Pieken)
            onProgress("Wetenschappelijke kluis verzegelen...", 99, 100)
            fillScientificVault(onProgress)

            onProgress("Training succesvol voltooid!", 100, 100)
            Log.i(TAG, "Neural training voltooid.")
            delay(1000)

        } catch (e: Exception) {
            Log.e(TAG, "Training mislukt: ${e.message}", e)
            onProgress("Fout bij trainen: ${e.message}", 0, 0)
        }
    }

    private suspend fun fillScientificVault(onProgress: (String, Int, Int) -> Unit) = withContext(Dispatchers.IO) {
        try {
            val db = VoiceTallyDatabase.getDatabase(context)
            val dao = db.tellingDao()
            val saf = SaFStorageHelper(context)

            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: "{}"
            val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)

            // BEPAAL HOOFDTELPOST (De allereerste in het JSON bestand)
            val primarySite = root.locaties.firstOrNull() ?: return@withContext
            val clusterIds = getLocalSiteClusterIds(saf, primarySite.latitude, primarySite.longitude) ?: listOf(primarySite.telpostid)
            val primaryClusterId = primarySite.telpostid

            val speciesIds = dao.getAllSpeciesIds()
            val total = speciesIds.size

            speciesIds.forEachIndexed { index, sid ->
                if (index % 10 == 0) {
                    onProgress("Vault verzegelen: Soort ${index+1}/$total...", 99, 100)
                }

                // Gebruik de volledige cluster voor de distributie
                val distribution = dao.getSpeciesDailyDistribution(sid, clusterIds)
                val rawCurve = FloatArray(366)
                distribution.forEach { if (it.day in 1..366) rawCurve[it.day - 1] = it.count.toFloat() }

                // GEEN SMOOTHING: Sla ruwe data op voor maximale eerlijkheid
                val curveString = rawCurve.joinToString("|") { String.format(Locale.US, "%.4f", it) }

                // Piek berekening
                val peakSpring = findPeakInPeriod(rawCurve, 1, 166)
                val peakAutumn = findPeakInPeriod(rawCurve, 167, 366)

                dao.insertDailyAnalysisVault(com.yvesds.vt5.core.database.entities.SpeciesPhenologyVault(
                    speciesId = sid,
                    clusterId = primaryClusterId, // Altijd gekoppeld aan de hoofdtelpost
                    dailyBphSeries = curveString,
                    peakSpring = peakSpring,
                    peakAutumn = peakAutumn
                ))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Vault failure: ${e.message}")
        }
    }

    private fun findPeakInPeriod(curve: FloatArray, startDay: Int, endDay: Int): String {
        var maxVal = -1f; var peakDay = -1
        for (i in (startDay - 1) until kotlin.math.min(endDay, curve.size)) {
            if (curve[i] > maxVal) { maxVal = curve[i]; peakDay = i + 1 }
        }
        if (peakDay == -1 || maxVal <= 0f) return "[onbekend]"
        val cal = Calendar.getInstance().apply { set(Calendar.DAY_OF_YEAR, peakDay) }
        return java.text.SimpleDateFormat("d MMMM", Locale("nl", "BE")).format(cal.time)
    }

    private fun getLocalSiteClusterIds(saf: SaFStorageHelper, lat: Double, lon: Double): List<String>? {
        return try {
            val jsonStr = saf.readServerDataFile("telpost_locaties.json") ?: return null
            val root = com.yvesds.vt5.VT5App.json.decodeFromString<com.yvesds.vt5.core.database.entities.TelpostLocatiesRoot>(jsonStr)
            root.locaties.filter { 
                val r = 6371.0
                val dLat = Math.toRadians(it.latitude - lat); val dLon = Math.toRadians(it.longitude - lon)
                val a = kotlin.math.sin(dLat/2).pow(2) + kotlin.math.cos(Math.toRadians(lat)) * kotlin.math.cos(Math.toRadians(it.latitude)) * kotlin.math.sin(dLon/2).pow(2)
                r * 2 * kotlin.math.atan2(kotlin.math.sqrt(a), kotlin.math.sqrt(1 - a)) <= 35.0 
            }.map { it.telpostid }
        } catch (_: Exception) { null }
    }

    /**
     * BSI 4.0: Berekent de uurs-distributie profielen op basis van de "Anchor Sites".
     */
    private suspend fun buildHourlyProfiles(allSpecies: List<String>) = withContext(Dispatchers.IO) {
        val db = VoiceTallyDatabase.getDatabase(context)
        val dao = db.tellingDao()
        val anchorSites = AiConfig.ANCHOR_SITE_IDS

        val currentKb = modelStore.loadExpertKnowledge() ?: ExpertKnowledgeBase()
        val newProfiles = mutableMapOf<String, List<Float>>()

        allSpecies.forEach { sid ->
            val dist = dao.getSpeciesHourlyDistribution(anchorSites, sid)
            if (dist.isNotEmpty()) {
                val hourlyArray = FloatArray(24)
                var total = 0L
                dist.forEach { row ->
                    val h = row.hour.toIntOrNull() ?: return@forEach
                    if (h in 0..23) {
                        hourlyArray[h] = row.count.toFloat()
                        total += row.count
                    }
                }
                if (total > 0) {
                    newProfiles[sid] = hourlyArray.map { it / total }
                }
            }
        }

        modelStore.saveExpertKnowledge(currentKb.copy(hourlyProfiles = newProfiles))
    }

    // Placeholder voor data-modellen die elders gebruikt worden
    data class TrainingSample(val features: FloatArray, val labelIndex: Int)
}

