 */
object VicoLineChartHelper {

    private val axisLabel = TextComponent(
        color = Color.WHITE,
        textSizeSp = 9f,
    )

    private val axisLine = LineComponent(
        fill = Fill(Color.LTGRAY),
        thicknessDp = 1f,
    )

    private val axisTick = LineComponent(
        fill = Fill(Color.LTGRAY),
        thicknessDp = 1f,
    )

    private val axisGuideline = LineComponent(
        fill = Fill(Color.argb(120, 180, 180, 180)),
        thicknessDp = 0.6f,
    )

    private val monthLetterByWeekStart = mapOf(
        1 to "J", 5 to "F", 9 to "M", 13 to "A", 17 to "M", 21 to "J",
        25 to "J", 29 to "A", 33 to "S", 37 to "O", 41 to "N", 45 to "D", 49 to "D"
    )

    /** Bouw één of meerdere lijnlagen met standaard cubic-bezier interpolatie. */
    fun createLineLayer(vararg lineColors: Int): LineCartesianLayer {
        val lines = lineColors.map { color ->
            val fill = Fill(color)
            LineCartesianLayer.Line(fill = LineCartesianLayer.LineFill.single(fill))
        }

        return LineCartesianLayer(
            LineCartesianLayer.LineProvider.series(*lines.toTypedArray()),
            pointSpacingDp = 2f,
        )
    }

    /** Create a dedicated LineCartesianLayer for beaufort values, fixed to 0..maxBeaufort on the Y axis */
    fun createBeaufortLineLayer(maxBeaufort: Double, beaufortColor: Int, alpha: Int = 140): LineCartesianLayer {
        // Apply requested alpha to the provided color so the beaufort line can be semi-transparent
        val a = alpha.coerceIn(0, 255)
        val withAlpha = Color.argb(a, Color.red(beaufortColor), Color.green(beaufortColor), Color.blue(beaufortColor))
        val fill = Fill(withAlpha)
        val line = LineCartesianLayer.Line(fill = LineCartesianLayer.LineFill.single(fill))

        // Use a fixed range provider for Y (0..maxBeaufort). X range will remain automatic.
        val rangeProvider = CartesianLayerRangeProvider.fixed(
            /* minX */ null,
            /* maxX */ null,
            /* minY */ 0.0,
            /* maxY */ maxBeaufort,
        )

        return LineCartesianLayer(
            LineCartesianLayer.LineProvider.series(line),
            rangeProvider = rangeProvider,
            verticalAxisPosition = Axis.Position.Vertical.End,
        )
    }

    /**
     * Labels enkel per maand (ongeveer om de 4 weken): week 1, 5, 9, ...
     * We tonen enkel de maandletter.
     */
    fun createMonthLabelAxis(): HorizontalAxis<Axis.Position.Horizontal.Bottom> {
        val monthFormatter = CartesianValueFormatter { _, value, _ ->
            val week = value.toInt() + 1
            monthLetterByWeekStart[week] ?: "?"
        }

        return HorizontalAxis.bottom(
            line = axisLine,
            label = axisLabel,
            valueFormatter = monthFormatter,
            tick = axisTick,
            tickLengthDp = 4f,
            guideline = axisGuideline,
            itemPlacer = HorizontalAxis.ItemPlacer.aligned(spacing = 4, offset = 0),
        )
    }

    /** Korte verticale streepjes voor elke week, zonder labels. */
    fun createWeeklyTickAxis(): HorizontalAxis<Axis.Position.Horizontal.Top> {
        return HorizontalAxis.top(
            line = axisLine,
            label = null,
            tick = axisTick,
            tickLengthDp = 4f,
            guideline = null,
            itemPlacer = HorizontalAxis.ItemPlacer.aligned(spacing = 1, offset = 0),
        )
    }

    fun createCountAxis(): VerticalAxis<Axis.Position.Vertical.Start> {
        val formatter = CartesianValueFormatter { _, value, _ ->
            // Display counts as whole numbers, no decimals
            String.format(java.util.Locale.getDefault(), "%.0f", value)
        }

        return VerticalAxis.start(
            line = axisLine,
            label = axisLabel,
            valueFormatter = formatter,
            tick = axisTick,
            tickLengthDp = 4f,
            guideline = axisGuideline,
            itemPlacer = VerticalAxis.ItemPlacer.count(count = { 6 }),
        )
    }

    fun createBeaufortAxis(): VerticalAxis<Axis.Position.Vertical.End> {
        val formatter = CartesianValueFormatter { _, value, _ ->
            // Beaufort scale: show as whole numbers (0..7)
            String.format(java.util.Locale.getDefault(), "%.0f", value)
        }

        return VerticalAxis.end(
            line = axisLine,
            label = axisLabel,
            valueFormatter = formatter,
            tick = axisTick,
            tickLengthDp = 4f,
            guideline = null,
            // Prefer more ticks for the beaufort axis so integer steps are visible
            itemPlacer = VerticalAxis.ItemPlacer.count(count = { 8 }),
        )
    }
}

// app/build.gradle.kts
import java.util.Properties

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.serialization") version "2.0.21"
    id("org.jetbrains.kotlin.kapt")
    id("kotlin-parcelize")
}

val versionPropertiesFile = rootProject.file("app/version.properties")
val versionProperties = Properties().apply {
    if (versionPropertiesFile.exists()) {
        versionPropertiesFile.inputStream().use { load(it) }
    }
}

fun parseSemver(version: String): Triple<Int, Int, Int> {
    val match = Regex("^(\\d+)\\.(\\d+)\\.(\\d+)$").matchEntire(version)
        ?: error("VERSION_NAME moet semver zijn (x.y.z), maar kreeg: $version")
    return Triple(match.groupValues[1].toInt(), match.groupValues[2].toInt(), match.groupValues[3].toInt())
}

fun semverToVersionCode(version: String): Int {
    val (major, minor, patch) = parseSemver(version)
    return major * 10000 + minor * 100 + patch
}

val resolvedVersionName =
    (project.findProperty("VT_VERSION_NAME") as String?)
        ?: versionProperties.getProperty("VERSION_NAME")
        ?: "2.2.0"

val resolvedVersionCode =
    (project.findProperty("VT_VERSION_CODE") as String?)?.toIntOrNull()
        ?: semverToVersionCode(resolvedVersionName)

android {
    namespace = "com.yvesds.vt5"
    compileSdk = 35
    ndkVersion = "28.2.13676358"

    defaultConfig {
        applicationId = "com.yvesds.vt5"
        minSdk = 33
        targetSdk = 35
        versionCode = resolvedVersionCode
        versionName = resolvedVersionName
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"

        // Beperk ABIs tot ARM (64-bit en 32-bit). 
        // Dit verwijdert x86 en x86_64 native libs (voor emulators), wat de APK grootte 
        // aanzienlijk verkleint.
        ndk {
            abiFilters.add("armeabi-v7a")
            abiFilters.add("arm64-v8a")
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
        debug {
            // Enable minification and resource shrinking for debug builds as well
            // so that locally produced APKs are smaller when you need that.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
    }

    buildFeatures {
        viewBinding = true
        compose = false
    }

    packaging {
        resources { excludes += "/META-INF/{AL2.0,LGPL2.1}" }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions { jvmTarget = "17" }
}

dependencies {
    implementation("androidx.core:core-ktx:1.13.1")
    implementation("androidx.appcompat:appcompat:1.7.0")
    implementation("androidx.activity:activity-ktx:1.9.2")

    implementation("com.google.android.material:material:1.12.0")
    implementation("androidx.lifecycle:lifecycle-runtime-ktx:2.8.6")
    implementation("androidx.recyclerview:recyclerview:1.3.2")

    // Flexbox voor wrap-content tiles in meerdere kolommen
    implementation("com.google.android.flexbox:flexbox:3.0.0")

    implementation("androidx.documentfile:documentfile:1.0.1")
    implementation("androidx.security:security-crypto:1.1.0-alpha06")

    implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.7.3")
    implementation("org.jetbrains.kotlinx:kotlinx-serialization-protobuf:1.7.3")
    implementation("org.jetbrains.kotlinx:kotlinx-serialization-cbor:1.7.3")

    implementation("com.squareup.okhttp3:okhttp:4.12.0")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0")
    implementation("com.journeyapps:zxing-android-embedded:4.3.0")

    // WorkManager
    implementation("androidx.work:work-runtime-ktx:2.8.1")

    // DataStore
    implementation("androidx.datastore:datastore-preferences:1.1.1")

    // Room Database
    val roomVersion = "2.8.4"
    implementation("androidx.room:room-runtime:$roomVersion")
    implementation("androidx.room:room-ktx:$roomVersion")
    implementation("androidx.room:room-paging:$roomVersion")
    kapt("androidx.room:room-compiler:$roomVersion")
    // Voor Kotlin: gebruik ksp of kapt (VT5 gebruikt kapt of standaard annotationProcessor)
    // Gezien de huidige configuratie voegen we kapt toe als plugin indien nodig, 
    // maar we proberen eerst de standaard annotationProcessor voor Room.

    implementation("androidx.media:media:1.7.1")

    // Vico Charts
    implementation("com.patrykandpatrick.vico:core:2.0.0-beta.3")
    implementation("com.patrykandpatrick.vico:views:2.0.0-beta.3")
    // Paging 3 for incremental lists
    implementation("androidx.paging:paging-runtime-ktx:3.2.1")

    // Excel support (.xlsx) - Lightweight streaming reader
    implementation("org.dhatim:fastexcel-reader:0.18.0")
    implementation("stax:stax-api:1.0.1")

    // Kaart functionaliteit (OpenStreetMap)
    implementation("org.osmdroid:osmdroid-android:6.1.18")
}
// Tests uit
tasks.matching {
    it.name.startsWith("test", true) || it.name.startsWith("connectedAndroidTest", true)
}.configureEach { this.enabled = false }

tasks.register("printResolvedVersion") {
    group = "versioning"
    description = "Toont de versie die gebruikt wordt voor deze build."
    notCompatibleWithConfigurationCache("Leest script-variabelen voor versie-output")
    doLast {
        println("VT versionName=$resolvedVersionName")
        println("VT versionCode=$resolvedVersionCode")
    }
}

tasks.register("bumpPatchVersion") {
    group = "versioning"
    description = "Verhoogt patch van app/version.properties (x.y.z -> x.y.(z+1))."
    notCompatibleWithConfigurationCache("Schrijft versiegegevens weg naar version.properties")
    doLast {
        val props = Properties().apply {
            if (versionPropertiesFile.exists()) {
                versionPropertiesFile.inputStream().use { load(it) }
            }
        }
        val current = props.getProperty("VERSION_NAME") ?: "2.2.0"
        val (major, minor, patch) = parseSemver(current)
        val next = "$major.$minor.${patch + 1}"
        props.setProperty("VERSION_NAME", next)
        versionPropertiesFile.outputStream().use { out ->
            props.store(out, "VoiceTally app version")
        }
        println("VERSION_NAME bumped: $current -> $next")
        println("Derived VERSION_CODE: ${semverToVersionCode(next)}")
    }
}

tasks.named("assembleRelease") {
    mustRunAfter("bumpPatchVersion")
}

tasks.register("prepareRelease") {
    group = "versioning"
    description = "Verhoogt patchversie en bouwt daarna direct de release APK."
    notCompatibleWithConfigurationCache("Schrijft versiegegevens weg en start aansluitend een release build")
    dependsOn("bumpPatchVersion", "assembleRelease")
}

